const extraQuestions2 = [
  // ── ANIMALS ───────────────────────────────────────────────────────────────
  { category: "Animals", difficulty: "EASY", question: "What is the largest land animal on Earth?", options: JSON.stringify(["Hippopotamus","Giraffe","White Rhino","African Elephant"]), correctAnswer: "African Elephant", funFact: "African bush elephants can weigh up to 7 tons and stand 4 meters tall at the shoulder. They have the largest brains of any land animal and display remarkable intelligence — using tools, recognizing themselves in mirrors, and mourning their dead." },
  { category: "Animals", difficulty: "EASY", question: "Which bird is known for its ability to mimic human speech?", options: JSON.stringify(["Parrot","Mynah","Parrot","Crow"]), correctAnswer: "Parrot", funFact: "African Grey Parrots are considered the most intelligent birds. Alex, an African Grey studied by Dr. Irene Pepperberg, could identify 50 objects, count to 6, and understood concepts like 'same' and 'different.' He had a vocabulary of over 100 words." },
  { category: "Animals", difficulty: "EASY", question: "How many legs does a spider have?", options: JSON.stringify(["6","8","10","12"]), correctAnswer: "8", funFact: "Spiders have 8 legs and are arachnids, not insects (which have 6 legs). Most spiders have 8 eyes too, though some have fewer. There are about 45,000 known spider species, and every continent except Antarctica has spiders." },
  { category: "Animals", difficulty: "EASY", question: "What is the fastest land animal?", options: JSON.stringify(["Lion","Greyhound","Cheetah","Pronghorn"]), correctAnswer: "Cheetah", funFact: "Cheetahs can reach 112 km/h (70 mph) in short sprints. Unlike other big cats, they cannot roar — they purr instead. Cheetahs are the only cats that cannot retract their claws, giving them the grip needed for high-speed running." },
  { category: "Animals", difficulty: "EASY", question: "Which marine animal is known as the largest fish in the world?", options: JSON.stringify(["Blue Whale","Great White Shark","Whale Shark","Oarfish"]), correctAnswer: "Whale Shark", funFact: "Whale sharks can reach 18 meters in length and weigh over 20 tons, yet they eat only tiny plankton and small fish filtered through their huge mouths. Despite being so large, they are completely harmless to humans. Each whale shark has a unique pattern of spots — like a fingerprint." },
  { category: "Animals", difficulty: "EASY", question: "What is a group of lions called?", options: JSON.stringify(["Pack","Herd","Pride","Colony"]), correctAnswer: "Pride", funFact: "A lion pride typically has 10–15 members — females are the primary hunters while males defend the territory. Unlike other big cats, lions are social animals. Female lions in a pride often synchronize their pregnancies so cubs are raised together." },
  { category: "Animals", difficulty: "EASY", question: "Which animal has the longest neck?", options: JSON.stringify(["Camel","Llama","Ostrich","Giraffe"]), correctAnswer: "Giraffe", funFact: "A giraffe's neck can be 2 meters long yet has only 7 cervical vertebrae — the same number as humans. Their necks weigh about 270 kg. To drink water, giraffes must awkwardly splay their legs or bend them, making them vulnerable to predators." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which animal has three hearts and blue blood?", options: JSON.stringify(["Horseshoe Crab","Octopus","Squid","Nautilus"]), correctAnswer: "Octopus", funFact: "An octopus has 3 hearts (two pump blood to the gills, one to the body), 9 brains (one central plus one per arm), and blue blood (copper-based hemocyanin instead of iron-based hemoglobin). Two-thirds of their neurons are in their arms, which can act independently." },
  { category: "Animals", difficulty: "MEDIUM", question: "What is the only mammal capable of true flight?", options: JSON.stringify(["Flying squirrel","Bat","Flying lemur","Sugar glider"]), correctAnswer: "Bat", funFact: "Bats make up 20% of all mammal species. They navigate using echolocation — emitting ultrasonic pulses and interpreting echoes. Some bats can detect obstacles as thin as a human hair. Vampire bats are the only mammals that feed exclusively on blood." },
  { category: "Animals", difficulty: "MEDIUM", question: "How do starfish eat their prey?", options: JSON.stringify(["They use a tongue","They inject venom","They push their stomach outside their body","They swallow whole"]), correctAnswer: "They push their stomach outside their body", funFact: "Starfish (sea stars) evert (push out) their stomach through their mouth and into their prey, digest it externally, then pull the stomach back in. This allows them to eat prey too large to fit through their tiny mouth, like mussels and oysters." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which animal has the highest blood pressure of any living creature?", options: JSON.stringify(["Elephant","Giraffe","Blue Whale","Horse"]), correctAnswer: "Giraffe", funFact: "A giraffe's blood pressure is 2–3 times higher than a human's — necessary to pump blood up its 2-meter neck to the brain. Special valves and thick-walled blood vessels prevent their brain from exploding when they lower their heads to drink." },
  { category: "Animals", difficulty: "MEDIUM", question: "What animal can regrow its limbs?", options: JSON.stringify(["Salamander","Gecko","Chameleon","Iguana"]), correctAnswer: "Salamander", funFact: "Axolotl salamanders can regenerate entire limbs, portions of their heart and brain, and even parts of their eyes — with no scarring. Scientists are studying their regeneration mechanisms hoping to apply them to human medicine. Axolotls are critically endangered in the wild, found only in one lake system in Mexico." },
  { category: "Animals", difficulty: "HARD", question: "What is the name for a group of flamingos?", options: JSON.stringify(["Colony","Flamboyance","Flock","Stand"]), correctAnswer: "Flamboyance", funFact: "Flamingos get their pink color from carotenoid pigments in the algae and crustaceans they eat. A flamingo raised in captivity without these foods would actually turn white. Baby flamingos are born grey-white. They feed their chicks 'crop milk' — a secretion of their digestive system." },
  { category: "Animals", difficulty: "HARD", question: "Which animal has the most chromosomes?", options: JSON.stringify(["Human","Adder's tongue fern","Hermit crab","Atlas blue butterfly"]), correctAnswer: "Adder's tongue fern", funFact: "The Adder's tongue fern (Ophioglossum reticulatum) has about 1,260 chromosomes — the most of any organism. Humans have 46. Having more chromosomes doesn't indicate complexity; ferns, lobsters, and some butterflies have far more chromosomes than humans." },
  { category: "Animals", difficulty: "HARD", question: "How long can a tardigrade (water bear) survive without water?", options: JSON.stringify(["5 years","30 years","100 years","Over 100 years"]), correctAnswer: "Over 100 years", funFact: "Tardigrades can survive in a dessicated state (cryptobiosis) for potentially over 100 years. They've survived all five mass extinctions, temperatures from -272°C to 150°C, pressures 6x deeper than the ocean, and the vacuum of space. They are almost certainly the toughest animals on Earth." },
  // ── LOGIC ─────────────────────────────────────────────────────────────────
  { category: "Logic", difficulty: "EASY", question: "If all cats are animals and all animals need water, do cats need water?", options: JSON.stringify(["No","Only sometimes","Yes","Cannot be determined"]), correctAnswer: "Yes", funFact: "This is a classic syllogism — one of the oldest forms of logical reasoning, formalized by Aristotle in the 4th century BC. If A implies B, and B implies C, then A implies C. This transitive property is a cornerstone of formal logic and mathematics." },
  { category: "Logic", difficulty: "EASY", question: "A rooster lays an egg at the peak of a roof. Which way does it roll?", options: JSON.stringify(["Left","Right","Toward the back","Roosters don't lay eggs"]), correctAnswer: "Roosters don't lay eggs", funFact: "This is a classic trick question testing careful reading. Roosters are male chickens and cannot lay eggs. It's a reminder that apparent complexity can sometimes hide a simple, obvious answer hidden in plain sight — a key principle in logical thinking and problem solving." },
  { category: "Logic", difficulty: "EASY", question: "If you have a 3-litre jug and a 5-litre jug, how can you measure exactly 4 litres?", options: JSON.stringify(["Fill the 5, pour into 3, empty 3, pour remaining into 3, fill 5 and top up 3","Just fill the 5 and estimate","Use both full","You can't"]), correctAnswer: "Fill the 5, pour into 3, empty 3, pour remaining into 3, fill 5 and top up 3", funFact: "This water pouring puzzle appeared in the movie Die Hard with a Vengeance (1995). It is a classic example of a state-space search problem in computer science — AI algorithms use similar techniques to solve much more complex problems." },
  { category: "Logic", difficulty: "MEDIUM", question: "What comes next in the sequence: 2, 4, 8, 16, __?", options: JSON.stringify(["24","30","32","34"]), correctAnswer: "32", funFact: "This is a geometric sequence where each term is multiplied by 2. These powers of 2 (2¹, 2², 2³...) are fundamental to computing — binary numbers, memory sizes (8GB, 16GB, 32GB), and pixel counts all follow this pattern." },
  { category: "Logic", difficulty: "MEDIUM", question: "A man builds a house with all four sides facing south. A bear walks by. What color is the bear?", options: JSON.stringify(["Brown","Black","White","Grey"]), correctAnswer: "White", funFact: "The only place on Earth where all four sides of a building can face south is the North Pole, where Polar Bears (which are white) live. The puzzle is an example of a lateral thinking problem — you need to question the assumed frame of reference to find the solution." },
  { category: "Logic", difficulty: "MEDIUM", question: "If it takes 5 machines 5 minutes to make 5 widgets, how long does it take 100 machines to make 100 widgets?", options: JSON.stringify(["100 minutes","50 minutes","10 minutes","5 minutes"]), correctAnswer: "5 minutes", funFact: "This puzzle fools most people because they intuitively scale up linearly. Each machine makes 1 widget in 5 minutes. 100 machines each making 1 widget still only takes 5 minutes. It's a popular interview question used by Google and Microsoft." },
  { category: "Logic", difficulty: "MEDIUM", question: "Which number should replace the question mark: 1, 1, 2, 3, 5, 8, 13, ?", options: JSON.stringify(["18","20","21","23"]), correctAnswer: "21", funFact: "This is the Fibonacci sequence — each number is the sum of the two before it. It appears throughout nature: in the spiral arrangement of sunflower seeds, nautilus shells, and the branching of trees. Leonardo Fibonacci introduced it to Western mathematics in 1202, though Indian mathematicians knew it 1,600 years earlier." },
  { category: "Logic", difficulty: "HARD", question: "The Monty Hall Problem: you pick door 1. The host opens door 3 (empty). Should you switch to door 2?", options: JSON.stringify(["No, it makes no difference","Yes, switching doubles your chance of winning","No, door 1 was always better","Yes, but only by a tiny margin"]), correctAnswer: "Yes, switching doubles your chance of winning", funFact: "Switching gives you a 2/3 chance of winning vs. staying at 1/3. When Marilyn vos Savant published this answer in 1990, she received 10,000 letters including from PhDs calling her wrong. Computer simulations confirm switching is the correct strategy." },
  { category: "Logic", difficulty: "HARD", question: "In propositional logic, which of these is a tautology?", options: JSON.stringify(["P AND NOT P","P OR Q","P OR NOT P","P AND Q"]), correctAnswer: "P OR NOT P", funFact: "P OR NOT P (the Law of Excluded Middle) is always true regardless of whether P is true or false — making it a tautology. This principle was foundational to Aristotelian logic. In quantum mechanics, this law can be violated at the quantum level, leading to 'superposition' states." },
  { category: "Logic", difficulty: "HARD", question: "What is the name of the logical paradox: 'This statement is false'?", options: JSON.stringify(["Russel's Paradox","Zeno's Paradox","The Liar's Paradox","Gödel's Paradox"]), correctAnswer: "The Liar's Paradox", funFact: "The Liar's Paradox has no resolution within classical logic — if the statement is true, it must be false; if false, it must be true. Gödel used a similar self-referential idea in his Incompleteness Theorems (1931), proving that any sufficiently complex mathematical system contains true statements that cannot be proven." },
  // ── WORLD WONDERS ─────────────────────────────────────────────────────────
  { category: "World Wonders", difficulty: "EASY", question: "Which of the Seven Wonders of the Ancient World is still standing?", options: JSON.stringify(["Colossus of Rhodes","Hanging Gardens of Babylon","Great Pyramid of Giza","Temple of Artemis"]), correctAnswer: "Great Pyramid of Giza", funFact: "The Great Pyramid of Giza is the oldest and only surviving wonder of the ancient world. Built around 2560 BC, it was the tallest man-made structure for over 3,800 years. Recent research suggests it was built by paid workers, not slaves, who received beer, bread, and medical care." },
  { category: "World Wonders", difficulty: "EASY", question: "In which country is Machu Picchu located?", options: JSON.stringify(["Chile","Bolivia","Colombia","Peru"]), correctAnswer: "Peru", funFact: "Machu Picchu was built around 1450 by Inca Emperor Pachacuti and abandoned just 100 years later, likely due to smallpox. It was 'rediscovered' for the outside world by Hiram Bingham III in 1911 — though local Peruvians always knew it existed." },
  { category: "World Wonders", difficulty: "EASY", question: "What country contains the Colosseum?", options: JSON.stringify(["Greece","Spain","Turkey","Italy"]), correctAnswer: "Italy", funFact: "The Colosseum in Rome could hold 50,000–80,000 spectators and had 80 entrances allowing it to fill and empty in minutes — a crowd management design still used in modern stadiums. It was completed in 80 AD and hosted over 400 years of gladiatorial games." },
  { category: "World Wonders", difficulty: "EASY", question: "Which ancient wonder was a giant statue on the Greek island of Rhodes?", options: JSON.stringify(["Statue of Zeus","Mausoleum at Halicarnassus","Colossus of Rhodes","Lighthouse of Alexandria"]), correctAnswer: "Colossus of Rhodes", funFact: "The Colossus of Rhodes (constructed 292–280 BC) was a 33-meter bronze statue of the sun god Helios. It stood for only 54 years before being toppled by an earthquake. A legend that ships sailed between its legs is almost certainly false — it likely stood on a promontory overlooking the harbor." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "What is the Great Wall of China primarily made of?", options: JSON.stringify(["Marble","Granite","Brick and tamped earth","Limestone"]), correctAnswer: "Brick and tamped earth", funFact: "The Great Wall of China is not a single continuous structure but a series of walls built over 2,000+ years. The famous brick sections were built during the Ming Dynasty (1368–1644). The myth that it is visible from space is false — it is too narrow to be seen by the naked eye from the Moon." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "For what purpose was the Taj Mahal originally built?", options: JSON.stringify(["As a palace","As a mosque","As a mausoleum","As a fortress"]), correctAnswer: "As a mausoleum", funFact: "The Taj Mahal was built by Mughal Emperor Shah Jahan between 1632–1653 as a tomb for his beloved wife Mumtaz Mahal, who died in childbirth. It took 22 years and 20,000 workers to build. Shah Jahan was later imprisoned by his own son in a fort where he could see the Taj Mahal — his only comfort." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which New Seven Wonders site is located in Jordan?", options: JSON.stringify(["Angkor Wat","Chichen Itza","Christ the Redeemer","Petra"]), correctAnswer: "Petra", funFact: "Petra (meaning 'rock' in Greek) is a city carved directly into rose-red sandstone cliffs by the Nabataean people around 300 BC. At its peak it was home to 20,000 people. The iconic Treasury (Al-Khazneh) facade is 43 meters tall and features an intricate 3-level design carved from a single cliff face." },
  { category: "World Wonders", difficulty: "HARD", question: "What was the original purpose of Stonehenge?", options: JSON.stringify(["Royal palace","Astronomical calendar and burial site","Military fortress","Trading post"]), correctAnswer: "Astronomical calendar and burial site", funFact: "Stonehenge was built in phases from 3000–1500 BC. The largest stones (sarsens) weigh up to 25 tons and were transported from Marlborough Downs, 25 km away. The site was used as a burial ground for centuries — over 50,000 cremated bone fragments have been found there." },
  { category: "World Wonders", difficulty: "HARD", question: "Which ancient wonder was said to be a series of terraced gardens in Mesopotamia?", options: JSON.stringify(["Temple of Artemis","Hanging Gardens of Babylon","Gardens of Nineveh","Ziggurat of Ur"]), correctAnswer: "Hanging Gardens of Babylon", funFact: "The Hanging Gardens are the only Ancient Wonder whose existence is disputed — no Babylonian texts mention them and no archaeological evidence has been found. Some scholars believe they were actually located in Nineveh, the capital of Assyria, created by King Sennacherib for his wife who missed the green hills of her homeland." },
  { category: "World Wonders", difficulty: "HARD", question: "The ancient Library of Alexandria is estimated to have held how many scrolls at its peak?", options: JSON.stringify(["10,000","100,000","400,000–700,000","Over 1 million"]), correctAnswer: "400,000–700,000", funFact: "The Library of Alexandria contained up to 700,000 scrolls — the largest collection of knowledge in the ancient world. It was not destroyed in a single fire; it declined gradually over centuries of underfunding and conflict. Julius Caesar's fire in 48 BC destroyed only the dock warehouse, not the main library." },
];

const extraQuestions3 = [
  // ── SCIENCE (extra) ───────────────────────────────────────────────────────
  { category: "Science", difficulty: "EASY", question: "What is the center of an atom called?", options: JSON.stringify(["Electron shell","Proton ring","Nucleus","Core"]), correctAnswer: "Nucleus", funFact: "Ernest Rutherford discovered the atomic nucleus in 1911 by firing alpha particles at gold foil. Most passed through, but some bounced back — proving atoms are mostly empty space with a tiny dense center. He described it as 'like firing artillery shells at tissue paper and having them bounce back.'" },
  { category: "Science", difficulty: "EASY", question: "Which organ pumps blood through the human body?", options: JSON.stringify(["Lung","Liver","Kidney","Heart"]), correctAnswer: "Heart", funFact: "In a 70-year lifetime, the human heart beats approximately 2.5 billion times. It pumps about 5 liters of blood per minute at rest — enough to fill a bath in about 4 minutes. The heart generates enough energy in a lifetime to drive a truck to the Moon and back." },
  { category: "Science", difficulty: "EASY", question: "What is H2O more commonly known as?", options: JSON.stringify(["Salt","Oxygen","Hydrogen","Water"]), correctAnswer: "Water", funFact: "Water is the only substance that expands when it freezes — most substances contract. This is why ice floats on water. If ice sank, lakes would freeze solid from the bottom up, making aquatic life nearly impossible and Earth's climate dramatically different." },
  { category: "Science", difficulty: "EASY", question: "What do we call the process by which a caterpillar becomes a butterfly?", options: JSON.stringify(["Hibernation","Metamorphosis","Evolution","Mutation"]), correctAnswer: "Metamorphosis", funFact: "Inside a chrysalis, the caterpillar doesn't just grow wings — its body completely dissolves into a cellular soup and reorganizes. Some scientists believe the butterfly can retain memories from its caterpillar life, suggesting memories can survive metamorphosis." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the pH of pure water?", options: JSON.stringify(["5","6","7","8"]), correctAnswer: "7", funFact: "pH 7 is neutral — neither acidic nor basic. The pH scale was introduced by Danish chemist Søren Sørensen in 1909. 'pH' stands for 'potential of hydrogen.' Our blood maintains a pH of 7.35–7.45; a shift of even 0.4 units can be fatal." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the name of the layer of the atmosphere closest to Earth's surface?", options: JSON.stringify(["Stratosphere","Mesosphere","Thermosphere","Troposphere"]), correctAnswer: "Troposphere", funFact: "The troposphere contains 75% of the atmosphere's mass and virtually all weather phenomena. It extends 8–15 km above Earth's surface (thicker at the equator, thinner at the poles). Every time you breathe, you inhale air from the troposphere." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the chemical formula for table salt?", options: JSON.stringify(["NaCl","KCl","CaCl2","MgCl2"]), correctAnswer: "NaCl", funFact: "Salt (sodium chloride) is essential for life — it regulates fluid balance, nerve signals, and muscle contractions. Humans historically valued salt so highly that Roman soldiers were sometimes paid in salt (the origin of the word 'salary'). Today's ocean is about 3.5% salt." },
  { category: "Science", difficulty: "HARD", question: "What does the Heisenberg Uncertainty Principle state?", options: JSON.stringify(["Energy cannot be created or destroyed","You cannot know both position and momentum of a particle exactly simultaneously","Light behaves as both wave and particle","Mass and energy are equivalent"]), correctAnswer: "You cannot know both position and momentum of a particle exactly simultaneously", funFact: "Werner Heisenberg formulated this principle in 1927. It's not due to measurement limitations — it's a fundamental property of quantum systems. The very act of observing a particle's position disturbs its momentum. This uncertainty is built into the fabric of reality." },
  { category: "Science", difficulty: "HARD", question: "What is the name for the theoretical boundary around a black hole beyond which nothing can escape?", options: JSON.stringify(["Photon sphere","Ergosphere","Event horizon","Schwarzschild limit"]), correctAnswer: "Event horizon", funFact: "At the event horizon, escape velocity equals the speed of light — so even light cannot escape. Time itself slows to a stop at the event horizon relative to a distant observer. The first image of a black hole's shadow (M87*) was captured in 2019 by the Event Horizon Telescope." },
  { category: "Science", difficulty: "HARD", question: "Which scientist discovered penicillin by accident?", options: JSON.stringify(["Louis Pasteur","Joseph Lister","Marie Curie","Alexander Fleming"]), correctAnswer: "Alexander Fleming", funFact: "Fleming discovered penicillin in 1928 when mold contaminated a bacterial culture and killed the bacteria around it. He largely forgot about it until 1939 when Howard Florey and Ernst Chain developed it into a usable drug. Penicillin has saved an estimated 200 million lives." },
  // ── TECHNOLOGY (extra) ────────────────────────────────────────────────────
  { category: "Technology", difficulty: "EASY", question: "What does 'GPS' stand for?", options: JSON.stringify(["General Positioning Service","Global Positioning System","Geo-Positioning Signal","Ground Positioning Satellite"]), correctAnswer: "Global Positioning System", funFact: "GPS was developed by the US Department of Defense using 24 satellites and became fully operational in 1995. It was originally only for military use; President Reagan opened it to civilians after Korean Air Flight 007 was shot down in 1983 because the crew had made a navigation error." },
  { category: "Technology", difficulty: "EASY", question: "Which company is known for the Windows operating system?", options: JSON.stringify(["Apple","Google","Microsoft","IBM"]), correctAnswer: "Microsoft", funFact: "Windows 1.0 was released in 1985 and was so slow that Edlin, a basic text editor, sometimes ran faster. Windows 95 was a cultural event — people queued overnight to buy it, and the Rolling Stones licensed 'Start Me Up' for the launch. Today Windows runs on about 73% of the world's PCs." },
  { category: "Technology", difficulty: "MEDIUM", question: "What is the name of Elon Musk's space exploration company?", options: JSON.stringify(["Blue Origin","Virgin Galactic","Rocket Lab","SpaceX"]), correctAnswer: "SpaceX", funFact: "SpaceX's Falcon 9 rocket was the first orbital-class rocket to successfully land and reuse its booster. By doing so, SpaceX reduced launch costs from ~$65,000 per kg to under $3,000 per kg. In 2012, SpaceX became the first private company to deliver cargo to the International Space Station." },
  { category: "Technology", difficulty: "MEDIUM", question: "What does 'HTML' stand for?", options: JSON.stringify(["Hyper Transfer Markup Language","HyperText Markup Language","High Text Machine Language","Hyper Textual Meta Language"]), correctAnswer: "HyperText Markup Language", funFact: "HTML was invented by Tim Berners-Lee in 1990 and remains the backbone of every website. The first website (info.cern.ch) went live on August 6, 1991 and still exists today. HTML5, the current version, added native video, audio, and canvas drawing without needing plugins like Flash." },
  { category: "Technology", difficulty: "HARD", question: "What is Moore's Law?", options: JSON.stringify(["Hard drives double in capacity every year","The number of transistors on a chip doubles approximately every two years","Internet speed doubles every 18 months","Battery capacity doubles every 5 years"]), correctAnswer: "The number of transistors on a chip doubles approximately every two years", funFact: "Gordon Moore (Intel co-founder) predicted this in 1965 and it held true for about 50 years. Engineers are now hitting physical limits as transistors approach atomic scale. Some chips have transistors just 2 nanometers wide — smaller than a strand of DNA." },
  { category: "Technology", difficulty: "HARD", question: "Which programming paradigm treats computation as the evaluation of mathematical functions?", options: JSON.stringify(["Object-Oriented Programming","Procedural Programming","Functional Programming","Event-Driven Programming"]), correctAnswer: "Functional Programming", funFact: "Functional programming languages like Haskell, Lisp, and Erlang avoid changing state and mutable data. WhatsApp, which handled over 900 million users, was largely built with Erlang. The concept originates from Alonzo Church's Lambda Calculus (1930s) — predating computers entirely." },
  // ── HISTORY (extra) ───────────────────────────────────────────────────────
  { category: "History", difficulty: "EASY", question: "Which ancient city was famously 'sacked' by Genghis Khan's Mongols?", options: JSON.stringify(["Constantinople","Baghdad","Rome","Alexandria"]), correctAnswer: "Baghdad", funFact: "In 1258, the Mongols sacked Baghdad — then the world's most advanced city — and destroyed the House of Wisdom, the greatest library of the medieval world. The Tigris River reportedly ran black with ink from the destroyed books. The event ended the Islamic Golden Age." },
  { category: "History", difficulty: "EASY", question: "Who invented the telephone?", options: JSON.stringify(["Thomas Edison","Nikola Tesla","Guglielmo Marconi","Alexander Graham Bell"]), correctAnswer: "Alexander Graham Bell", funFact: "Bell filed his patent on February 14, 1876 — just hours before rival Elisha Gray filed a similar claim. The US Patent Office awarded Bell the patent, though legal battles lasted decades. Bell's first telephone words to his assistant: 'Mr. Watson, come here, I want to see you.'" },
  { category: "History", difficulty: "MEDIUM", question: "What was the name of the trading network connecting China to the Mediterranean?", options: JSON.stringify(["Amber Road","Incense Route","Salt Road","Silk Road"]), correctAnswer: "Silk Road", funFact: "The Silk Road wasn't a single road but a network of trade routes spanning 6,400 km, active from 130 BC to the 1450s. It carried not just silk but spices, glassware, religions, ideas, and diseases — including the Black Death, which traveled west along its routes in the 14th century." },
  { category: "History", difficulty: "MEDIUM", question: "What year did the first men land on the Moon?", options: JSON.stringify(["1965","1967","1969","1971"]), correctAnswer: "1969", funFact: "Apollo 11 landed on the Moon on July 20, 1969. Neil Armstrong's heart rate reached 150 bpm during the final minutes of landing. The computer guidance system displayed error code 1202 during descent — mission controllers let them continue. The landing computer had less power than a modern calculator." },
  { category: "History", difficulty: "HARD", question: "What was the name of the first artificial satellite launched into space?", options: JSON.stringify(["Vostok 1","Explorer 1","Sputnik 1","Luna 1"]), correctAnswer: "Sputnik 1", funFact: "The Soviet Union launched Sputnik 1 on October 4, 1957, shocking the world and triggering the Space Race. It was only the size of a beach ball (58 cm diameter) and transmitted a simple radio beep. The shock of Sputnik directly led to the creation of NASA and massive increases in US science education funding." },
  { category: "History", difficulty: "HARD", question: "Who was the Chinese philosopher who founded Confucianism?", options: JSON.stringify(["Laozi","Sunzi","Mencius","Confucius"]), correctAnswer: "Confucius", funFact: "Confucius (551–479 BC) emphasized education, family loyalty, and respect for elders and ancestors. He never wrote down his teachings — his students compiled them into the Analects after his death. Confucianism became the official Chinese state philosophy for over 2,000 years, shaping East Asian culture profoundly." },
  // ── GEOGRAPHY (extra) ─────────────────────────────────────────────────────
  { category: "Geography", difficulty: "EASY", question: "What is the smallest continent?", options: JSON.stringify(["Europe","Antarctica","South America","Australia"]), correctAnswer: "Australia", funFact: "Australia is the world's smallest continent but the sixth largest country. It's the only country that covers an entire continent. Australia has more venomous species than any other country — 21 of the world's 25 most venomous snakes are found there." },
  { category: "Geography", difficulty: "EASY", question: "Through which country does the Amazon River primarily flow?", options: JSON.stringify(["Colombia","Venezuela","Peru","Brazil"]), correctAnswer: "Brazil", funFact: "The Amazon basin covers 40% of South America and contains 10% of all species on Earth. The river discharges 20% of all fresh water that enters the world's oceans. During the wet season, the Amazon can be 50 km wide in places and flood an area the size of France." },
  { category: "Geography", difficulty: "MEDIUM", question: "What is the name of the world's largest hot desert?", options: JSON.stringify(["Arabian Desert","Gobi Desert","Kalahari Desert","Sahara Desert"]), correctAnswer: "Sahara Desert", funFact: "The Sahara spans 9.2 million sq km across 11 countries. Despite its reputation, only 25% is sand dunes (ergs) — the rest is rocky plateau (hamada) and gravel plains (reg). Ancient cave paintings in Algeria show the Sahara had rivers, elephants, and hippos just 6,000 years ago." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which country contains the most natural freshwater lakes?", options: JSON.stringify(["Russia","USA","China","Canada"]), correctAnswer: "Canada", funFact: "Canada has more lakes than all other countries combined — approximately 879,800 lakes covering about 9% of its total area. The Great Lakes on the US-Canada border contain 21% of the world's surface fresh water. The Great Bear Lake in Canada's Northwest Territories is the largest lake entirely within Canada." },
  { category: "Geography", difficulty: "HARD", question: "What is the name of the tectonic plate that the Indian subcontinent sits on?", options: JSON.stringify(["Eurasian Plate","Pacific Plate","Indo-Australian Plate","Arabian Plate"]), correctAnswer: "Indo-Australian Plate", funFact: "The Indo-Australian Plate has been colliding with the Eurasian Plate for 50 million years, pushing up the Himalayas — and it's still moving at about 5 cm per year. Mount Everest grows about 4mm taller annually because of this ongoing collision." },
  { category: "Geography", difficulty: "HARD", question: "Which strait separates Europe from Africa?", options: JSON.stringify(["Strait of Hormuz","Bosphorus","Strait of Dover","Strait of Gibraltar"]), correctAnswer: "Strait of Gibraltar", funFact: "The Strait of Gibraltar is only 14 km wide at its narrowest point, yet two continents meet here. The ancient world called the rocks on each side the 'Pillars of Hercules.' The Mediterranean Sea loses more water to evaporation than it receives from rivers, so Atlantic water constantly flows in through this strait." },
  // ── MOVIES (extra) ────────────────────────────────────────────────────────
  { category: "Movies", difficulty: "EASY", question: "In 'The Lion King', what is Simba's father's name?", options: JSON.stringify(["Scar","Rafiki","Timon","Mufasa"]), correctAnswer: "Mufasa", funFact: "James Earl Jones voiced Mufasa, having previously voiced Darth Vader. The Lion King is loosely based on Shakespeare's Hamlet — a prince whose uncle kills the king, takes the throne, and the prince must reclaim his birthright. The wildebeest stampede scene took 3 years to animate using early computer graphics." },
  { category: "Movies", difficulty: "EASY", question: "Which 1993 film features dinosaurs brought back to life?", options: JSON.stringify(["Jurassic Park","Land of the Lost","Dinosaur","The Lost World"]), correctAnswer: "Jurassic Park", funFact: "Jurassic Park (1993) revolutionized CGI — before it, movies relied entirely on physical models. Director Steven Spielberg and the effects team built 14 dinosaur robots for close-up shots but used CGI for wider shots. It was the first film to use a THX digital sound mix." },
  { category: "Movies", difficulty: "MEDIUM", question: "Who played the Joker in the 2019 film 'Joker'?", options: JSON.stringify(["Jack Nicholson","Heath Ledger","Jared Leto","Joaquin Phoenix"]), correctAnswer: "Joaquin Phoenix", funFact: "Joaquin Phoenix lost 23 kg for the role of Arthur Fleck/Joker, eating an extremely restrictive diet under medical supervision. He won the Academy Award, Golden Globe, and BAFTA for the role. The film was shot without a script for some scenes — Phoenix improvised the iconic refrigerator scene and the dancing." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which film is famous for the line 'I'll be back'?", options: JSON.stringify(["RoboCop","Die Hard","Predator","The Terminator"]), correctAnswer: "The Terminator", funFact: "Arnold Schwarzenegger originally wanted to say 'I'll come back' because 'I'll be back' seemed grammatically unusual for a robot. Director James Cameron insisted. It became arguably the most quoted movie line ever. Schwarzenegger has said the line in over 30 films since The Terminator." },
  { category: "Movies", difficulty: "HARD", question: "What was the budget of the original 1977 Star Wars film?", options: JSON.stringify(["$5 million","$11 million","$25 million","$40 million"]), correctAnswer: "$11 million", funFact: "Star Wars had a budget of $11 million but grossed $775 million worldwide — a 70x return. 20th Century Fox was so unsure of its success they traded George Lucas the merchandising rights (worth billions) for a small pay cut. The film was rejected by every other studio before Fox accepted it." },
  { category: "Movies", difficulty: "HARD", question: "Which foreign language film won the Academy Award for Best Picture in 2020?", options: JSON.stringify(["Amélie","Pan's Labyrinth","Life is Beautiful","Parasite"]), correctAnswer: "Parasite", funFact: "Parasite (Gisaengchung) by Bong Joon-ho became the first non-English language film to win Best Picture in the Oscars' 92-year history. Bong received a standing ovation and said: 'Once you overcome the one-inch barrier of subtitles, you will be introduced to so many more amazing films.' He took home 4 Oscars that night." },
  // ── MUSIC (extra) ─────────────────────────────────────────────────────────
  { category: "Music", difficulty: "EASY", question: "Who is known as the 'Queen of Pop'?", options: JSON.stringify(["Rihanna","Britney Spears","Beyoncé","Madonna"]), correctAnswer: "Madonna", funFact: "Madonna has sold over 300 million records worldwide, making her the best-selling female music artist of all time. She has reinvented her image and sound dozens of times across 5 decades. Her 1985 album 'Like a Virgin' spent 3 years on the Billboard charts." },
  { category: "Music", difficulty: "EASY", question: "What is the name for the speed of music?", options: JSON.stringify(["Dynamics","Harmony","Rhythm","Tempo"]), correctAnswer: "Tempo", funFact: "Tempo is measured in BPM (beats per minute). The human resting heart rate is 60–100 BPM. Many pop songs are around 120 BPM, which musicologists believe synchronizes with energetic human movement. Some studies suggest music tempo directly influences walking speed and perceived exertion during exercise." },
  { category: "Music", difficulty: "MEDIUM", question: "What two instruments make up a classical 'duo sonata'?", options: JSON.stringify(["Two pianos","Violin and cello","A solo instrument and piano","Two violins"]), correctAnswer: "A solo instrument and piano", funFact: "The duo sonata (one melodic instrument + piano) became standard in the Classical period (1750–1820). Beethoven wrote famous duo sonatas for violin and piano (including 'Spring' and 'Kreutzer'). The piano replaced the harpsichord as the standard accompaniment instrument in this era." },
  { category: "Music", difficulty: "MEDIUM", question: "Which rock band is associated with the song 'Bohemian Rhapsody'?", options: JSON.stringify(["Led Zeppelin","The Rolling Stones","Aerosmith","Queen"]), correctAnswer: "Queen", funFact: "Bohemian Rhapsody (1975) was unlike anything in pop music — operatic sections, no chorus, and nearly 6 minutes long. Radio DJs said it was too long to play, so DJ Kenny Everett was given a copy as a favour and played it 14 times in a weekend. The public reaction forced its commercial release." },
  { category: "Music", difficulty: "HARD", question: "What musical term describes playing notes smoothly and connected?", options: JSON.stringify(["Staccato","Sforzando","Legato","Fortissimo"]), correctAnswer: "Legato", funFact: "Legato (Italian for 'tied together') vs. staccato (short and detached) is one of music's most fundamental contrasts. In string music, legato is achieved with a smooth bow stroke. In piano music, players overlap notes slightly. The concept exists in virtually every musical culture worldwide." },
  { category: "Music", difficulty: "HARD", question: "Who composed 'The Four Seasons'?", options: JSON.stringify(["Handel","Vivaldi","Telemann","Corelli"]), correctAnswer: "Vivaldi", funFact: "Antonio Vivaldi composed The Four Seasons around 1720 in Venice. Each concerto has an accompanying sonnet describing the season, which may have been written by Vivaldi himself. Despite dying in poverty and obscurity, his music was rediscovered in the 1920s — he is now one of the most performed classical composers." },
];

const extraQuestions4 = [
  // ── GENERAL KNOWLEDGE ──────────────────────────────────────────────────────
  { category: "General Knowledge", difficulty: "EASY", question: "How many continents does the equator pass through?", options: JSON.stringify(["2","3","4","5"]), correctAnswer: "3", funFact: "The equator passes through South America, Africa, and Asia. Countries like Ecuador, Kenya, and Indonesia all sit directly on the line, and it is marked with monuments in cities like Quito and Pontianak." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "What is the driest desert in the world?", options: JSON.stringify(["Sahara","Gobi","Atacama","Kalahari"]), correctAnswer: "Atacama", funFact: "The Atacama Desert in Chile receives less than 1 mm of rain per year — some weather stations have never recorded rainfall. NASA tests its Mars rovers there because the soil is almost identical to the Martian surface." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "What is the tallest animal in the world?", options: JSON.stringify(["Elephant","Giraffe","Ostrich","Camel"]), correctAnswer: "Giraffe", funFact: "Male giraffes can reach 5.5 meters tall, and their necks alone can weigh up to 250 kg. Despite the long neck, giraffes have the same number of neck vertebrae as humans — just seven — each one up to 30 cm long." },
  { category: "General Knowledge", difficulty: "HARD", question: "Which country has no rivers at all?", options: JSON.stringify(["Egypt","Saudi Arabia","Mongolia","Kazakhstan"]), correctAnswer: "Saudi Arabia", funFact: "Saudi Arabia has no permanent rivers or lakes. It relies instead on groundwater and desalination — desalinizing over 3 million cubic meters of seawater daily, making it one of the world's largest producers of desalinated water." },

  // ── SCIENCE ───────────────────────────────────────────────────────────────
  { category: "Science", difficulty: "EASY", question: "Which planet has the most moons?", options: JSON.stringify(["Jupiter","Earth","Mars","Venus"]), correctAnswer: "Jupiter", funFact: "Jupiter has 92 confirmed moons, with more being discovered. Its largest moon Ganymede is bigger than the planet Mercury! Saturn is a close second with 83 moons." },
  { category: "Science", difficulty: "EASY", question: "What is the hardest natural material in the human body?", options: JSON.stringify(["Bone","Tooth enamel","Fingernail","Cartilage"]), correctAnswer: "Tooth enamel", funFact: "Tooth enamel is the hardest substance in the human body — harder than bone. It's made mostly of hydroxyapatite, a calcium mineral, and contains no living cells, which is why teeth can't heal themselves like bones can." },
  { category: "Science", difficulty: "MEDIUM", question: "Which direction does blood travel in veins?", options: JSON.stringify(["Away from the heart","Toward the heart","It doesn't move","Up only"]), correctAnswer: "Toward the heart", funFact: "Veins carry oxygen-depleted blood back toward the heart, while arteries carry oxygenated blood away. Veins have one-way valves that prevent backflow — in the legs, muscle contractions help pump blood upward against gravity." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the name of the process plants use to turn sunlight into food?", options: JSON.stringify(["Respiration","Photosynthesis","Fermentation","Osmosis"]), correctAnswer: "Photosynthesis", funFact: "Photosynthesis converts sunlight, water, and carbon dioxide into glucose and oxygen. The process first emerged over 2.5 billion years ago in cyanobacteria, which eventually transformed Earth's atmosphere and made animal life possible." },
  { category: "Science", difficulty: "HARD", question: "Which particle is known as the 'God Particle'?", options: JSON.stringify(["Neutrino","Quark","Higgs Boson","Gluon"]), correctAnswer: "Higgs Boson", funFact: "The Higgs Boson gives other particles their mass. It was predicted in 1964 but not confirmed until 2012 at CERN's Large Hadron Collider. The nickname 'God Particle' was coined by physicist Leon Lederman, who actually wanted to call it the 'Goddamn Particle' because it was so hard to find." },

  // ── HISTORY ───────────────────────────────────────────────────────────────
  { category: "History", difficulty: "EASY", question: "Who was the first President of the Philippines?", options: JSON.stringify(["Jose Rizal","Emilio Aguinaldo","Manuel Quezon","Andres Bonifacio"]), correctAnswer: "Emilio Aguinaldo", funFact: "Emilio Aguinaldo was proclaimed President of the First Philippine Republic on January 23, 1899 in Malolos, Bulacan. He had earlier declared independence from Spain on June 12, 1898 in Kawit, Cavite." },
  { category: "History", difficulty: "EASY", question: "The Titanic sank in which year?", options: JSON.stringify(["1905","1912","1915","1921"]), correctAnswer: "1912", funFact: "The RMS Titanic sank on April 15, 1912 — just four days into her maiden voyage. Over 1,500 people died. The wreck wasn't found until 1985, resting 3,800 meters deep in the North Atlantic." },
  { category: "History", difficulty: "MEDIUM", question: "What was the name of the ancient Filipino writing system?", options: JSON.stringify(["Alibata","Baybayin","Kulitan","Runic"]), correctAnswer: "Baybayin", funFact: "Baybayin was the pre-colonial script of the Philippines. The mistaken term 'Alibata' was invented in the 1900s by a scholar who mistakenly based the name on the Arabic alphabet, but the true native name is 'Baybayin', from 'baybay' meaning 'to spell.'" },
  { category: "History", difficulty: "MEDIUM", question: "Which ancient wonder is located in Giza, Egypt?", options: JSON.stringify(["The Colossus","The Great Pyramid","The Lighthouse","The Hanging Gardens"]), correctAnswer: "The Great Pyramid", funFact: "The Great Pyramid of Giza was the tallest man-made structure on Earth for over 3,800 years. It was built from roughly 2.3 million stone blocks, each weighing about 2.5 tons, and is the only surviving wonder of the ancient world." },
  { category: "History", difficulty: "HARD", question: "What was the name of the first Filipino Pope-approved saint?", options: JSON.stringify(["Lorenzo Ruiz","Pedro Calungsod","San Diego de Alcala","Blessed Justo"]), correctAnswer: "Lorenzo Ruiz", funFact: "Lorenzo Ruiz became the first Filipino saint when he was canonized in 1987 alongside 15 other martyrs who died in Nagasaki, Japan. Interestingly, Pedro Calungsod — the second Filipino saint — died earlier but was canonized later in 2012." },

  // ── GEOGRAPHY ─────────────────────────────────────────────────────────────
  { category: "Geography", difficulty: "EASY", question: "Which country has the largest population in the world?", options: JSON.stringify(["China","United States","India","Indonesia"]), correctAnswer: "India", funFact: "India overtook China as the world's most populous country in April 2023, reaching over 1.428 billion people. India is expected to keep growing until around 2064, when its population will peak near 1.7 billion." },
  { category: "Geography", difficulty: "EASY", question: "What is the longest river in the world?", options: JSON.stringify(["Amazon","Nile","Yangtze","Mississippi"]), correctAnswer: "Nile", funFact: "Debate continues, but the Nile — at about 6,650 km — is traditionally considered the world's longest river. The Amazon is widely regarded as the largest by volume, discharging more water than the next seven largest rivers combined." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which country is the largest by area?", options: JSON.stringify(["United States","Canada","China","Russia"]), correctAnswer: "Russia", funFact: "Russia spans 11 time zones and covers 17.1 million square kilometers — about 11% of Earth's land. It's almost twice the size of the United States and larger than the entire continent of Australia." },
  { category: "Geography", difficulty: "MEDIUM", question: "What is the capital of the Philippines?", options: JSON.stringify(["Quezon City","Manila","Makati","Cebu City"]), correctAnswer: "Manila", funFact: "Manila is the capital and the heart of the National Capital Region, yet nearby Quezon City is actually the country's most populous city. Manila derives its name from 'Maynilad', referencing the nilad plants that once grew along the bay." },
  { category: "Geography", difficulty: "HARD", question: "Which is the only country to border both the Atlantic and Indian Oceans?", options: JSON.stringify(["Brazil","Indonesia","South Africa","Madagascar"]), correctAnswer: "South Africa", funFact: "South Africa's southernmost point — Cape Agulhas — is where the Atlantic and Indian Oceans officially meet. Both currents flow along its coastline, which also gives South Africa a rich maritime history." },

  // ── TECHNOLOGY ────────────────────────────────────────────────────────────
  { category: "Technology", difficulty: "EASY", question: "What does 'Wi-Fi' stand for?", options: JSON.stringify(["Wireless Frequency","Wireless Fidelity","Wide Internet","Wire Internet"]), correctAnswer: "Wireless Fidelity", funFact: "Technically, 'Wi-Fi' doesn't officially stand for anything — it was a marketing coinage by the Wi-Fi Alliance. The backronym 'Wireless Fidelity' was a nod to the audio term 'Hi-Fi,' but the alliance later dropped the meaning entirely." },
  { category: "Technology", difficulty: "EASY", question: "Which company makes the iPhone?", options: JSON.stringify(["Samsung","Google (Pixel)","Apple","Sony"]), correctAnswer: "Apple", funFact: "The first iPhone launched on June 29, 2007 and introduced the smartphone era. It had a 3.5-inch screen, a single 2MP camera, and no App Store — yet it sold over 6 million units in its first year." },
  { category: "Technology", difficulty: "MEDIUM", question: "What does 'www' stand for in a website address?", options: JSON.stringify(["World Web Wire","Wide World Web","World Wide Web","Web Wire World"]), correctAnswer: "World Wide Web", funFact: "The 'www' prefix was created when Tim Berners-Lee invented the Web in 1989 at CERN. Older websites required you to type it, but modern browsers automatically add or remove it for you. Many new sites drop it entirely." },
  { category: "Technology", difficulty: "MEDIUM", question: "Which social media platform was founded by Mark Zuckerberg?", options: JSON.stringify(["Twitter","Instagram","Facebook","Snapchat"]), correctAnswer: "Facebook", funFact: "Facebook launched in 2004 from a Harvard dorm room. It originally restricted membership to college students with a Harvard.edu email. By 2012 it had over 1 billion users, and today its parent company Meta also owns Instagram and WhatsApp." },
  { category: "Technology", difficulty: "HARD", question: "What programming language is primarily used to style web pages?", options: JSON.stringify(["JavaScript","Python","HTML","CSS"]), correctAnswer: "CSS", funFact: "CSS (Cascading Style Sheets) was proposed by Håkon Wium Lie in 1994 while working at CERN. Before CSS, web pages were styled with HTML attributes alone — which made redesigning a website an excruciating, page-by-page task." },

  // ── GAMING ────────────────────────────────────────────────────────────────
  { category: "Gaming", difficulty: "EASY", question: "In Minecraft, what is the name of the building block made of compressed grass?", options: JSON.stringify(["Grass Block","Moss","Sod","Turf"]), correctAnswer: "Grass Block", funFact: "The grass block is one of Minecraft's most iconic blocks — it even appears on the game's title screen and loading screen. Its top texture has barely changed since the game's early alpha versions." },
  { category: "Gaming", difficulty: "EASY", question: "What gaming console was the first to hit 100 million sales?", options: JSON.stringify(["Nintendo Wii","PlayStation 2","Xbox 360","Game Boy"]), correctAnswer: "Game Boy", funFact: "The original Game Boy, released in 1989, sold over 118 million units — including its successors. It succeeded thanks to Tetris, bundled with the console, and its incredible battery life of roughly 30 hours on just 4 AA batteries." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which puzzle game has colored falling blocks and was created by Alexey Pajitnov?", options: JSON.stringify(["Tetris","Candy Crush","Bejeweled","Puyo Puyo"]), correctAnswer: "Tetris", funFact: "Tetris was created in 1984 by Soviet software engineer Alexey Pajitnov on an Elektronika 60 computer. It may be the best-selling video game of all time with over 500 million paid downloads across all versions." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which game series features a plumber named Mario?", options: JSON.stringify(["Sonic","Super Mario","Zelda","Metroid"]), correctAnswer: "Super Mario", funFact: "Mario made his debut in 1981 as 'Jumpman' in Donkey Kong. He was later renamed after Mario Segale, the landlord of Nintendo of America's office. Mario's signature jump and red hat remain his most recognized traits worldwide." },
  { category: "Gaming", difficulty: "HARD", question: "Which game is the best-selling video game of all time?", options: JSON.stringify(["Grand Theft Auto V","Minecraft","Tetris","Wii Sports"]), correctAnswer: "Minecraft", funFact: "Minecraft has sold over 300 million copies as of 2023 — more than any other game. It was created by Markus 'Notch' Persson in just six days in 2009 and later sold to Microsoft in 2014 for $2.5 billion." },

  // ── MOVIES ────────────────────────────────────────────────────────────────
  { category: "Movies", difficulty: "EASY", question: "Which movie features a toy cowboy named Woody?", options: JSON.stringify(["Shrek","Toy Story","Up","Cars"]), correctAnswer: "Toy Story", funFact: "Toy Story (1995) was the first fully computer-animated feature film ever made. It took 4 years to produce and required 117 animators working on an average of 1 frame per week each. Woody was voiced by Tom Hanks." },
  { category: "Movies", difficulty: "EASY", question: "Who played Iron Man in the Marvel movies?", options: JSON.stringify(["Chris Evans","Robert Downey Jr.","Chris Hemsworth","Mark Ruffalo"]), correctAnswer: "Robert Downey Jr.", funFact: "Robert Downey Jr.'s casting as Iron Man in 2008 was considered a huge risk at the time. His improvisation — like the famous 'I am Iron Man' line — helped define the character and launched the entire MCU era." },
  { category: "Movies", difficulty: "MEDIUM", question: "Who directed the movie 'Avatar'?", options: JSON.stringify(["Steven Spielberg","James Cameron","Christopher Nolan","Peter Jackson"]), correctAnswer: "James Cameron", funFact: "James Cameron spent over a decade developing the technology for Avatar (2009). The film earned $2.9 billion, making it the highest-grossing film of all time until Avengers: Endgame briefly overtook it in 2019." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which film franchise features the character 'Bilbo Baggins'?", options: JSON.stringify(["Harry Potter","Star Wars","The Hobbit","Pirates of the Caribbean"]), correctAnswer: "The Hobbit", funFact: "Bilbo Baggins was created by J.R.R. Tolkien in 1937's The Hobbit. The character also appears in The Lord of the Rings. In the films, Martin Freeman played Bilbo in The Hobbit trilogy while Ian Holm played him in Lord of the Rings." },
  { category: "Movies", difficulty: "HARD", question: "Who directed the original 'Star Wars: A New Hope'?", options: JSON.stringify(["George Lucas","Steven Spielberg","Irvin Kershner","Stephen Sommers"]), correctAnswer: "George Lucas", funFact: "George Lucas wrote and directed Star Wars (1977) after producer Richard Zanuck rejected it and 20th Century Fox only funded it because Lucas had a prior hit. Lucas financed his own risky salary for the Sequel Trilogy rights — which proved to be a fortune." },

  // ── MUSIC ────────────────────────────────────────────────────────────────
  { category: "Music", difficulty: "EASY", question: "Who is known as the 'King of Pop'?", options: JSON.stringify(["Elvis Presley","Michael Jackson","Prince","Bruno Mars"]), correctAnswer: "Michael Jackson", funFact: "Michael Jackson's album 'Thriller' (1982) remains the biggest-selling album of all time, with estimated sales of over 70 million copies. His music video for 'Thriller' revolutionized the medium and was inducted into the National Film Registry." },
  { category: "Music", difficulty: "EASY", question: "Who sang the hit song 'Halo'?", options: JSON.stringify(["Rihanna","Beyoncé","Adele","Taylor Swift"]), correctAnswer: "Beyoncé", funFact: "'Halo' was written for Beyoncé by Ryan Tedder and Emanuel Kiriakou in 2008. It was nominated for a Grammy. Interestingly, Ryan Tedder also wrote 'Already Gone' for Kelly Clarkson around the same time, and the two songs share a similar chord structure." },
  { category: "Music", difficulty: "MEDIUM", question: "What is the highest voice type in the human choir?", options: JSON.stringify(["Bass","Alto","Soprano","Tenor"]), correctAnswer: "Soprano", funFact: "Soprano is the highest female vocal range, typically from middle C to C two octaves higher. The highest male voice is the countertenor, while sopranos can reach notes that break glass — though the physics behind the 'singer breaks glass' stunt is debatable." },
  { category: "Music", difficulty: "MEDIUM", question: "Which boy band sings the song 'I Want It That Way'?", options: JSON.stringify(["NSYNC","Backstreet Boys","One Direction","BTS"]), correctAnswer: "Backstreet Boys", funFact: "The Backstreet Boys' 'I Want It That Way' became one of the best-known boy band songs ever. The group was formed in 1993 in Florida and named after a real street mall in Orlando called the 'Backstreet Market'." },
  { category: "Music", difficulty: "HARD", question: "What is the name of the traditional Filipino 2-stringed lute?", options: JSON.stringify(["Kudyapi","Bandurria","Kulintang","Angklung"]), correctAnswer: "Kudyapi", funFact: "The kudyapi is a two-stringed bamboo lute played by indigenous groups like the Maranao and Tagbanwa. It produces a melodic, plucked sound similar to a guitar. The kulintang is a different instrument — a set of small gongs." },

  // ── SPORTS ────────────────────────────────────────────────────────────────
  { category: "Sports", difficulty: "EASY", question: "How many players are there on a baseball team?", options: JSON.stringify(["9","8","11","6"]), correctAnswer: "9", funFact: "A baseball team fields 9 players — pitcher, catcher, first baseman, second baseman, third baseman, shortstop, and three outfielders. The oldest baseball clubs date to 1845, when the game's modern rules were codified by Alexander Cartwright." },
  { category: "Sports", difficulty: "EASY", question: "Which sport uses a 'shuttlecock'?", options: JSON.stringify(["Badminton","Tennis","Squash","Volleyball"]), correctAnswer: "Badminton", funFact: "A shuttlecock — often called a 'birdie' — is made of 16 goose feathers around a cork base. Its unique aerodynamic shape makes it always tumble and land cork-first, which is essential to the game of badminton." },
  { category: "Sports", difficulty: "MEDIUM", question: "How long is a standard soccer (football) match?", options: JSON.stringify(["60 minutes","75 minutes","90 minutes","120 minutes"]), correctAnswer: "90 minutes", funFact: "A regulation soccer match lasts 90 minutes — two halves of 45 minutes each, not counting stoppage time. Extra time of 30 minutes is added in knockout tournaments when the score is tied, with a possible penalty shootout after." },
  { category: "Sports", difficulty: "MEDIUM", question: "Which country is considered the birthplace of basketball?", options: JSON.stringify(["Canada","USA","UK","Australia"]), correctAnswer: "USA", funFact: "Basketball was invented on December 21, 1891 in Springfield, Massachusetts, by Canadian-American PE teacher James Naismith. He originally used a soccer ball and two peach baskets, and the first public game was 9 vs 9 players." },
  { category: "Sports", difficulty: "HARD", question: "Who holds the record for the most Olympic gold medals of all time?", options: JSON.stringify(["Usain Bolt","Simone Biles","Michael Phelps","Larisa Latynina"]), correctAnswer: "Michael Phelps", funFact: "Michael Phelps has won 23 Olympic gold medals — 28 medals total — across five Olympic Games (2004–2016). That's more gold medals than many entire countries. He also owns the record for most gold medals in a single Olympics with 8 in Beijing 2008." },

  // ── POP CULTURE ───────────────────────────────────────────────────────────
  { category: "Pop Culture", difficulty: "EASY", question: "Which streaming platform is known for its red logo and the tagline 'Enjoy Entertainment'?", options: JSON.stringify(["Netflix","Disney+","Prime Video","HBO Max"]), correctAnswer: "Netflix", funFact: "Netflix famously introduced its streaming service in 2007, and today it's the world's largest subscription-based streaming platform. Its red-and-black branding has become one of the most recognized logos in entertainment — even spawning the 'Netflix and chill' pop culture meme." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which musician is known for the hit 'Blinding Lights'?", options: JSON.stringify(["Post Malone","The Weeknd","Drake","Ed Sheeran"]), correctAnswer: "The Weeknd", funFact: "The Weeknd's 'Blinding Lights' (2019) was the #1 song of the entire 2020s decade according to Billboard. It blended 80s synth-pop with modern R&B, and its music video was shot in Las Vegas — a nod to the neon-soaked aesthetics of the 80s." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "What is the name of the famous yellow smiley face meme?", options: JSON.stringify(["Moshi","Zorblax","Smiley","Emoji Man"]), correctAnswer: "Smiley", funFact: "The classic yellow smiley face was created in 1963 by Harvey Ross Ball for a Massachusetts insurance company. The Internet later adopted it as the ultimate meme and it appears in everything from emojis to caution stickers and video game icons." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "Which movie won the 2020 Academy Award for Best Picture?", options: JSON.stringify(["Parasite","1917","Joker","Once Upon a Time in Hollywood"]), correctAnswer: "Parasite", funFact: "Parasite made history at the 92nd Academy Awards as the first non-English-language film to win Best Picture. Director Bong Joon-ho also won Best Director, and the film took home four total Oscars that evening." },
  { category: "Pop Culture", difficulty: "HARD", question: "What is the name of the 'Internet Law' that states any sufficiently advanced troll is indistinguishable from a bot?", options: JSON.stringify(["Godwin's Law","Sturgeon's Law","Clarke's Third Law","Betteridge's Law"]), correctAnswer: "Clarke's Third Law", funFact: "Clarke's Third Law states: 'Any sufficiently advanced technology is indistinguishable from magic.' Joking memes have adapted it to describe the line between humans and trolls on the Internet — showing how even physics law jokes became pop culture staples." },

  // ── PHILIPPINES ───────────────────────────────────────────────────────────
  { category: "Philippines", difficulty: "EASY", question: "What is the smallest province in the Philippines?", options: JSON.stringify(["Batanes","Catanduanes","Camiguin","Siquijor"]), correctAnswer: "Camiguin", funFact: "Camiguin, in Northern Mindanao, is the smallest province in the Philippines by both area (237 km²) and population. Despite its size, it has seven active volcanoes — more per square kilometer than any other province in the country." },
  { category: "Philippines", difficulty: "EASY", question: "What is the national bird of the Philippines?", options: JSON.stringify(["Mayon Falcon","Blue Jay","Philippine Eagle","Sunbird"]), correctAnswer: "Philippine Eagle", funFact: "The Philippine Eagle — the world's largest eagle by length and wingspan — was declared the national bird in 1995. It's also one of the rarest, with fewer than 500 pairs estimated in the wild, nearly all in Mindanao." },
  { category: "Philippines", difficulty: "MEDIUM", question: "In which city can you find the iconic Chocolate Hills?", options: JSON.stringify(["Cebu City","Bohol","Surigao","Baguio"]), correctAnswer: "Bohol", funFact: "The Chocolate Hills of Bohol number 1,268 dome-shaped hills that turn brown in the dry season, resembling chocolate drops. They're a protected geological wonder and a UNESCO-listed natural landmark in the Philippines." },
  { category: "Philippines", difficulty: "MEDIUM", question: "What is the name of the annual 'Tarsier Festival' province?", options: JSON.stringify(["Cebu","Bohol","Leyte","Mindoro"]), correctAnswer: "Bohol", funFact: "The tarsier — one of the smallest primates in the world — is native to Bohol and is a star attraction of the province. Tarsiers are nocturnal and can rotate their heads almost 180 degrees, and it takes about a month of reintroduction before they're healthy after being kept as pets." },
  { category: "Philippines", difficulty: "HARD", question: "Which Filipino wrote the novel 'Noli Me Tangere'?", options: JSON.stringify(["Marcelo H. del Pilar","Jose Rizal","Apolinario Mabini","Andres Bonifacio"]), correctAnswer: "Jose Rizal", funFact: "Jose Rizal wrote 'Noli Me Tangere' (Touch Me Not) in 1887 while living in Europe. The novel exposed Spanish colonial abuses and helped spark the revolution. It's now a required reading in Philippine schools and was translated into Tagalog (as 'Noli Me Tangere') by other reformers." },

  // ── FOOD & DRINKS ─────────────────────────────────────────────────────────
  { category: "Food & Drinks", difficulty: "EASY", question: "What is the main ingredient in sushi?", options: JSON.stringify(["Rice","Bread","Noodles","Tortilla"]), correctAnswer: "Rice", funFact: "Rice is the true heart of sushi — the Japanese term 'sushi' actually refers to the vinegared rice, not the fish. In Japan, the rice is seasoned with rice vinegar, sugar, and salt, and is meticulously prepared to achieve the perfect texture." },
  { category: "Food & Drinks", difficulty: "EASY", question: "Which fruit has seeds on the outside?", options: JSON.stringify(["Orange","Banana","Apple","Strawberry"]), correctAnswer: "Strawberry", funFact: "The strawberry is technically an 'aggregate fruit' — the fleshy part is the enlarged flower stalk, and each tiny yellow 'seed' on its surface is the actual fruit containing a seed. Average strawberries have about 200 seeds each." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "What makes a dish 'halal'?", options: JSON.stringify(["It contains no pork","It's prepared without alcohol and according to Islamic dietary law","It's gluten-free","It's cooked as a vegetarian dish"]), correctAnswer: "It's prepared without alcohol and according to Islamic dietary law", funFact: "Halal means 'permissible' in Arabic. Halal food must comply with Islamic dietary rules — including how the animal is slaughtered humanely and blessed, and what ingredients are used. It's a growing global food market worth billions." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "What is the traditional Filipino dish made with vinegar-soaked raw fish?", options: JSON.stringify(["Sinigang","Adobo","Kinilaw","Lechon"]), correctAnswer: "Kinilaw", funFact: "Kinilaw is a Filipino ceviche-like dish where raw fish is cured in vinegar, citrus, and spices for about 15 minutes. Unlike Mexican ceviche's lime-based marinade, kinilaw traditionally uses coconut vinegar and is served alongside ginger and chili." },
  { category: "Food & Drinks", difficulty: "HARD", question: "Which Philippine drink is made from fermented coconut sap?", options: JSON.stringify(["Tubâ","Buko Juice","Sago","Halo-halo"]), correctAnswer: "Tubâ", funFact: "Tubâ is a traditional Filipino toddy made from the fermented sap of coconut or nipa palms, commonly sweet and slightly fizzy. The same base can produce different drinks, depending on how long it ferments — from a mild sweet juice to a stronger spirit." },

  // ── TV SHOWS & ANIME ──────────────────────────────────────────────────────
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which anime is about a boy who becomes a pirate and stretches like rubber?", options: JSON.stringify(["Naruto","One Piece","Dragon Ball Z","Fairy Tail"]), correctAnswer: "One Piece", funFact: "One Piece began as a manga in 1997 by Eiichiro Oda and now holds the Guinness World Record for most copies of the same comic manga published by a single author. It chronicles Monkey D. Luffy's quest for the legendary treasure 'ONE PIECE.'" },
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Who is the main character of 'Naruto'?", options: JSON.stringify(["Sasuke","Goku","Naruto","Luffy"]), correctAnswer: "Naruto", funFact: "Naruto Uzumaki was a boisterous, orphaned ninja who dreamed of becoming Hokage. The Naruto series premiered in 2002 and ran over 700 episodes across its original and sequel series Boruto, capturing the imagination of millions worldwide." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which anime series features giant humanoid machines controlled by pilots called 'EVAs'?", options: JSON.stringify(["Gundam","Evangelion","Dragon Ball","Cowboy Bebop"]), correctAnswer: "Evangelion", funFact: "Neon Genesis Evangelion (1995) was a psychological deconstruction of the mecha genre, and its finale famously confounded viewers. It's now considered a landmark of anime art, with a successful theatrical remake saga spanning 1995–2021." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which TV show featured Rachel, Monica, Ross, Joey, Chandler, and Phoebe?", options: JSON.stringify(["Happy Days","Friends","Seinfeld","FRIENDS"]), correctAnswer: "Friends", funFact: "Friends premiered 1994 and ran 10 seasons — 236 episodes. At its peak it drew over 25 million viewers each week. The actors negotiated to each earn $1 million per episode in the final two seasons, making them the highest-paid TV cast at the time." },
  { category: "TV Shows & Anime", difficulty: "HARD", question: "Which anime, directed by Hayao Miyazaki, is set in a bathhouse for spirits?", options: JSON.stringify(["Spirited Away","My Neighbor Totoro","Princess Mononoke","Kiki's Delivery Service"]), correctAnswer: "Spirited Away", funFact: "Spirited Away (2001) won the Golden Bear in Berlin and the Oscar for Best Animated Feature — the first time a non-English film ever won that award. Studio Ghibli and Hayao Miyazaki infused it with Japanese folklore, and it became the highest-grossing Japanese film in history." },

  // ── ANIMALS ───────────────────────────────────────────────────────────────
  { category: "Animals", difficulty: "EASY", question: "Which animal is known for its ability to change colors?", options: JSON.stringify(["Octopus","Frog","Cuttlefish","Parrot"]), correctAnswer: "Cuttlefish", funFact: "Cuttlefish are masters of camouflage — they can change color and texture in milliseconds. Their camouflage ability doesn't just hide them from predators; it also communicates with potential mates and rivals. They're close relatives of octopuses and squids." },
  { category: "Animals", difficulty: "EASY", question: "Which animal has the strongest bite force ever measured?", options: JSON.stringify(["Lion","Great White Shark","Nile Crocodile","Siberian Tiger"]), correctAnswer: "Nile Crocodile", funFact: "Nile crocodiles can bite with up to 5,000 pounds per square inch of force — the strongest bite ever measured. For comparison, a lion's bite is only about 650 psi." },
  { category: "Animals", difficulty: "MEDIUM", question: "Why do dogs wag their tails?", options: JSON.stringify(["To express joy","To show aggression","To communicate emotions","It's purely involuntary"]), correctAnswer: "To communicate emotions", funFact: "A dog's tail has a complex communication purpose. A rapid, low-wagging tail generally means friendliness, while a slow, high, stiff wag can signal arousal or aggression. Dogs also use tail position to signal confidence, fear, or submission." },
  { category: "Animals", difficulty: "MEDIUM", question: "What is the largest species of jellyfish?", options: JSON.stringify(["Moon Jelly","Lion's Mane Jellyfish","Blue Jelly","Box Jelly"]), correctAnswer: "Lion's Mane Jellyfish", funFact: "The lion's mane jellyfish is the largest jellyfish species, with bells up to 2.4 meters wide and tentacles that can exceed 37 meters — longer than a blue whale. Despite its size, it's mostly harmless to humans, unlike the smaller box jellyfish." },
  { category: "Animals", difficulty: "HARD", question: "Which bird is capable of flying backward?", options: JSON.stringify(["Sparrow","Woodpecker","Hummingbird","Falcon"]), correctAnswer: "Hummingbird", funFact: "Hummingbirds are the only birds that can fly backward, hover for extended periods, and even fly upside-down briefly. They beat their wings 50–80 times per second, which is why they're among the most agile fliers in the animal kingdom." },
];

const extraQuestions5 = [
  // ── GENERAL KNOWLEDGE ──────────────────────────────────────────────────────
  { category: "General Knowledge", difficulty: "EASY", question: "Which planet is the only one named after a Greek god?", options: JSON.stringify(["Saturn","Neptune","Jupiter","Uranus"]), correctAnswer: "Jupiter", funFact: "Jupiter is named after the Roman god of the sky — the counterpart of the Greek Zeus. In fact, Jupiter is the only planet named after a Greek deity, since the Romans borrowed Zeus and renamed him Jupiter." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "Which language has the most native speakers in the world?", options: JSON.stringify(["English","Spanish","Mandarin Chinese","Hindi"]), correctAnswer: "Mandarin Chinese", funFact: "Mandarin Chinese has over 900 million native speakers — nearly twice as many as English. English claims the title for total speakers (including second-language users), but by natives alone Mandarin wins." },
  { category: "General Knowledge", difficulty: "HARD", question: "What is the smallest country in the world by land area?", options: JSON.stringify(["Monaco","Vatican City","San Marino","Liechtenstein"]), correctAnswer: "Vatican City", funFact: "Vatican City covers just 0.49 square kilometers — roughly the size of 60 football fields. It is the world's smallest independent state, fully enclosed within Rome, with a population of under 1,000." },

  // ── SCIENCE ───────────────────────────────────────────────────────────────
  { category: "Science", difficulty: "EASY", question: "Which organ produces insulin?", options: JSON.stringify(["Liver","Kidney","Pancreas","Spleen"]), correctAnswer: "Pancreas", funFact: "The pancreas produces insulin in clusters of cells called the islets of Langerhans. When these cells fail, type 1 diabetes develops — which is why insulin injections are needed." },
  { category: "Science", difficulty: "EASY", question: "What is the most abundant gas in Earth's atmosphere?", options: JSON.stringify(["Oxygen","Carbon Dioxide","Nitrogen","Argon"]), correctAnswer: "Nitrogen", funFact: "Nitrogen makes up about 78% of the air we breathe, with oxygen at 21%. The remaining 1% is mostly argon, carbon dioxide, and trace gases." },
  { category: "Science", difficulty: "MEDIUM", question: "How many bones does an adult human have?", options: JSON.stringify(["197","206","212","232"]), correctAnswer: "206", funFact: "Adults have 206 bones — but babies are born with about 300! Many bones, like those in the skull and spine, fuse together as we grow." },
  { category: "Science", difficulty: "HARD", question: "Which human organ has its own independent nervous system and is often called the 'second brain'?", options: JSON.stringify(["Liver","Heart","Gut","Lungs"]), correctAnswer: "Gut", funFact: "The gut contains about 500 million neurons — more than in a rat's brain — connected directly to the brain via the vagus nerve. This enteric nervous system can act independently and even influence mood and anxiety." },

  // ── HISTORY ───────────────────────────────────────────────────────────────
  { category: "History", difficulty: "EASY", question: "Which ancient civilization built Machu Picchu?", options: JSON.stringify(["Maya","Aztec","Inca","Olmec"]), correctAnswer: "Inca", funFact: "Machu Picchu was built by the Inca around 1450 as a royal estate in the Andes at 2,430 meters above sea level. It was abandoned about a century later during the Spanish conquest and never discovered by the Spanish." },
  { category: "History", difficulty: "EASY", question: "Who was the last pharaoh of ancient Egypt?", options: JSON.stringify(["Ramesses II","Cleopatra VII","Tutankhamun","Hatshepsut"]), correctAnswer: "Cleopatra VII", funFact: "Cleopatra VII ruled Egypt's Ptolemaic Kingdom until 30 BC, when Egypt became a Roman province. She was more famous for her intelligence and political skill than her looks — she spoke nine languages." },
  { category: "History", difficulty: "MEDIUM", question: "In which year did World War II end?", options: JSON.stringify(["1943","1944","1945","1946"]), correctAnswer: "1945", funFact: "World War II ended in 1945 — Europe surrendered in May (VE Day) and Japan in September (VJ Day) after the atomic bombs. It was the deadliest conflict in history, with 70–85 million casualties." },
  { category: "History", difficulty: "HARD", question: "Which ancient library was destroyed by fire around 273 AD and once housed hundreds of thousands of scrolls?", options: JSON.stringify(["Library of Celsus","Library of Alexandria","Library of Ashurbanipal","Library of Pergamum"]), correctAnswer: "Library of Alexandria", funFact: "The Library of Alexandria was the largest in the ancient world, first founded around 283 BC by Ptolemy I. It may have held up to 700,000 scrolls. Although famously 'burned,' it actually declined gradually through fires, budget cuts, and neglect over centuries." },

  // ── GEOGRAPHY ─────────────────────────────────────────────────────────────
  { category: "Geography", difficulty: "EASY", question: "What is the largest ocean on Earth?", options: JSON.stringify(["Atlantic","Indian","Pacific","Arctic"]), correctAnswer: "Pacific", funFact: "The Pacific covers about 165 million square kilometers — more than all of Earth's land combined. It also holds the Mariana Trench, the deepest point on the planet at nearly 11,000 meters." },
  { category: "Geography", difficulty: "EASY", question: "On which continent is the Sahara Desert located?", options: JSON.stringify(["Asia","Africa","Australia","South America"]), correctAnswer: "Africa", funFact: "The Sahara spans 11 countries in North Africa and is nearly the size of the United States. Around 7,000 years ago, though, it was green and dotted with lakes and grasslands." },
  { category: "Geography", difficulty: "MEDIUM", question: "What is the capital city of Japan?", options: JSON.stringify(["Osaka","Kyoto","Tokyo","Sapporo"]), correctAnswer: "Tokyo", funFact: "Tokyo is the world's largest metropolitan area, home to over 37 million people. It was historically called Edo until 1868, when it became the imperial capital and was renamed Tokyo, meaning 'Eastern Capital.'" },
  { category: "Geography", difficulty: "HARD", question: "Which country has the most time zones of any country on Earth?", options: JSON.stringify(["Russia","United States","France","China"]), correctAnswer: "France", funFact: "France holds 13 time zones — but almost all are overseas territories scattered across the globe, from French Polynesia to New Caledonia. Including overseas territories, France also edges out the US and Russia." },

  // ── TECHNOLOGY ────────────────────────────────────────────────────────────
  { category: "Technology", difficulty: "EASY", question: "Which company owns and develops the Android operating system?", options: JSON.stringify(["Apple","Microsoft","Google","Samsung"]), correctAnswer: "Google", funFact: "Android was originally built by Android Inc., which Google bought in 2005 for about $50 million. Today it powers roughly 70% of the world's smartphones." },
  { category: "Technology", difficulty: "EASY", question: "What does 'RAM' stand for?", options: JSON.stringify(["Read Access Memory","Random Access Memory","Rapid Access Module","Redundant Array Memory"]), correctAnswer: "Random Access Memory", funFact: "RAM is your computer's short-term memory. Unlike storage, it forgets everything the moment power is cut — which is why an unsaved document disappears after a sudden shutdown." },
  { category: "Technology", difficulty: "MEDIUM", question: "In which year was the World Wide Web invented?", options: JSON.stringify(["1985","1989","1993","1996"]), correctAnswer: "1989", funFact: "Tim Berners-Lee proposed the World Wide Web in 1989 while at CERN in Switzerland. The very first website, info.cern.ch, is still online today as a relic of the web's dawn." },
  { category: "Technology", difficulty: "HARD", question: "What is the name of the open-source operating system kernel created by Linus Torvalds in 1991?", options: JSON.stringify(["BSD","Linux","GNU","Unix"]), correctAnswer: "Linux", funFact: "Linus Torvalds wrote the Linux kernel at age 21 in Finland, releasing it in 1991 as a hobby project. Today Linux runs most of the internet's servers, all Android phones, and even the Mars rovers." },

  // ── GAMING ────────────────────────────────────────────────────────────────
  { category: "Gaming", difficulty: "EASY", question: "Which video game franchise features the adventurer Lara Croft?", options: JSON.stringify(["Metal Gear","Resident Evil","Tomb Raider","Silent Hill"]), correctAnswer: "Tomb Raider", funFact: "Lara Croft debuted in 1996 and became one of the most recognizable characters in gaming. Her original design was invented while the developers realized a male hero was too generic — so they created a female lead." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which game series features the hedgehog Sonic's blue rival Shadow?", options: JSON.stringify(["Mario","Sonic the Hedgehog","Crash Bandicoot","Rayman"]), correctAnswer: "Sonic the Hedgehog", funFact: "Shadow the Hedgehog debuted in 2001's Sonic Adventure 2 as the 'Ultimate Life Form.' He was designed as an anti-Sonic with a brooding personality and is voiced by Keanu Reeves in the 2024 Sonic movies." },
  { category: "Gaming", difficulty: "MEDIUM", question: "In which game series do players catch creatures inside Poké Balls?", options: JSON.stringify(["Digimon","Pokémon","Monster Hunter","Yo-kai Watch"]), correctAnswer: "Pokémon", funFact: "Pokémon began as a Game Boy RPG in 1996 by Satoshi Tajiri, inspired by his childhood hobby of collecting insects. The franchise is now the highest-earning media franchise ever, surpassing Star Wars and Marvel." },
  { category: "Gaming", difficulty: "HARD", question: "Which game studio developed 'The Legend of Zelda: Breath of the Wild'?", options: JSON.stringify(["Square Enix","Capcom","Nintendo","Bandai Namco"]), correctAnswer: "Nintendo", funFact: "Breath of the Wild (2017) was developed by Nintendo EPD over five years, with a huge open world inspired by Japanese architecture and scale model dioramas. It went on to sell over 30 million copies and won Game of the Year in 2017." },

  // ── MOVIES ────────────────────────────────────────────────────────────────
  { category: "Movies", difficulty: "EASY", question: "Which animated film follows a boy trapped in the Land of the Dead during Día de Muertos?", options: JSON.stringify(["Moana","Encanto","Coco","The Book of Life"]), correctAnswer: "Coco", funFact: "Coco (2017) was inspired by the Mexican holiday Día de los Muertos and took over 100,000 unique art assets. Its 'Remember Me' theme won the Oscar for Best Original Song." },
  { category: "Movies", difficulty: "EASY", question: "Who voiced Dory in 'Finding Nemo' and 'Finding Dory'?", options: JSON.stringify(["Ellen DeGeneres","Jennifer Aniston","Tina Fey","Meryl Streep"]), correctAnswer: "Ellen DeGeneres", funFact: "Ellen DeGeneres brought the forgetful blue tang Dory to life and even co-produced the sequel. Dory was so beloved that Finding Dory (2016) earned over $1 billion at the box office." },
  { category: "Movies", difficulty: "MEDIUM", question: "What was the first film in the Marvel Cinematic Universe?", options: JSON.stringify(["Hulk","Iron Man","Thor","Captain America: The First Avenger"]), correctAnswer: "Iron Man", funFact: "Iron Man (2008) launched the MCU with a modest budget of $140 million. Its massive success convinced Marvel it could build a shared universe — and the connection was teased in a post-credits scene with Nick Fury." },
  { category: "Movies", difficulty: "HARD", question: "Who directed the film 'Schindler's List'?", options: JSON.stringify(["Steven Spielberg","Martin Scorsese","Quentin Tarantino","Roman Polanski"]), correctAnswer: "Steven Spielberg", funFact: "Steven Spielberg directed Schindler's List (1993) after famously declining to first, feeling he wasn't ready. He worked for free on the film, donating his salary to his Shoah Foundation which preserves Holocaust survivor testimonies." },

  // ── MUSIC ─────────────────────────────────────────────────────────────────
  { category: "Music", difficulty: "EASY", question: "Which pop star released the hit song 'Bad Guy' in 2019?", options: JSON.stringify(["Ariana Grande","Billie Eilish","Dua Lipa","Halsey"]), correctAnswer: "Billie Eilish", funFact: "Billie Eilish wrote 'Bad Guy' in her childhood bedroom with her brother Finneas. At 18, she became the youngest artist ever to win all four major Grammys — sweeping Record, Song, Album, and New Artist in 2020." },
  { category: "Music", difficulty: "EASY", question: "How many strings does a standard guitar have?", options: JSON.stringify(["4","5","6","7"]), correctAnswer: "6", funFact: "The six-string guitar in its modern form was standardized in the 1800s in Spain. Basses typically have 4 strings and guitars can have 7 or 12, but the classic six-string tuning (EADGBE) dominates popular music." },
  { category: "Music", difficulty: "MEDIUM", question: "Which Filipino band sang the 2001 hit 'Your Love'?", options: JSON.stringify(["Eraserheads","Rivermaya","Parokya ni Edgar","Alamid"]), correctAnswer: "Alamid", funFact: "'Your Love' was released by Alamid and remains one of the most beloved OPM ballads. It is a school-band and karaoke staple across the Philippines — often requested at every reunion party." },
  { category: "Music", difficulty: "HARD", question: "Which classical composer continued composing even after losing his hearing completely?", options: JSON.stringify(["Mozart","Bach","Beethoven","Chopin"]), correctAnswer: "Beethoven", funFact: "Ludwig van Beethoven began losing his hearing in his mid-20s and was nearly deaf by his 40s. He composed his iconic Ninth Symphony completely deaf — famously 'conducting' its 1824 premiere by following a page-turner's cues." },

  // ── SPORTS ────────────────────────────────────────────────────────────────
  { category: "Sports", difficulty: "EASY", question: "What is a score of zero called in tennis?", options: JSON.stringify(["Duck","Zero","Love","Nil"]), correctAnswer: "Love", funFact: "In tennis, zero is called 'love' — likely from the French 'l'oeuf,' meaning 'the egg,' a shape that resembles the number zero. Point values follow an odd sequence: 15, 30, 40, game." },
  { category: "Sports", difficulty: "EASY", question: "How many periods is an ice hockey game divided into?", options: JSON.stringify(["2","3","4","5"]), correctAnswer: "3", funFact: "An NHL hockey game has three 20-minute periods with two intermissions of about 18 minutes. If tied after regulation, the game heads to sudden-death overtime — and possibly a shootout." },
  { category: "Sports", difficulty: "MEDIUM", question: "Which sport is played at the Wimbledon Championships?", options: JSON.stringify(["Cricket","Tennis","Golf","Squash"]), correctAnswer: "Tennis", funFact: "Wimbledon is the oldest tennis tournament in the world, founded in 1877 in London. It is the only Grand Slam still played on grass, and players must wear predominantly white clothing." },
  { category: "Sports", difficulty: "HARD", question: "In which Olympic sport would you perform the 'triple axel'?", options: JSON.stringify(["Gymnastics","Figure Skating","Ski Jumping","Freestyle Skiing"]), correctAnswer: "Figure Skating", funFact: "The triple axel requires three and a half rotations in the air — the extra half turn makes it one of the hardest jumps ever. It was first landed in competition by Vern Taylor in 1978; women didn't land it until Midori Ito in 1988." },

  // ── POP CULTURE ───────────────────────────────────────────────────────────
  { category: "Pop Culture", difficulty: "EASY", question: "Which video platform is known for short looping videos and is owned by ByteDance?", options: JSON.stringify(["YouTube","TikTok","Twitch","Vimeo"]), correctAnswer: "TikTok", funFact: "TikTok launched internationally in 2018 as the overseas version of Chinese app Douyin. By 2024 it surpassed 1 billion users — making it one of the fastest-growing platforms in history." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which streaming series gave us the catchphrase 'This is the way'?", options: JSON.stringify(["Stranger Things","The Mandalorian","The Witcher","Squid Game"]), correctAnswer: "The Mandalorian", funFact: "'This is the way' is the mantra of the Mandalorian warrior cult, first spoken by Pedro Pascal's Din Djarin in 2019. The phrase is widely credited for making Baby Yoda (Grogu) a pop culture phenomenon." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "Which Korean series became the most-watched show on Netflix within weeks of its 2021 release?", options: JSON.stringify(["Money Heist","Squid Game","All of Us Are Dead","Sweet Home"]), correctAnswer: "Squid Game", funFact: "Squid Game (2021) became Netflix's biggest debut ever with 1.65 billion hours watched in its first month. Creator Hwang Dong-hyuk spent 12 years writing the script and reportedly lost several teeth from stress during production." },
  { category: "Pop Culture", difficulty: "HARD", question: "Which anime film, directed by Mamoru Hosoda, tells the story of a shy girl who becomes a virtual pop idol in an online world?", options: JSON.stringify(["Your Name","Belle","Weathering with You","A Silent Voice"]), correctAnswer: "Belle", funFact: "Belle (2021) mixes a modern retelling of Beauty and the Beast with a vast virtual network called 'U.' It was the director's most ambitious film to date and used a complex mix of traditional and 3D animation." },

  // ── PHILIPPINES ───────────────────────────────────────────────────────────
  { category: "Philippines", difficulty: "EASY", question: "What is the national costume for Filipino men?", options: JSON.stringify(["Kimono","Barong Tagalog","Salakot","Cheongsam"]), correctAnswer: "Barong Tagalog", funFact: "The Barong Tagalog is a formal embroidered shirt worn untucked, derived from the Spanish 'baro.' It became the official national attire in 1975 via Presidential Decree and is worn at weddings and state functions." },
  { category: "Philippines", difficulty: "EASY", question: "What is the traditional Filipino martial art called 'Arnis' also known as?", options: JSON.stringify(["Eskrima","Krav Maga","Aikido","Tae Kwon Do"]), correctAnswer: "Eskrima", funFact: "Arnis — also called Eskrima or Kali — is the national martial art of the Philippines and the only one recognized as a UNESCO intangible heritage. It centers on stick fighting but includes empty-hand techniques." },
  { category: "Philippines", difficulty: "MEDIUM", question: "Which region of the Philippines is famous for the Batad rice terraces?", options: JSON.stringify(["Ilocos","Ifugao","Palawan","Bicol"]), correctAnswer: "Ifugao", funFact: "The Batad rice terraces in Ifugao, carved about 2,000 years ago, form a stunning amphitheater of paddies. UNESCO recognizes the Rice Terraces of the Philippine Cordilleras as a living cultural landscape." },
  { category: "Philippines", difficulty: "HARD", question: "Which active volcano is the highest point in the Philippines?", options: JSON.stringify(["Mayon","Mount Apo","Taal","Pinatubo"]), correctAnswer: "Mount Apo", funFact: "Mount Apo in Mindanao is the highest mountain in the Philippines at 2,954 meters — and it's technically a dormant volcano, not active. It is also home to the endangered Philippine eagle." },

  // ── FOOD & DRINKS ─────────────────────────────────────────────────────────
  { category: "Food & Drinks", difficulty: "EASY", question: "What is considered the national dish of the Philippines?", options: JSON.stringify(["Sinigang","Lechon","Adobo","Kare-Kare"]), correctAnswer: "Adobo", funFact: "Adobo is meat braised in soy sauce, vinegar, garlic, and peppercorns. Its vinegar base made it naturally last longer in the tropical heat, and it was already being described by early Spanish colonists in the 1600s." },
  { category: "Food & Drinks", difficulty: "EASY", question: "Which icy Filipino dessert is topped with ube, leche flan, and sweet beans?", options: JSON.stringify(["Buko Pandan","Halo-halo","Suman","Ginataan"]), correctAnswer: "Halo-halo", funFact: "Halo-halo translates to 'mix-mix' in Tagalog — and true to its name, it layers shaved ice with fruits, ube, flan, and dozens of toppings. It is officially regarded as a national dessert." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "Which country is the world's largest producer of coffee?", options: JSON.stringify(["Vietnam","Colombia","Brazil","Ethiopia"]), correctAnswer: "Brazil", funFact: "Brazil produces roughly one-third of the world's coffee, with over 2.5 million hectares planted. Ethiopia — coffee's birthplace — ranks lower in volume but is famous for some of the world's most prized beans." },
  { category: "Food & Drinks", difficulty: "HARD", question: "Which Filipino street food is made from a fertilized duck egg incubated for about 18 days?", options: JSON.stringify(["Itlog na Maalat","Balut","Penoy","Kwek-Kwek"]), correctAnswer: "Balut", funFact: "Balut is a popular Filipino delicacy — a fertilized duck egg boiled and eaten from the shell with salt and chili vinegar. It is rich in protein and is a classic pulutan (drinking snack)." },

  // ── TV SHOWS & ANIME ──────────────────────────────────────────────────────
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which anime follows the young hunter Gon Freecss on his journey to find his father?", options: JSON.stringify(["My Hero Academia","Hunter x Hunter","Demon Slayer","Bleach"]), correctAnswer: "Hunter x Hunter", funFact: "Hunter x Hunter was created by Yoshihiro Togashi, the same author of Yu Yu Hakusho. It is one of the most acclaimed shonen series, though it is famous for its frequent, long hiatuses due to the author's health." },
  { category: "TV Shows & Anime", difficulty: "EASY", question: "What is the primary breathing style taught to Tanjiro Kamado in 'Demon Slayer'?", options: JSON.stringify(["Water Breathing","Fire Breathing","Wind Breathing","Thunder Breathing"]), correctAnswer: "Water Breathing", funFact: "Tanjiro learns Water Breathing, a graceful style mirroring flowing water, from former Hashira Sakonji Urokodaki. Its first form resembles the calm surface of water: Water Surface Slash." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which anime centers on a teenage gamer trapped inside a virtual reality MMORPG where death in-game means death in real life?", options: JSON.stringify(["Code Geass","Gurren Lagann","Sword Art Online","One Punch Man"]), correctAnswer: "Sword Art Online", funFact: "Sword Art Online (2012) follows Kirito, who is trapped in the VR game SAO after creator Akihiko Kayaba locks players in. It became one of the most commercially successful anime franchises, spawning multiple sequels and films." },
  { category: "TV Shows & Anime", difficulty: "HARD", question: "Which anime series features giant humanoid machines controlled by pilots, set in the futuristic underground home of humanity?", options: JSON.stringify(["Gundam","Neon Genesis Evangelion","Macross","Code Geass"]), correctAnswer: "Neon Genesis Evangelion", funFact: "Neon Genesis Evangelion (1995) redefined the mecha genre as a psychological drama, centered on depressed teen pilots and a cryptic conspiracy. Its unconventional ending sparked years of debate and led director Hideaki Anno to produce an entire alternate film ending." },

  // ── ANIMALS ───────────────────────────────────────────────────────────────
  { category: "Animals", difficulty: "EASY", question: "What is the fastest fish in the ocean?", options: JSON.stringify(["Tuna","Sailfish","Great White Shark","Marlin"]), correctAnswer: "Sailfish", funFact: "Sailfish can burst past 110 km/h in short sprints, making them the ocean's fastest swimmers. They use their long bills to slash at schools of prey rather than simply biting." },
  { category: "Animals", difficulty: "EASY", question: "Which insect produces honey in hexagonal wax combs?", options: JSON.stringify(["Wasp","Honeybee","Ant","Termite"]), correctAnswer: "Honeybee", funFact: "Honeybees build hexagons because the shape packs the most honey in the least wax — a perfect geometric efficiency. A single colony of 20,000 bees can produce about 30 kg of honey per year." },
  { category: "Animals", difficulty: "MEDIUM", question: "What is the largest reptile in the world?", options: JSON.stringify(["Komodo dragon","Green anaconda","Saltwater crocodile","American alligator"]), correctAnswer: "Saltwater crocodile", funFact: "Saltwater crocodiles can exceed 6 meters and weigh over 1,000 kg. They can also swim long distances at sea — which is how they colonized islands across Southeast Asia and Australia." },
  { category: "Animals", difficulty: "HARD", question: "Which amphibian can regrow lost limbs, tail, and even parts of its heart and brain?", options: JSON.stringify(["Frog","Salamander","Axolotl","Newt"]), correctAnswer: "Axolotl", funFact: "The axolotl is the only vertebrate that can regenerate entire limbs, tails, and even portions of its heart and brain — and it does so without scarring. Scientists study it intensely hoping to unlock similar healing in humans." },

  // ── LOGIC ─────────────────────────────────────────────────────────────────
  { category: "Logic", difficulty: "EASY", question: "What number comes next in the sequence: 2, 3, 5, 7, 11, __?", options: JSON.stringify(["12","13","14","15"]), correctAnswer: "13", funFact: "The sequence lists the prime numbers — numbers divisible only by 1 and themselves. After 11 comes 13, since 12, 14, and 15 all have other factors." },
  { category: "Logic", difficulty: "EASY", question: "A farmer has 17 sheep. All but 9 run away. How many sheep are left?", options: JSON.stringify(["8","9","0","17"]), correctAnswer: "9", funFact: "The phrase 'all but 9' means 9 remain — none of the sheep actually died. Classic trick questions like this one test whether you read carefully instead of solving instantly." },
  { category: "Logic", difficulty: "MEDIUM", question: "A clock shows 3:15. What is the angle between the hour hand and the minute hand?", options: JSON.stringify(["0 degrees","7.5 degrees","15 degrees","22.5 degrees"]), correctAnswer: "7.5 degrees", funFact: "At 3:15, the minute hand points exactly at 3, but the hour hand has already moved a quarter of the way past 3 — one quarter of 30 degrees (the space between numbers) is 7.5 degrees. Small gaps like this are why analog clock puzzles are so sneaky." },
  { category: "Logic", difficulty: "HARD", question: "In the Monty Hall problem, after the host opens an empty door, what should you do?", options: JSON.stringify(["Switch doors — it doubles your odds","Stay with your first choice","It doesn't matter","Flip a coin"]), correctAnswer: "Switch doors — it doubles your odds", funFact: "When you first pick, you have a 1/3 chance. The host always reveals a losing door, which concentrates the remaining probability — so switching wins 2/3 of the time. Even many PhD mathematicians initially refused to believe it!" },

  // ── WORLD WONDERS ─────────────────────────────────────────────────────────
  { category: "World Wonders", difficulty: "EASY", question: "Which landmark sits atop Corcovado mountain in Rio de Janeiro?", options: JSON.stringify(["Statue of Liberty","Christ the Redeemer","Moai Statues","Taj Mahal"]), correctAnswer: "Christ the Redeemer", funFact: "Christ the Redeemer is a 30-meter Art Deco statue completed in 1931 on Corcovado peak. It is often struck by lightning, and in 2016 a storm snapped one of its thumbs — repaired within days." },
  { category: "World Wonders", difficulty: "EASY", question: "What is the official name of the clock tower famously called 'Big Ben'?", options: JSON.stringify(["Elizabeth Tower","Victoria Tower","Windsor Tower","Westminster Tower"]), correctAnswer: "Elizabeth Tower", funFact: "Big Ben is technically just the name of the giant 13.5-ton bell inside the tower. The tower itself was renamed 'Elizabeth Tower' in 2012 for Queen Elizabeth II's Diamond Jubilee." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which New Seven Wonders site can be found in Jordan's desert?", options: JSON.stringify(["Petra","Angkor Wat","Chichén Itzá","Machu Picchu"]), correctAnswer: "Petra", funFact: "Petra, carved into pink sandstone cliffs by the Nabataeans around 300 BC, was a filming location for Indiana Jones and the Last Crusade. It faded into obscurity until Swiss explorer Johann Ludwig Burckhardt rediscovered it in 1812." },
  { category: "World Wonders", difficulty: "HARD", question: "Which of the Seven Wonders of the Ancient World was a giant bronze statue of the sun god Helios on Rhodes?", options: JSON.stringify(["Colossus of Rhodes","Temple of Artemis","Statue of Zeus","Mausoleum at Halicarnassus"]), correctAnswer: "Colossus of Rhodes", funFact: "The Colossus of Rhodes stood roughly 33 meters tall, about the height of today's Statue of Liberty. Erected in 280 BC, it survived only 54 years before a severe earthquake toppled it — and its fallen remains attracted visitors for centuries." },
];

const extraQuestions6 = [
  { category: "General Knowledge", difficulty: "EASY", question: "What is the chemical symbol for gold?", options: JSON.stringify(["Ag","Au","Fe","Cu"]), correctAnswer: "Au", funFact: "Au comes from the Latin 'aurum'. Gold has been prized since antiquity — the first known gold jewelry dates to 4000 BC in ancient Bulgaria." },
  { category: "General Knowledge", difficulty: "EASY", question: "Which planet has the most violent storms in the solar system?", options: JSON.stringify(["Mars","Neptune","Saturn","Jupiter"]), correctAnswer: "Jupiter", funFact: "Jupiter's Great Red Spot is a storm larger than Earth that has raged for at least 400 years. Wind speeds there reach 430 mph (700 km/h)." },
  { category: "General Knowledge", difficulty: "EASY", question: "What is the world's oldest known written language?", options: JSON.stringify(["Sumerian","Latin","Greek"]), correctAnswer: "Sumerian", funFact: "Sumerian emerged around 3400 BC in ancient Mesopotamia. The earliest known writing is the Kish tablet. It survived as a liturgical language until the 1st century AD." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "Which gemstone is a variety of the mineral corundum?", options: JSON.stringify(["Sapphire","Emerald","Topaz","Ruby"]), correctAnswer: "Ruby", funFact: "Ruby is red corundum; all other corundum colors are called sapphire. Pure corundum is colorless. Trace elements like chromium give ruby its red hue." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "What is the hardest natural substance on Earth?", options: JSON.stringify(["Quartz","Topaz","Corundum","Diamond"]), correctAnswer: "Diamond", funFact: "Diamond ranks 10 on the Mohs hardness scale. Its carbon atoms form a rigid tetrahedral lattice, making it the hardest known natural material — though lonsdaleite may theoretically be harder." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "Which country hosted the 2024 Summer Olympics?", options: JSON.stringify(["Japan","Australia","Germany","France"]), correctAnswer: "France", funFact: "Paris hosted the 2024 Summer Olympics (July-August 2024), the fourth time France has hosted the Games. The opening ceremony took place on the Seine River rather than a stadium." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "How many bones does a newborn baby have?", options: JSON.stringify(["206","250","320","270"]), correctAnswer: "270", funFact: "Babies are born with around 270-300 bones, many of which are cartilage. As they grow, some fuse (like skull sutures), leaving 206 bones in adulthood." },
  { category: "General Knowledge", difficulty: "HARD", question: "What was the name of the first photograph ever taken from space?", options: JSON.stringify(["Lunar 1","Apollo 11","Vostok 1","Earthrise"]), correctAnswer: "Earthrise", funFact: "Earthrise was captured on December 24, 1968, by astronaut William Anders aboard Apollo 8. It became an iconic image of the environmental movement and is often credited with inspiring Earth Day." },
  { category: "General Knowledge", difficulty: "HARD", question: "Which country invented the modern postal stamp?", options: JSON.stringify(["France","Germany","USA","Great Britain"]), correctAnswer: "Great Britain", funFact: "The Penny Black, issued May 1, 1840, was the world's first adhesive postage stamp. It featured Queen Victoria and was the brainchild of Rowland Hill to reform Britain's mail system." },
  { category: "General Knowledge", difficulty: "HARD", question: "What is the deepest cave in the world?", options: JSON.stringify(["Mammoth Cave","Ojos del Salado","Lechuguilla Cave","Krubera-Voronya Cave"]), correctAnswer: "Krubera-Voronya Cave", funFact: "Located in Georgia's Arabika Massif, Krubera-Voronya Cave reaches over 2,197 meters deep. Only a handful of cavers have reached its deepest point, discovered in 2001." },
  { category: "General Knowledge", difficulty: "HARD", question: "What is the only letter that never appears in any U.S. state name?", options: JSON.stringify(["Z","J","X","Q"]), correctAnswer: "Q", funFact: "The letters J and Z also appear in few state names, but Q is the only letter of the English alphabet that appears in zero U.S. state names — not even in 'Quincy' or any territory." },
  { category: "General Knowledge", difficulty: "EASY", question: "What is the atomic number of carbon?", options: JSON.stringify(["4","8","12","6"]), correctAnswer: "6", funFact: "Carbon's atomic number is 6 — it has 6 protons. It sits in Group 14 of the periodic table and is the backbone of all known organic chemistry, forming up to 4 covalent bonds." },
  { category: "General Knowledge", difficulty: "EASY", question: "What gas do fireflies need to create light?", options: JSON.stringify(["Nitrogen","Hydrogen","Carbon Dioxide","Oxygen"]), correctAnswer: "Oxygen", funFact: "Fireflies produce light via luciferin oxidation, which requires oxygen from the air. The bioluminescence reaction needs O₂ — no gas is produced by the firefly itself, it consumes oxygen." },
  { category: "Science", difficulty: "EASY", question: "Which planet is closest to the Sun?", options: JSON.stringify(["Venus","Mars","Jupiter","Mercury"]), correctAnswer: "Mercury", funFact: "Mercury orbits the Sun at an average distance of 58 million km. Despite being closest, it is not the hottest planet — Venus holds that record due to its thick greenhouse atmosphere." },
  { category: "Science", difficulty: "EASY", question: "What is the powerhouse of the cell?", options: JSON.stringify(["Nucleus","Ribosome","Lysosome","Mitochondria"]), correctAnswer: "Mitochondria", funFact: "Mitochondria generate ATP through cellular respiration. They have their own DNA (maternal inheritance), suggesting ancient symbiotic bacteria were engulfed by ancestral cells." },
  { category: "Science", difficulty: "EASY", question: "What is water's chemical formula?", options: JSON.stringify(["CO₂","NaCl","O₂","H₂O"]), correctAnswer: "H₂O", funFact: "Water is H₂O — two hydrogen atoms covalently bonded to one oxygen atom per molecule. It is the only common substance that exists naturally as solid, liquid, and gas on Earth's surface." },
  { category: "Science", difficulty: "MEDIUM", question: "Which particle carries the strong nuclear force?", options: JSON.stringify(["Photon","Graviton","W boson","Gluon"]), correctAnswer: "Gluon", funFact: "Gluons are the force carriers of the strong interaction, which binds quarks inside protons and neutrons. They themselves carry 'color charge' — unlike photons, which are electrically neutral." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the SI unit of electrical resistance?", options: JSON.stringify(["Volt","Ampere","Watt","Ohm"]), correctAnswer: "Ohm", funFact: "Named after Georg Simon Ohm, the ohm is the SI unit of resistance. It is defined as the resistance between two points of a conductor when a constant potential difference of 1 volt produces 1 ampere." },
  { category: "Science", difficulty: "MEDIUM", question: "Which type of star is our Sun classified as?", options: JSON.stringify(["Red Giant","White Dwarf","Blue Giant","Yellow Dwarf"]), correctAnswer: "Yellow Dwarf", funFact: "The Sun is a G-type main-sequence star (G2V), informally a 'yellow dwarf.' It has been fusing hydrogen for about 4.6 billion years and has roughly 5 billion years left before becoming a red giant." },
  { category: "Science", difficulty: "MEDIUM", question: "Which blood type is known as the 'universal donor'?", options: JSON.stringify(["A-positive","B-negative","AB-positive","O-negative"]), correctAnswer: "O-negative", funFact: "O-negative blood lacks A, B, and Rh antigens, so it can be transfused to almost anyone in emergencies. Only about 7% of the population has it, making it the most sought-after type in hospitals." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the process called when plants release water vapor through their leaves?", options: JSON.stringify(["Photosynthesis","Respiration","Evaporation","Transpiration"]), correctAnswer: "Transpiration", funFact: "Transpiration pulls water up from roots through xylem vessels and releases it as vapor from stomata. It accounts for about 10% of atmospheric moisture and drives the water cycle in forests." },
  { category: "Science", difficulty: "MEDIUM", question: "Which metal is liquid at room temperature?", options: JSON.stringify(["Gallium","Cesium","Bromine","Mercury"]), correctAnswer: "Mercury", funFact: "Mercury is the only metal that is liquid near room temperature (melts at -38.83°C). It was historically used in thermometers, but its toxicity has led to replacements in most modern devices." },
  { category: "Science", difficulty: "HARD", question: "What is the theoretical speed limit in the universe?", options: JSON.stringify(["Speed of sound","Infinite","Mach 10","Speed of light"]), correctAnswer: "Speed of light", funFact: "In vacuum, the speed of light is 299,792,458 m/s. It is the universal speed limit for matter and information, per Einstein's special relativity — nothing with mass can reach or exceed it." },
  { category: "Science", difficulty: "HARD", question: "Which enzyme is responsible for unzipping DNA during replication?", options: JSON.stringify(["Polymerase","Ligase","Topoisomerase","Helicase"]), correctAnswer: "Helicase", funFact: "Helicase breaks the hydrogen bonds between complementary base pairs, separating the double helix into two single strands. It works ahead of the replication fork, often paired with topoisomerase." },
  { category: "Science", difficulty: "HARD", question: "Which subatomic particle has a fractional electric charge?", options: JSON.stringify(["Electron","Proton","Neutron","Quark"]), correctAnswer: "Quark", funFact: "Quarks carry fractional charges (+2/3 or -1/3 of the elementary charge). They are never observed in isolation due to color confinement; they are always bound in groups (protons = uud, neutrons = udd)."},
  { category: "Science", difficulty: "HARD", question: "What is the name of the theorized particle that gives mass to other particles?", options: JSON.stringify(["Graviton","Photon","Tachyon","Higgs boson"]), correctAnswer: "Higgs boson", funFact: "The Higgs boson was confirmed at CERN's Large Hadron Collider in 2012. It arises from the Higgs field permeating the universe — particles interacting with it acquire mass, a mechanism proposed in 1964 by Englert and Higgs." },
  { category: "Science", difficulty: "EASY", question: "What is the most abundant gas in Earth's atmosphere?", options: JSON.stringify(["Oxygen","Argon","Carbon Dioxide","Nitrogen"]), correctAnswer: "Nitrogen", funFact: "Nitrogen makes up about 78% of the air we breathe, with oxygen at 21%. The remaining 1% is mostly argon, carbon dioxide, and trace gases." },
  { category: "History", difficulty: "EASY", question: "Who discovered America in 1492?", options: JSON.stringify(["Vasco da Gama","Ferdinand Magellan","Amerigo Vespucci","Christopher Columbus"]), correctAnswer: "Christopher Columbus", funFact: "Columbus made four voyages between 1492 and 1504, reaching the Caribbean. His voyages launched Spanish colonization, though Vikings and others had reached the Americas centuries earlier." },
  { category: "History", difficulty: "EASY", question: "Which ancient civilization built the pyramids of Giza?", options: JSON.stringify(["Romans","Greeks","Persians","Ancient Egyptians"]), correctAnswer: "Ancient Egyptians", funFact: "The Great Pyramid of Giza was built as a tomb for Pharaoh Khufu around 2560 BC. It used about 2.3 million stone blocks weighing 2.5 tons each and took about 20 years to complete." },
  { category: "History", difficulty: "EASY", question: "In which year did the Berlin Wall fall?", options: JSON.stringify(["1987","1991","1990","1989"]), correctAnswer: "1989", funFact: "The Berlin Wall fell on November 9, 1989. East Germans flooded checkpoints, and it was dismantled in the following weeks. This event symbolized the end of the Cold War division of Europe." },
  { category: "History", difficulty: "MEDIUM", question: "Who wrote 'The Declaration of Independence'?", options: JSON.stringify(["Benjamin Franklin","John Adams","George Washington","Thomas Jefferson"]), correctAnswer: "Thomas Jefferson", funFact: "Thomas Jefferson drafted the Declaration in 1776, drawing on John Locke's philosophy. It was edited by Benjamin Franklin and John Adams before Congress adopted it on July 4, 1776." },
  { category: "History", difficulty: "MEDIUM", question: "Which empire ruled the largest contiguous land empire in history?", options: JSON.stringify(["British Empire","Roman Empire","Ottoman Empire","Mongol Empire"]), correctAnswer: "Mongol Empire", funFact: "The Mongol Empire at its peak around 1270 stretched from Korea to Eastern Europe — about 24 million km². Founded by Genghis Khan, it unified the Silk Road and spread technologies across continents." },
  { category: "History", difficulty: "MEDIUM", question: "Who built the Great Wall of China?", options: JSON.stringify(["Japanese","Korean","Mongolian","Chinese dynasties"]), correctAnswer: "Chinese dynasties", funFact: "The Great Wall was built and rebuilt by multiple Chinese dynasties — the Qin, Han, Ming, and others. The iconic sections seen today were mostly built during the Ming Dynasty (1368-1644)." },
  { category: "History", difficulty: "HARD", question: "Which ancient city was famously destroyed by a volcanic eruption in 79 AD?", options: JSON.stringify(["Herculaneum","Stabiae","Torre Annunziata","Pompeii"]), correctAnswer: "Pompeii", funFact: "Mount Vesuvius buried Pompeii and Herculaneum under ash and pumice in 79 AD. The cities were preserved remarkably — excavations since 1748 reveal carbonized bread, frescoes, and plaster casts of victims." },
  { category: "History", difficulty: "HARD", question: "Which empire fell to the Ottoman Turks when Constantinople was conquered in 1453?", options: JSON.stringify(["Roman Empire","Greek Empire","Persian Empire","Byzantine Empire"]), correctAnswer: "Byzantine Empire", funFact: "The Byzantine Empire fell in 1453 when Sultan Mehmed II conquered Constantinople. The city had stood for over 1,000 years as the seat of the Eastern Roman Empire. The fall marked the end of the medieval Roman world." },
  { category: "History", difficulty: "HARD", question: "What was the name of the first satellite to orbit Earth?", options: JSON.stringify(["Explorer 1","Vostok 1","Apollo 11","Sputnik 1"]), correctAnswer: "Sputnik 1", funFact: "Sputnik 1, launched by the USSR on October 4, 1957, was the first artificial satellite. Its simple radio beep signal announced the Space Age and triggered the U.S.-Soviet space race." },
  { category: "Geography", difficulty: "EASY", question: "Which continent is entirely in the Southern Hemisphere?", options: JSON.stringify(["South America","Africa","Australia","Antarctica"]), correctAnswer: "Antarctica", funFact: "Antarctica is the only continent entirely south of the equator. It is governed by the Antarctic Treaty, which bans military activity and mining and promotes scientific research." },
  { category: "Geography", difficulty: "EASY", question: "What is the largest desert in the world?", options: JSON.stringify(["Sahara","Arabian","Gobi","Antarctic Desert"]), correctAnswer: "Antarctic Desert", funFact: "The Antarctic Desert covers about 14 million km², making it Earth's largest desert. Deserts are defined by low precipitation, not heat — polar deserts are the coldest type." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which country has the most volcanoes?", options: JSON.stringify(["Japan","Chile","Philippines","Indonesia"]), correctAnswer: "Indonesia", funFact: "Indonesia sits on the Pacific Ring of Fire and has over 120 active volcanoes, including Merapi and Tambora. Tambora's 1815 eruption was the most powerful in recorded history." },
  { category: "Geography", difficulty: "MEDIUM", question: "What is the driest continent on Earth?", options: JSON.stringify(["Africa","Australia","South America","Antarctica"]), correctAnswer: "Antarctica", funFact: "Antarctica is the driest, coldest, windiest, and highest continent. Its interior receives less than 50 mm of precipitation annually — technically a polar desert despite being covered in ice." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which country has the most time zones of any sovereign state?", options: JSON.stringify(["Russia","USA","China","France"]), correctAnswer: "France", funFact: "France technically has 12-13 time zones due to its overseas territories scattered globally. This makes it the country with the most time zones, even wider than Russia or the USA." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which river is the longest in South America?", options: JSON.stringify(["Orinoco","Paraná","São Francisco","Amazon River"]), correctAnswer: "Amazon River", funFact: "The Amazon River is the largest by discharge volume and arguably the longest in South America (about 6,400 km). The Nile in Africa traditionally holds the global longest-river title." },
  { category: "Geography", difficulty: "HARD", question: "Which ocean was named after a region, not a person?", options: JSON.stringify(["Atlantic Ocean","Pacific Ocean","Arctic Ocean","Indian Ocean"]), correctAnswer: "Indian Ocean", funFact: "The Indian Ocean is named after India, which historically bordered it and controlled key trade routes. Most oceans are named after continents (Atlantic, Pacific) — the Indian Ocean follows this pattern with a subcontinent." },
  { category: "Geography", difficulty: "HARD", question: "Which strait separates North America from Asia?", options: JSON.stringify(["Torres Strait","Strait of Gibraltar","English Channel","Bering Strait"]), correctAnswer: "Bering Strait", funFact: "The Bering Strait is about 85 km wide at its narrowest, separating Russia (Asia) from Alaska (North America). During ice ages, a land bridge called Beringia connected the two continents." },
  { category: "Technology", difficulty: "EASY", question: "What does 'URL' stand for?", options: JSON.stringify(["Uniform Remote Locator","Universal Resource Locator","United Resource Locator","Uniform Resource Locator"]), correctAnswer: "Uniform Resource Locator", funFact: "A URL is a web address that specifies a resource's location and retrieval method on the internet. It includes protocol, domain, path, and query string — the modern equivalent of a postal address." },
  { category: "Technology", difficulty: "EASY", question: "What does 'Wi-Fi' technically stand for?", options: JSON.stringify(["Wireless Fidelity","World Wide Web","Wireless Forum","It doesn't officially stand for anything"]), correctAnswer: "It doesn't officially stand for anything", funFact: "The Wi-Fi Alliance coined 'Wi-Fi' as a brand name. Many assume it means 'Wireless Fidelity,' but the alliance never officially defined it — it was a marketing name inspired by 'Hi-Fi' audio terminology." },
  { category: "Technology", difficulty: "EASY", question: "Which company developed the Swift programming language?", options: JSON.stringify(["Google","Microsoft","Amazon","Apple"]), correctAnswer: "Apple", funFact: "Apple developed Swift, announced in 2014 by Chris Lattner, to replace Objective-C for iOS and macOS development. It is designed for safety and performance and has open-source compiler support." },
  { category: "Technology", difficulty: "MEDIUM", question: "Which programming language is used to add interactivity to websites?", options: JSON.stringify(["Java","Python","HTML","JavaScript"]), correctAnswer: "JavaScript", funFact: "JavaScript powers dynamic content on 98% of websites. Originally created by Brendan Eich in 10 days (1995), it now runs on servers via Node.js, mobile apps, and even desktop software." },
  { category: "Technology", difficulty: "MEDIUM", question: "What does 'CPU' stand for?", options: JSON.stringify(["Computer Processing Unit","Central Program Unit","Core Processing Unit","Central Processing Unit"]), correctAnswer: "Central Processing Unit", funFact: "The CPU is the brain of a computer, executing instructions. Modern CPUs contain billions of transistors on a single chip. The term has been used since the 1950s to distinguish the processor from external hardware." },
  { category: "Technology", difficulty: "MEDIUM", question: "What does 'GUI' stand for?", options: JSON.stringify(["Graphical Unit Interface","General User Interface","Graphical Universal Interface","Graphical User Interface"]), correctAnswer: "Graphical User Interface", funFact: "A GUI lets users interact with devices through visual elements like icons and windows, replacing text-based command lines. Xerox PARC pioneered it in the 1970s; Apple's Macintosh popularized it in 1984." },
  { category: "Technology", difficulty: "MEDIUM", question: "Which company created the SQL database language?", options: JSON.stringify(["Oracle","Microsoft","MySQL AB","IBM"]), correctAnswer: "IBM", funFact: "IBM's System R project in the 1970s, led by Donald Chamberlin and Raymond Boyce, defined SQL (Structured Query Language). Oracle and other vendors later commercialized it, and it became the relational database standard." },
  { category: "Technology", difficulty: "HARD", question: "What is the name of the open-source JavaScript runtime built on Chrome's V8 engine?", options: JSON.stringify(["Deno","Bun","NPM","Node.js"]), correctAnswer: "Node.js", funFact: "Node.js, created by Ryan Dahl in 2009, uses Google's V8 engine to run JavaScript outside browsers. It uses an event-driven, non-blocking I/O model — making it popular for real-time servers and APIs." },
  { category: "Technology", difficulty: "HARD", question: "What is the name of the protocol that secures web traffic?", options: JSON.stringify(["HTTP","FTPS","SSL","HTTPS"]), correctAnswer: "HTTPS", funFact: "HTTPS wraps HTTP in TLS (Transport Layer Security) encryption, preventing eavesdropping and tampering. The 'S' stands for Secure. Certificate Authorities issue the encryption keys verified by browsers." },
  { category: "Technology", difficulty: "HARD", question: "Which technology uses quantum bits that can be both 0 and 1 simultaneously?", options: JSON.stringify(["Classical computing","Neuromorphic computing","Optical computing","Quantum computing"]), correctAnswer: "Quantum computing", funFact: "Quantum computers use qubits, which exploit superposition and entanglement to process certain problems exponentially faster than classical computers. Current devices are noisy and error-prone but advancing rapidly." },
  { category: "Gaming", difficulty: "EASY", question: "In 'Minecraft', what drops when you kill an Enderman?", options: JSON.stringify(["Gunpowder","String","Blaze Rod","Ender Pearl"]), correctAnswer: "Ender Pearl", funFact: "Ender Pearls are dropped by Endermen and are essential for brewing Eye of Ender, used to locate Strongholds and activate the End Portal. They also teleport the player briefly when thrown." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which game studio developed the 'Dark Souls' series?", options: JSON.stringify(["Capcom","Bandai Namco","Konami","FromSoftware"]), correctAnswer: "FromSoftware", funFact: "FromSoftware created the Dark Souls trilogy starting in 2011. Their precise, punishing combat design became a genre staple. Hidetaka Miyazaki is the studio president and creative director." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which game introduced the concept of a battle royale genre?", options: JSON.stringify(["Fortnite","Apex Legends","Call of Duty: Warzone","PlayerUnknown's Battlegrounds"]), correctAnswer: "PlayerUnknown's Battlegrounds", funFact: "PUBG (2017) popularized the battle royale concept — 100 players parachuting onto an island and fighting to be the last one standing. It was inspired by the Japanese film 'Battle Royale'." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which fighting game series is known for its 'Tier List' rankings?", options: JSON.stringify(["Street Fighter","Tekken","Guilty Gear","Super Smash Bros"]), correctAnswer: "Super Smash Bros", funFact: "Super Smash Bros is famous for its competitive tier list meta, where characters are ranked by tournament performance. The series has hosted major esports events including Apex and EVO." },
  { category: "Gaming", difficulty: "MEDIUM", question: "In 'League of Legends', what are the two opposing factions called?", options: JSON.stringify(["Valoran and Ionia","Piltover and Zaun","Freljord and Shurima","Demacia and Noxus"]), correctAnswer: "Demacia and Noxus", funFact: "In League of Legends, the two main opposing factions are Demacia (order, justice) and Noxus (power, conquest). Players are called 'Summoners' — the factions are not to be confused with the Summoners themselves." },
  { category: "Gaming", difficulty: "HARD", question: "Which studio developed 'Hollow Knight'?", options: JSON.stringify(["Devolver Digital","Supergiant Games","Thunder Lotus","Team Cherry"]), correctAnswer: "Team Cherry", funFact: "Team Cherry, an Australian indie studio of just three people, created Hollow Knight (2017). The Metroidvania earned critical acclaim and over 5 million sales, becoming one of the most successful indie games ever." },
  { category: "Gaming", difficulty: "HARD", question: "Which game won the first-ever Game of the Year award at The Game Awards?", options: JSON.stringify(["Bloodborne","Metal Gear Solid V","Super Mario Maker","The Witcher 3: Wild Hunt"]), correctAnswer: "The Witcher 3: Wild Hunt", funFact: "The Witcher 3: Wild Hunt won Game of the Year at The Game Awards in 2015 — the first year the ceremony was held. It defeated Bloodborne, Metal Gear Solid V, and Super Mario Maker." },
  { category: "Movies", difficulty: "EASY", question: "Which actor played 'James Bond' in the most films?", options: JSON.stringify(["Sean Connery","Pierce Brosnan","Daniel Craig","Roger Moore"]), correctAnswer: "Roger Moore", funFact: "Roger Moore starred as James Bond in seven films (1973-1985), the most of any actor. Sean Connery originated the role, and Daniel Craig is the most recent. Timothy Dalton and Pierce Brosnan also starred." },
  { category: "Movies", difficulty: "EASY", question: "Which 2020 film was based on a DC Comics character played by Margot Robbie?", options: JSON.stringify(["Suicide Squad","Wonder Woman","Catwoman","Birds of Prey"]), correctAnswer: "Birds of Prey", funFact: "'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)' (2020) starred Margot Robbie as Harley Quinn. It was directed by Cathy Yan and celebrated for its vibrant, chaotic action sequences." },
  { category: "Movies", difficulty: "EASY", question: "Which Pixar film features a character named 'WALL-E'?", options: JSON.stringify(["Brave","Inside Out","Up","WALL-E"]), correctAnswer: "WALL-E", funFact: "WALL-E (2008) is Pixar's love story about a small waste-collecting robot on a polluted, abandoned Earth. It won the Academy Award for Best Animated Feature and was praised for its minimal dialogue." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which film won the Palme d'Or at Cannes in 1997?", options: JSON.stringify(["The Thin Red Line","L.A. Confidential","Good Will Hunting","Taste of Cherry"]), correctAnswer: "Taste of Cherry", funFact: "Abbas Kiarostami's 'Taste of Cherry' (1997) won the Palme d'Or. It follows a man driving through Tehran's hills contemplating suicide. The film is a minimalist masterpiece of Iranian cinema." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which director has won the most Best Director Oscars?", options: JSON.stringify(["Frank Capra","Steven Spielberg","Billy Wilder","John Ford"]), correctAnswer: "John Ford", funFact: "John Ford won four Best Director Oscars — for 'The Informer,' 'The Grapes of Wrath,' 'How Green Was My Valley,' and 'The Quiet Man.' He's the most awarded director in Academy history." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which actress played Hermione Granger in the Harry Potter films?", options: JSON.stringify(["Helena Bonham Carter","Katie Leung","Rita Skeeter","Emma Watson"]), correctAnswer: "Emma Watson", funFact: "Emma Watson played Hermione Granger in all eight films (2001-2011). She was just 11 when cast and grew up on screen. She later became a UN Women Goodwill Ambassador and advocate for women's education." },
  { category: "Movies", difficulty: "HARD", question: "Which film was the first to gross over $1 billion worldwide?", options: JSON.stringify(["Avatar","Star Wars: The Force Awakens","Avengers: Endgame","Titanic"]), correctAnswer: "Titanic", funFact: "James Cameron's 'Titanic' (1997) was the first film to gross over $1 billion, eventually earning $2.2 billion. It held that record for 12 years until 'Avatar' surpassed it in 2009." },
  { category: "Movies", difficulty: "HARD", question: "Which actor won three consecutive Best Actor Oscars in the 1930s?", options: JSON.stringify(["Tom Hanks","Daniel Day-Lewis","Jack Nicholson","Clark Gable"]), correctAnswer: "Clark Gable", funFact: "Clark Gable won three consecutive Best Actor Oscars (1932, 1934, 1936) — the only actor to do so in that era. He starred in 'It Happened One Night,' 'Mutiny on the Bounty,' and 'Test Pilot.'"},
  { category: "Music", difficulty: "EASY", question: "Which band sang 'Bohemian Rhapsody'?", options: JSON.stringify(["The Beatles","Led Zeppelin","Pink Floyd","Queen"]), correctAnswer: "Queen", funFact: "Queen's 'Bohemian Rhapsody' (1975) is a six-minute operatic rock epic that defied all radio conventions. Written by Freddie Mercury, it topped charts worldwide and became one of the most iconic rock songs ever." },
  { category: "Music", difficulty: "EASY", question: "How many keys does a standard piano have?", options: JSON.stringify(["76","88","108","88"]), correctAnswer: "88", funFact: "A standard piano has 88 keys — 52 white and 36 black. This range covers 7¼ octaves and has been the standard since Steinway established it in the 1880s." },
  { category: "Music", difficulty: "EASY", question: "Which instrument is known as the 'King of Instruments'?", options: JSON.stringify(["Piano","Violin","Harp","Organ"]), correctAnswer: "Organ", funFact: "The pipe organ is called the 'King of Instruments' due to its massive size, range, and complexity. The largest organs have tens of thousands of pipes and can fill entire cathedrals with sound." },
  { category: "Music", difficulty: "MEDIUM", question: "Which pop singer held the record for most streams on Spotify?", options: JSON.stringify(["Ed Sheeran","Taylor Swift","Bad Bunny","Drake"]), correctAnswer: "Drake", funFact: "Drake surpassed Ed Sheeran's streaming record with over 100 billion streams on Spotify. His frequent-release strategy and viral hits kept him atop the platform, though streaming numbers are debated." },
  { category: "Music", difficulty: "MEDIUM", question: "Which orchestra is based in Vienna and considered one of the world's best?", options: JSON.stringify(["Berlin Philharmonic","London Symphony","Boston Symphony","Vienna Philharmonic"]), correctAnswer: "Vienna Philharmonic", funFact: "The Vienna Philharmonic Orchestra was founded in 1842. Its annual New Year's Concert is broadcast globally. Uniquely, its musicians own the orchestra as a private association and elect their own members." },
  { category: "Music", difficulty: "MEDIUM", question: "Which music genre originated in Jamaica in the late 1960s?", options: JSON.stringify(["Ska","Calypso","Dancehall","Reggae"]), correctAnswer: "Reggae", funFact: "Reggae emerged from ska and rocksteady in Jamaica in the late 1960s. Bob Marley is its most famous ambassador, bringing it to global audiences. It influenced punk, hip-hop, and modern pop significantly." },
  { category: "Music", difficulty: "MEDIUM", question: "Which song held the #1 spot on the Billboard Hot 100 for the longest period in the 1990s?", options: JSON.stringify(["'Macarena' by Los del Río", "'One Sweet Day' by Mariah Carey", "'Despacito' by Luis Fonsi", "'I Will Always Love You' by Whitney Houston"]), correctAnswer: "'I Will Always Love You' by Whitney Houston", funFact: "'I Will Always Love You' by Whitney Houston held #1 for 14 weeks in 1992-93 — the longest of the 1990s. 'One Sweet Day' by Mariah Carey also spent 16 weeks at #1." },
  { category: "Music", difficulty: "HARD", question: "Which composer wrote 'The Four Seasons'?", options: JSON.stringify(["Bach","Mozart","Handel","Vivaldi"]), correctAnswer: "Vivaldi", funFact: "Antonio Vivaldi composed 'The Four Seasons' (1725), four violin concertos each representing a season. It is one of the earliest and most famous examples of program music, with vivid descriptive passages." },
  { category: "Music", difficulty: "HARD", question: "Which opera features the 'Flower Duet' famously used in commercials?", options: JSON.stringify(["Carmen","La Bohème","Tosca","Lakmé"]), correctAnswer: "Lakmé", funFact: "The 'Flower Duet' from Léo Delibes' opera 'Lakmé' (1883) became widely known through British Airways commercials from 1989. Its haunting soprano melody made it one of the most recognizable pieces of classical music." },
  { category: "Music", difficulty: "HARD", question: "Which jazz musician is credited with inventing bebop?", options: JSON.stringify(["Dizzy Gillespie","Thelonious Monk","Charlie Mingus","Charlie Parker"]), correctAnswer: "Charlie Parker", funFact: "Charlie 'Bird' Parker, an alto saxophonist, is credited with creating bebop in the 1940s alongside Dizzy Gillespie. Bebop featured complex chords, fast tempos, and virtuosic solos — a radical departure from swing." },
  { category: "Sports", difficulty: "EASY", question: "How many players are on a volleyball team?", options: JSON.stringify(["5","7","9","6"]), correctAnswer: "6", funFact: "A volleyball team has 6 players on the court at once. The sport was invented in 1895 by William G. Morgan as 'Mintonette,' designed to be less strenuous than basketball for older adults." },
  { category: "Sports", difficulty: "EASY", question: "How many rings are on the Olympic flag?", options: JSON.stringify(["4","6","8","5"]), correctAnswer: "5", funFact: "The Olympic flag has five interlocking rings — blue, yellow, black, green, and red — representing the union of the five inhabited continents. They were designed by Pierre de Coubertin in 1913." },
  { category: "Sports", difficulty: "MEDIUM", question: "Which country won the most FIFA World Cup titles?", options: JSON.stringify(["Germany","Italy","Argentina","Brazil"]), correctAnswer: "Brazil", funFact: "Brazil has won the FIFA World Cup a record 5 times (1958, 1962, 1970, 1994, 2002). They are the only nation to have played in every World Cup. Their iconic yellow jerseys are instantly recognizable worldwide." },
  { category: "Sports", difficulty: "MEDIUM", question: "In cricket, what is a team score of zero called?", options: JSON.stringify(["Laugh","Zero","Nil","Duck"]), correctAnswer: "Duck", funFact: "In cricket, a score of zero is called a 'duck.' A 'golden duck' means being out on the very first ball. The term likely derives from the duck-like shape of the zero." },
  { category: "Sports", difficulty: "MEDIUM", question: "Which Olympic sport involves a vaulting horse and parallel bars?", options: JSON.stringify(["Diving","Wrestling","Boxing","Gymnastics"]), correctAnswer: "Gymnastics", funFact: "Artistic gymnastics features apparatus including the vaulting horse, parallel bars, horizontal bar, rings, pommel horse, and floor exercise. Scoring evaluates difficulty, execution, and presentation." },
  { category: "Sports", difficulty: "MEDIUM", question: "In basketball, what is a three-point shot called when it scores?", options: JSON.stringify(["Layup","Free Throw","Dunk","Three-pointer"]), correctAnswer: "Three-pointer", funFact: "A three-pointer scores 3 points and is taken from beyond the three-point arc. The NBA three-point line is 23 feet 9 inches at the top of the key. Stephen Curry revolutionized the game with his three-point shooting." },
  { category: "Sports", difficulty: "MEDIUM", question: "Which sport uses a 'puck' instead of a ball?", options: JSON.stringify(["Bandy","Shinty","Ringette","Hockey"]), correctAnswer: "Hockey", funFact: "Ice hockey uses a vulcanized rubber puck instead of a ball. The puck is frozen before games to reduce bouncing. It travels at speeds over 100 mph and is one of the hardest objects in sport." },
  { category: "Sports", difficulty: "HARD", question: "Which golfer holds the record for most major championship wins?", options: JSON.stringify(["Tiger Woods","Walter Hagen","Gary Player","Jack Nicklaus"]), correctAnswer: "Jack Nicklaus", funFact: "Jack Nicklaus won 18 major championships — 6 Masters, 4 U.S. Opens, 3 British Opens, and 5 PGA Championships — the most in men's professional golf history. Tiger Woods has 15. Tiger is still active." },
  { category: "Sports", difficulty: "HARD", question: "Which marathon is considered the world's oldest and most prestigious?", options: JSON.stringify(["London Marathon","Berlin Marathon","New York City Marathon","Boston Marathon"]), correctAnswer: "Boston Marathon", funFact: "The Boston Marathon began in 1897, inspired by the marathon at the first modern Olympics. It is the world's oldest annual marathon and one of the six World Marathon Majors, held on Patriots' Day each April." },
  { category: "Sports", difficulty: "HARD", question: "Which tennis player has won the most Grand Slam singles titles?", options: JSON.stringify(["Rafael Nadal","Roger Federer","Pete Sampras","Novak Djokovic"]), correctAnswer: "Novak Djokovic", funFact: "Novak Djokovic has won 24 Grand Slam singles titles, the most in men's tennis history. He surpassed Rafael Nadal and Roger Federer's totals, completing the career Grand Slam twice." },
  { category: "Sports", difficulty: "HARD", question: "Which athlete won the most Olympic gold medals in gymnastics?", options: JSON.stringify(["Michael Phelps","Karl Lagerfeld","Simone Biles","Larisa Latynina"]), correctAnswer: "Larisa Latynina", funFact: "Larisa Latynina won 18 Olympic medals in gymnastics (9 gold, 5 silver, 4 bronze) for the Soviet Union between 1956 and 1964. Her record stood for 48 years before Michael Phelps surpassed her total medal count." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which social media app lets users send disappearing photos and messages?", options: JSON.stringify(["Instagram","TikTok","Telegram","Snapchat"]), correctAnswer: "Snapchat", funFact: "Snapchat launched in 2011 and pioneered the concept of ephemeral messages. Photos and videos 'disappear' after being viewed. The app popularized the 'Stories' format later adopted by Instagram and Facebook." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which fast-food chain has the golden arches logo?", options: JSON.stringify(["Burger King","Wendy's","Taco Bell","McDonald's"]), correctAnswer: "McDonald's", funFact: "McDonald's golden arches are one of the most recognizable logos worldwide, appearing in over 100 countries. The original restaurant opened in 1940 in San Bernardino, California, by brothers Richard and Maurice McDonald." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which video game character is a yellow circle that eats dots?", options: JSON.stringify(["Q*bert","Frogger","Asterisks","Pac-Man"]), correctAnswer: "Pac-Man", funFact: "Pac-Man, released by Namco in 1980, is one of the most iconic video game characters ever. He navigates a maze eating dots while avoiding ghosts. He was originally called 'Puck Man' but was changed to Pac-Man." },
  { category: "Pop Culture", difficulty: "EASY", question: "What is the name of the yellow smiley face emoji?", options: JSON.stringify(["Emoji","Kaomoji","Facepunch","Smiley"]), correctAnswer: "Smiley", funFact: "The classic yellow smiley face was created in 1963 by Harvey Ross Ball for a Massachusetts insurance company. The Internet later adopted it as the ultimate meme and it appears in everything from emojis to caution stickers." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which streaming service is known for its red-and-white logo and 'See What's Next' tagline?", options: JSON.stringify(["Hulu","Disney+","Amazon Prime","Netflix"]), correctAnswer: "Netflix", funFact: "Netflix redefined entertainment by pioneering binge-watching. Its 'See What's Next' tagline became iconic, and its original content like Stranger Things and The Crown have dominated awards seasons globally." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "Which song became TikTok's unofficial anthem after going viral in 2018?", options: JSON.stringify(["'Harley Quinn' by Doja Cat", "'Savage' by Megan Thee Stallion", "'Renegade' by K Camp", "'Old Town Road' by Lil Nas X"]), correctAnswer: "'Old Town Road' by Lil Nas X", funFact: "'Old Town Road' by Lil Nas X (featuring Billy Ray Cyrus) broke the Billboard Hot 100 record by spending 19 weeks at #1 in 2019. Its viral spread on TikTok — a country-hip-hop blend — created a new genre." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "Which K-pop group performed at the 2022 Super Bowl halftime show?", options: JSON.stringify(["BTS","EXO","BLACKACE","BLACKPINK"]), correctAnswer: "BLACKPINK", funFact: "BLACKPINK became the first K-pop girl group to perform at the Super Bowl LVI halftime show in February 2022. Their performance featured hits like 'Shut Down' and 'Pink Venom' and introduced K-pop to mainstream U.S. audiences." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "Which Japanese toy franchise became a global anime and card game phenomenon?", options: JSON.stringify(["Digimon","Yo-kai Watch","Tamagotchi","Pokémon"]), correctAnswer: "Pokémon", funFact: "Pokémon began as a digital pet toy and became a worldwide franchise. The trading card game alone generates billions annually. The anime, games, and movies have made it one of the highest-grossing media franchises ever." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "Which singer holds the record for the most top-10 hits on the Billboard Hot 100?", options: JSON.stringify(["The Beatles","Madonna","Taylor Swift","Drake"]), correctAnswer: "Drake", funFact: "Drake surpassed Madonna and The Beatles with the most top-10 hits on the Billboard Hot 100, reaching over 80 top-10 singles by 2023. His frequent releases and collaborations dominate the chart unlike any other artist." },
  { category: "Pop Culture", difficulty: "HARD", question: "Which artist is known as the 'Queen of Pop'?", options: JSON.stringify(["Beyoncé","Lady Gaga","Britney Spears","Madonna"]), correctAnswer: "Madonna", funFact: "Madonna is universally known as the 'Queen of Pop' for her reinvention, provocative image, and unmatched chart success spanning four decades. She has sold over 300 million records and influenced countless pop artists." },
  { category: "Pop Culture", difficulty: "HARD", question: "Which meme became a stock market phenomenon in January 2021?", options: JSON.stringify(["Dogecoin","NFT","NFT Marketplace","GameStop / 'Meme Stock'"]), correctAnswer: "GameStop / 'Meme Stock'", funFact: "In January 2021, Reddit's r/WallStreetBets coordinated buying of GameStop (GME) stock, causing massive losses for hedge funds shorting it. This 'meme stock' phenomenon drew attention to retail investor power and online coordination." },
  { category: "Philippines", difficulty: "EASY", question: "What is the name of the largest lake in the Philippines?", options: JSON.stringify(["Taal Lake","Lanao Lake","Lake Buendia","Laguna de Bay"]), correctAnswer: "Laguna de Bay", funFact: "Laguna de Bay is the largest lake in the Philippines and Southeast Asia, spanning 900 square kilometers across Laguna and Rizal provinces. Its name means 'Lake of Bay' from the Spanish 'laguna de la bay.'"},
  { category: "Philippines", difficulty: "EASY", question: "What is the traditional Filipino hat made of bamboo strips?", options: JSON.stringify(["Buntal Hat","Conical Hat","Fedora","Salakot"]), correctAnswer: "Salakot", funFact: "The salakot is a traditional Filipino sun hat made from woven bamboo strips or leaves. It has been worn for centuries across all social classes and is considered a national cultural treasure." },
  { category: "Philippines", difficulty: "EASY", question: "What is the name of the Philippines' national gem?", options: JSON.stringify(["Jade","Ruby","Opal","Pearl"]), correctAnswer: "Pearl", funFact: "The South Sea Pearl, found in the waters of Palawan and the Visayas, is the Philippines' national gem. It is renowned for its size and luster, making the Philippines one of the world's top pearl-producing nations." },
  { category: "Philippines", difficulty: "MEDIUM", question: "Which city is known as the 'Summer Capital of the Philippines'?", options: JSON.stringify(["Tagaytay","Cebu","Davao","Baguio"]), correctAnswer: "Baguio", funFact: "Baguio is known as the Summer Capital due to its cool climate at 1,500 meters elevation. Founded by American Governor-General Daniel Burnham, it features a blend of colonial architecture and indigenous Cordillera culture." },
  { category: "Philippines", difficulty: "MEDIUM", question: "Which Philippine festival celebrates the mango harvest?", options: JSON.stringify(["Panagbenga Festival","Kadayawan Festival","Sinulog Festival","Pahiyas Festival"]), correctAnswer: "Pahiyas Festival", funFact: "The Pahiyas Festival in Lucban, Quezon, celebrates the mango harvest every May 15. Houses are decorated with colorful rice ornaments (kiping) and fruits. The festival honors San Isidro Labrador, the patron saint of farmers." },
  { category: "Philippines", difficulty: "MEDIUM", question: "What is the name of the famous Propaganda Movement in Philippine history?", options: JSON.stringify(["Katipunan","Ilustrado Movement","Hukbalahap","Propaganda Movement"]), correctAnswer: "Propaganda Movement", funFact: "The Propaganda Movement (1880s) was led by Jose Rizal, Marcelo H. del Pilar, and Graciano Lopez Jaena. They advocated for Filipino representation in the Spanish Cortes and reforms — though peaceful, they sparked the revolution." },
  { category: "Philippines", difficulty: "HARD", question: "Which Philippine revolutionary led the Katipunan movement?", options: JSON.stringify(["Emilio Aguinaldo","Apolinario Mabini","Marcelo H. del Pilar","Andres Bonifacio"]), correctAnswer: "Andres Bonifacio", funFact: "Andres Bonifacio founded the Katipunan in 1892, a secret society that fought Spanish colonial rule. He is honored as the 'Father of the Philippine Revolution.' His execution in 1897 by Aguinaldo's orders remains a controversial chapter." },
  { category: "Philippines", difficulty: "HARD", question: "Which Philippine epic is the longest in the country's literary history?", options: JSON.stringify(["Biag ni Lam-ang","Darangen","Hudhud","Hinilawod"]), correctAnswer: "Hinilawod", funFact: "The Hinilawod is the longest Philippine epic, spanning 72 pages in the Panay Bukidnon language. It recounts the adventures of the hero Labaw Donggon and his brothers in ancient Panay. It is a UNESCO-recognized intangible cultural heritage." },
  { category: "Food & Drinks", difficulty: "EASY", question: "What fruit is known as the 'king of fruits'?", options: JSON.stringify(["Mango","Papaya","Lychee","Durian"]), correctAnswer: "Durian", funFact: "Durian is called the 'King of Fruits' in Southeast Asia for its strong smell and creamy texture. Banned in many hotels and public transport, its divisive aroma comes from sulfur compounds that some describe as resembling gym socks." },
  { category: "Food & Drinks", difficulty: "EASY", question: "What is the main ingredient in traditional bread?", options: JSON.stringify(["Eggs","Butter","Sugar","Flour"]), correctAnswer: "Flour", funFact: "Flour — ground grain — is the foundation of bread-making. Wheat flour contains gluten, a protein that forms a network trapping air bubbles during fermentation, giving bread its soft, airy texture." },
  { category: "Food & Drinks", difficulty: "EASY", question: "Which grain is used to make sake?", options: JSON.stringify(["Wheat","Barley","Corn","Rice"]), correctAnswer: "Rice", funFact: "Sake is a Japanese rice wine made by fermenting polished rice, water, and koji mold. Unlike beer, which uses barley malt, sake's brewing process is more like beer and wine combined. Premium sake uses highly polished rice grains." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "What gives wasabi its distinctive heat?", options: JSON.stringify(["Capsaicin","Gingerol","Cinnamaldehyde","Allyl isothiocyanate"]), correctAnswer: "Allyl isothiocyanate", funFact: "Real wasabi's heat comes from allyl isothiocyanate, released when the grated root's cells break. Most 'wasabi' outside Japan is actually horseradish dyed green with mustard dye. True wasabi is expensive because it is hard to cultivate." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "Which spice is derived from the dried stigma of the crocus flower?", options: JSON.stringify(["Cinnamon","Cumin","Turmeric","Saffron"]), correctAnswer: "Saffron", funFact: "Saffron is the world's most expensive spice by weight, requiring roughly 75,000 crocus flowers to produce one pound. Its delicate flavor and golden color come from the flower's red stigmas, hand-picked in autumn." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "Which vegetable is often called a 'superfood' due to its high nutrient density?", options: JSON.stringify(["Kale","Spinach","Brussels Sprouts","Broccoli"]), correctAnswer: "Broccoli", funFact: "Broccoli is a cruciferous vegetable packed with vitamins C, K, and fiber, plus sulforaphane — a compound studied for its cancer-fighting properties. It's one of the most nutrient-dense vegetables per calorie." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "Which drink was originally created as a medicinal tonic?", options: JSON.stringify(["Pepsi","Sprite","Fanta","Coca-Cola"]), correctAnswer: "Coca-Cola", funFact: "Coca-Cola was invented in 1886 by pharmacist John Pemberton as a patent medicine containing coca leaf and kola nut extracts. It was sold at Jacob's Pharmacy in Atlanta for five cents per glass before becoming the world's most popular soft drink." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "Which fruit is the source of the natural sweetener 'stevia'?", options: JSON.stringify(["Honey","Dates","Maple Syrup","Stevia plant leaves"]), correctAnswer: "Stevia plant leaves", funFact: "Stevia is a natural sweetener extracted from the leaves of the Stevia rebaudiana plant, native to South America. It is up to 300 times sweeter than sugar with zero calories, making it a popular sugar substitute." },
  { category: "Food & Drinks", difficulty: "HARD", question: "What is the process of fermenting grape juice into wine called?", options: JSON.stringify(["Distillation","Oxidation","Maceration","Fermentation"]), correctAnswer: "Fermentation", funFact: "Fermentation converts grape sugars into alcohol and carbon dioxide using yeast. The process has been practiced since at least 6000 BC in the Caucasus region. Winemaking combines art and science — terroir, grape variety, and aging all influence flavor." },
  { category: "Food & Drinks", difficulty: "HARD", question: "What is the name of the technique of slowly cooking meat in its own fat?", options: JSON.stringify(["Sous vide","Braising","Sear","Confit"]), correctAnswer: "Confit", funFact: "Confit is a French technique where meat (usually duck or goose) is salted and cooked slowly in its own rendered fat at low temperatures, then stored in the fat. It preserves the meat and creates incredibly tender, flavorful results." },
  { category: "Food & Drinks", difficulty: "HARD", question: "Which spice blend is the basis for the curry powder commonly used in British cooking?", options: JSON.stringify(["Garam masala","Tandoori masala","Five-spice powder","Curry powder (British blend)"]), correctAnswer: "Curry powder (British blend)", funFact: "The 'curry powder' popular in British cooking was actually created in Britain by Indian migrants — not in India itself. It blends turmeric, cumin, coriander, fenugreek, and chili. Traditional Indian cooking uses specific spice combinations, not a generic 'curry powder.'"},
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which animated series features a yellow sponge who works at a fast-food restaurant?", options: JSON.stringify(["The Simpsons","Family Guy","South Park","SpongeBob SquarePants"]), correctAnswer: "SpongeBob SquarePants", funFact: "SpongeBob SquarePants premiered in 1999 and became one of the longest-running animated series. Created by marine biologist Stephen Hillenburg, it is set in the underwater city of Bikini Bottom and has won multiple Emmy Awards." },
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which animated film is set in a kingdom under the sea?", options: JSON.stringify(["Finding Nemo","Shrek","Frozen","The Little Mermaid"]), correctAnswer: "The Little Mermaid", funFact: "Disney's The Little Mermaid (1989) tells the story of Ariel, a mermaid princess who dreams of living on land. Based on Hans Christian Andersen's fairy tale, it helped launch the Disney Renaissance era with its Oscar-winning songs." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which sitcom features the character 'Sheldon Cooper'?", options: JSON.stringify(["Friends","How I Met Your Mother","Brooklyn Nine-Nine","The Big Bang Theory"]), correctAnswer: "The Big Bang Theory", funFact: "The Big Bang Theory (2007-2019) features Jim Parsons as Sheldon Cooper, a genius physicist with obsessive-compulsive traits. It ran for 12 seasons and won multiple Emmys, including Outstanding Lead Actor for Parsons." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which TV show follows a group of lawyers fighting corporate corruption?", options: JSON.stringify(["Better Call Saul","The Good Wife","Billions","Suits"]), correctAnswer: "Suits", funFact: "Suits (2011-2019) follows Mike Ross, a college dropout who pretends to be a lawyer, and Harvey Specter at a top New York law firm. Despite its legal inaccuracies, it became a global hit and launched Megan Markle's acting career." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which TV show features a time-traveling Doctor and his companions?", options: JSON.stringify(["Stranger Things","The Flash","Lost","Doctor Who"]), correctAnswer: "Doctor Who", funFact: "Doctor Who has been airing since 1963, making it the longest-running sci-fi series. The Doctor regenerates into a new form (played by new actors) every few seasons, allowing the show to continue for over 60 years." },
  { category: "TV Shows & Anime", difficulty: "HARD", question: "Which anime film won the Academy Award for Best Animated Feature in 2003?", options: JSON.stringify(["Princess Mononoke","Perfect Blue","Akira","Spirited Away"]), correctAnswer: "Spirited Away", funFact: "Spirited Away (2001) won the Oscar for Best Animated Feature in 2003 — the first non-English film to do so. Hayao Miyazaki's masterpiece follows Chihiro's journey through a spirit world, blending Japanese folklore with stunning animation." },
  { category: "TV Shows & Anime", difficulty: "HARD", question: "Which Japanese anime was banned in over 10 countries due to graphic content?", options: JSON.stringify(["Attack on Titan","Death Note","Tokyo Ghoul","Elfen Lied"]), correctAnswer: "Elfen Lied", funFact: "Elfen Lied (2004) was banned in several countries due to extreme violence and nudity in its first episodes. The anime's graphic content sparked international debate, though its deeper themes of discrimination and trauma earned critical praise." },
  { category: "Animals", difficulty: "EASY", question: "Which animal is known as the 'ship of the desert'?", options: JSON.stringify(["Horse","Donkey","Elephant","Camel"]), correctAnswer: "Camel", funFact: "Camels are called 'ships of the desert' for their ability to travel long distances without water. They can close their nostrils to keep out sand and have broad, flat feet for walking on sand without sinking." },
  { category: "Animals", difficulty: "EASY", question: "Which animal can change its skin color for camouflage?", options: JSON.stringify(["Flamingo","Penguin","Parrot","Chameleon"]), correctAnswer: "Chameleon", funFact: "Chameleons change color using specialized cells called chromatophores beneath their skin. While often portrayed as camouflage-only, they also change color for temperature regulation, communication, and mood display." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which insect is responsible for pollinating most flowering plants?", options: JSON.stringify(["Butterfly","Bat","Ladybug","Honeybee"]), correctAnswer: "Honeybee", funFact: "Honeybees pollinate roughly 80% of flowering plants and about 75% of global food crops. Their decline threatens agriculture — a phenomenon called 'colony collapse disorder' that has puzzled scientists for years." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which bird can mimic almost any sound it hears?", options: JSON.stringify(["Parrot","Raven","Crow","Lyrebird"]), correctAnswer: "Lyrebird", funFact: "The superb lyrebird of Australia can mimic any sound it hears — chainsaws, car alarms, camera shutters, and other birds. This extraordinary mimicry is used in mating displays. It holds the record for the most accurate vocal imitation in the animal kingdom." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which marine animal has the longest lifespan of any vertebrate?", options: JSON.stringify(["Bowhead Whale","Giant Tortoise","Immortal Jellyfish","Greenland Shark"]), correctAnswer: "Greenland Shark", funFact: "Greenland sharks can live over 500 years, making them the longest-lived vertebrates. They grow about 1 cm per year and don't reach sexual maturity until around 150. Their extreme longevity was discovered by carbon-dating their eye lenses." },
  { category: "Animals", difficulty: "HARD", question: "Which animal has three hearts and blue blood?", options: JSON.stringify(["Squid","Starfish","Blue Whale","Octopus"]), correctAnswer: "Octopus", funFact: "Octopuses have three hearts: two pump blood to the gills, and one pumps it to the rest of the body. Their blood is blue due to hemocyanin (copper-based), unlike our iron-based hemoglobin. They also have nine brains — one central and eight mini-brains in each arm." },
  { category: "Animals", difficulty: "HARD", question: "Which animal has the longest pregnancy of any land mammal?", options: JSON.stringify(["Blue Whale","Giraffe","Orangutan","African Elephant"]), correctAnswer: "African Elephant", funFact: "African elephants have the longest gestation of any land mammal — around 22 months. They give birth to relatively mature calves that can walk within hours. Elephants are also one of the few species that experience menopause." },
  { category: "Logic", difficulty: "EASY", question: "If all cats are animals and all animals need water, are cats water-dependent?", options: JSON.stringify(["No","Maybe","Cannot be determined","Yes"]), correctAnswer: "Yes", funFact: "This is a syllogism: if A is B, and B is C, then A is C. All cats are animals, all animals need water, therefore cats need water. It is a foundational concept in deductive reasoning and formal logic." },
  { category: "Logic", difficulty: "EASY", question: "Which shape has four equal sides but not necessarily four right angles?", options: JSON.stringify(["Square","Rectangle","Trapezoid","Rhombus"]), correctAnswer: "Rhombus", funFact: "A rhombus has four equal sides like a square, but its angles are not necessarily 90°. A square is actually a special type of rhombus where all angles are right angles. The diagonals of a rhombus always bisect each other at 90°." },
  { category: "Logic", difficulty: "EASY", question: "Which statement describes a square perfectly?", options: JSON.stringify(["A shape with no corners","A three-sided figure","A shape with curved sides","A rectangle with four equal sides"]), correctAnswer: "A rectangle with four equal sides", funFact: "A square is a special type of rectangle where all four sides are equal. It has four right angles, four equal sides, and two pairs of parallel sides. It is both a rhombus and a rectangle simultaneously." },
  { category: "Logic", difficulty: "EASY", question: "What comes next: 10, 30, 70, 150, __?", options: JSON.stringify(["230","250","290","310"]), correctAnswer: "310", funFact: "Each term doubles and adds 10: 10×2+10=30, 30×2+10=70, 70×2+10=150, 150×2+10=310. Pattern recognition is a key logic skill — identifying the rule (multiply by 2, add 10) lets you predict the next term." },
  { category: "Logic", difficulty: "MEDIUM", question: "What number should replace the question mark: 1, 1, 2, 3, 5, 8, __?", options: JSON.stringify(["11","10","12","13"]), correctAnswer: "13", funFact: "This is the Fibonacci sequence, where each number is the sum of the two preceding ones (1+1=2, 1+2=3, 2+3=5, 3+5=8, 5+8=13). It appears throughout nature — in sunflower seed spirals, pinecone patterns, and nautilus shells." },
  { category: "Logic", difficulty: "MEDIUM", question: "A rooster lays an egg on the peak of a roof. Which way does it roll?", options: JSON.stringify(["Left","Right","Both ways","Neither — roosters don't lay eggs"]), correctAnswer: "Neither — roosters don't lay eggs", funFact: "This is a classic trick question. Roosters are male chickens and do not lay eggs — only hens do. The question tests whether you pause to question the premise rather than solving the hypothetical." },
  { category: "Logic", difficulty: "MEDIUM", question: "What is the name of the logical paradox where 'this statement is false' cannot be true or false?", options: JSON.stringify(["Russell's Paradox","Zeno's Paradox","Ship of Theseus","Liar Paradox"]), correctAnswer: "Liar Paradox", funFact: "The Liar Paradox ('This statement is false') creates a logical loop: if true, it must be false; if false, it must be true. It has challenged philosophers and mathematicians for millennia and influenced Gödel's incompleteness theorems." },
  { category: "Logic", difficulty: "HARD", question: "In formal logic, which of these statements is a tautology?", options: JSON.stringify(["P AND NOT P","P AND P","P OR P","P OR NOT P"]), correctAnswer: "P OR NOT P", funFact: "P OR NOT P is always true regardless of P's value — it is a tautology. This is the law of excluded middle. It contrasts with 'P AND NOT P,' which is always false (a contradiction) — the law of non-contradiction." },
  { category: "Logic", difficulty: "HARD", question: "If it takes 5 machines 5 minutes to make 5 widgets, how long would it take 100 machines to make 100 widgets?", options: JSON.stringify(["100 minutes","1 minute","20 minutes","5 minutes"]), correctAnswer: "5 minutes", funFact: "This is a classic rate puzzle. If 5 machines make 5 widgets in 5 minutes, each machine takes 5 minutes for one widget. So 100 machines each make one widget in 5 minutes. Most people incorrectly answer 100 minutes by assuming linear scaling." },
  { category: "Logic", difficulty: "HARD", question: "Which number is irrational — it cannot be expressed as a simple fraction?", options: JSON.stringify(["1.5","0.333...","2/3","√2"]), correctAnswer: "√2", funFact: "√2 (approximately 1.4142...) is irrational — it cannot be written as a fraction of two integers. Its decimal never ends or repeats. The discovery of irrational numbers by the Pythagoreans caused a philosophical crisis in ancient mathematics." },
  { category: "World Wonders", difficulty: "EASY", question: "Which wonder is located in Petra, Jordan?", options: JSON.stringify(["The Colosseum","Christ the Redeemer","Machu Picchu","Al-Khazneh (The Treasury)"]), correctAnswer: "Al-Khazneh (The Treasury)", funFact: "Al-Khazneh ('The Treasury') is the iconic facade of Petra in Jordan, carved directly into rose-red sandstone cliffs. It is believed to have been a royal tomb from the Nabataean kingdom around the 1st century BC." },
  { category: "World Wonders", difficulty: "EASY", question: "Which ancient wonder was a massive statue of the sun god Helios?", options: JSON.stringify(["Lighthouse of Alexandria","Statue of Zeus","Mausoleum at Halicarnassus","Colossus of Rhodes"]), correctAnswer: "Colossus of Rhodes", funFact: "The Colossus of Rhodes stood about 33 meters tall and was made of bronze plates over an iron frame. It was completed around 280 BC but stood for only 54 years before an earthquake toppled it. Its ruins remained a tourist attraction for centuries." },
  { category: "World Wonders", difficulty: "EASY", question: "Which structure is a famous landmark at Universal Studios in Los Angeles?", options: JSON.stringify(["The Statue of Liberty","Golden Gate Bridge","Space Needle","The Hollywood Sign"]), correctAnswer: "The Hollywood Sign", funFact: "The Hollywood Sign was originally 'Hollywoodland' when erected in 1923 as a real estate advertisement. The 'land' portion was removed in 1949, leaving the iconic sign we know today. It sits on Mount Lee in the Santa Monica Mountains." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which New Seven Wonders site is located in India?", options: JSON.stringify(["Great Wall of China","Colosseum","Chichen Itza","Taj Mahal"]), correctAnswer: "Taj Mahal", funFact: "The Taj Mahal in Agra, India, is considered the finest example of Mughal architecture. Built by Emperor Shah Jahan as a tomb for his wife Mumtaz Mahal, it took 22 years and 20,000 workers to complete (1632-1653)."},
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which ancient wonder was a tomb for a Persian king?", options: JSON.stringify(["Great Pyramid of Giza","Temple of Artemis","Hanging Gardens of Babylon","Mausoleum at Halicarnassus"]), correctAnswer: "Mausoleum at Halicarnassus", funFact: "The Mausoleum at Halicarnassus was built around 350 BC for Mausolus, a Persian satrap. Its name inspired the modern word 'mausoleum.' It was destroyed by earthquakes between the 12th and 15th centuries." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which of the New Seven Wonders of the World is in China?", options: JSON.stringify(["Forbidden City","Terracotta Army","Three Gorges Dam","Great Wall of China"]), correctAnswer: "Great Wall of China", funFact: "The Great Wall of China stretches over 21,000 kilometers across northern China, built over centuries starting in the 7th century BC. It is the largest man-made structure ever built. Contrary to myth, it is not visible from space with the naked eye." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which modern wonder, located in France, is known for its glass pyramid entrance?", options: JSON.stringify(["Eiffel Tower","Notre-Dame Cathedral","Arc de Triomphe","Louvre Pyramid"]), correctAnswer: "Louvre Pyramid", funFact: "The Louvre Pyramid, designed by architect I.M. Pei and completed in 1989, is a 21-meter glass-and-metal pyramid in the courtyard of the Louvre Museum. Initially controversial, it is now celebrated as a masterpiece of modern architecture." },
  { category: "World Wonders", difficulty: "HARD", question: "Which wonder of the ancient world was dedicated to the goddess Artemis?", options: JSON.stringify(["Statue of Zeus","Mausoleum at Halicarnassus","Lighthouse of Alexandria","Temple of Artemis"]), correctAnswer: "Temple of Artemis", funFact: "The Temple of Artemis at Ephesus was one of the Seven Wonders, built to honor the Greek goddess of the hunt. It was reconstructed three times — the final version, completed around 550 BC, was 115 meters long and 46 meters wide." },
  { category: "World Wonders", difficulty: "HARD", question: "Which ancient wonder was a garden built on elevated platforms?", options: JSON.stringify(["Sphinx of Giza","Temple of Artemis","Colossus of Rhodes","Hanging Gardens of Babylon"]), correctAnswer: "Hanging Gardens of Babylon", funFact: "The Hanging Gardens of Babylon were said to be built by King Nebuchadnezzar II around 600 BC for his Median wife who missed green hills. Their existence is debated — no archaeological evidence has been found, making them one of the most mysterious wonders." },
  { category: "Art & Literature", difficulty: "EASY", question: "Who wrote the novel '1984'?", options: JSON.stringify(["Aldous Huxley","Ray Bradbury","Kurt Vonnegut","George Orwell"]), correctAnswer: "George Orwell", funFact: "George Orwell's '1984' (1949) introduced concepts like Big Brother, Newspeak, and thoughtcrime. It remains a landmark of dystopian fiction, often cited during discussions about surveillance and censorship." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "Which artist painted the ceiling of the Sistine Chapel?", options: JSON.stringify(["Leonardo da Vinci","Raphael","Donatello","Michelangelo"]), correctAnswer: "Michelangelo", funFact: "Michelangelo painted the Sistine Chapel ceiling between 1508 and 1512, lying on scaffolding he designed himself. It features over 300 figures and took four years — despite the Pope (Julius II) originally commissioning him for a different project." },
  { category: "Art & Literature", difficulty: "HARD", question: "Who wrote the play 'Romeo and Juliet'?", options: JSON.stringify(["Christopher Marlowe","Ben Jonson","Oscar Wilde","William Shakespeare"]), correctAnswer: "William Shakespeare", funFact: "Shakespeare wrote 'Romeo and Juliet' around 1597. It is one of the most frequently performed plays in the world and has inspired countless adaptations — from Baz Luhrmann's 1996 film to West Side Story." },
  { category: "Space & Astronomy", difficulty: "EASY", question: "What galaxy is our solar system located in?", options: JSON.stringify(["Andromeda","Triangulum","Large Magellanic Cloud","Milky Way"]), correctAnswer: "Milky Way", funFact: "The Milky Way is a barred spiral galaxy containing 100-400 billion stars. Our Sun orbits its center once every 225-250 million years. It is visible as a band of light across the night sky." },
  { category: "Space & Astronomy", difficulty: "EASY", question: "What is the nearest star to Earth (after the Sun)?", options: JSON.stringify(["Sirius","Alpha Centauri A","Barnard's Star","Proxima Centauri"]), correctAnswer: "Proxima Centauri", funFact: "Proxima Centauri is a red dwarf star 4.24 light-years away — the closest to our Sun. It was discovered in 1917 by Robert Innes. It has at least two confirmed exoplanets, one possibly in the habitable zone." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "How many planets are in our solar system?", options: JSON.stringify(["6","7","9","8"]), correctAnswer: "8", funFact: "Our solar system has 8 planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Pluto was reclassified as a 'dwarf planet' by the International Astronomical Union in 2006." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "What is the largest planet in our solar system?", options: JSON.stringify(["Saturn","Neptune","Uranus","Jupiter"]), correctAnswer: "Jupiter", funFact: "Jupiter is the largest planet — over 1,300 Earths could fit inside it. Its Great Red Spot is a centuries-old storm. It has 95 known moons, including Ganymede (the solar system's largest moon) and Europa (a potential ocean world)."},
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is a black hole?", options: JSON.stringify(["A dead star that emits radio waves","A planet with no atmosphere","A galaxy made of dark matter","A region of spacetime where gravity prevents anything from escaping"]), correctAnswer: "A region of spacetime where gravity prevents anything from escaping", funFact: "A black hole forms when massive stars collapse at the end of their life. Its gravity is so intense that nothing — not even light — can escape past the event horizon. Supermassive ones reside at galaxy centers." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is gravitational lensing?", options: JSON.stringify(["Light bending around small objects","Light reflecting off planets","Light scattering off dust","Light bending around massive objects"]), correctAnswer: "Light bending around massive objects", funFact: "Gravitational lensing occurs when massive objects (like galaxy clusters) bend spacetime, warping light from objects behind them. Predicted by Einstein, it lets astronomers see distant galaxies magnified and study dark matter distributions." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "Who is the Greek god of the sea?", options: JSON.stringify(["Hades","Apollo","Ares","Poseidon"]), correctAnswer: "Poseidon", funFact: "Poseidon is the Greek god of the sea, earthquakes, and horses. His symbol is the trident. He was one of the three main gods of Olympus (with Zeus and Hades) and is known for his temperamental nature." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "What is the name of the Hindu elephant-headed god?", options: JSON.stringify(["Shiva","Vishnu","Brahma","Ganesha"]), correctAnswer: "Ganesha", funFact: "Ganesha, the elephant-headed god of wisdom and new beginnings, is one of the most worshipped deities in Hinduism. He is revered as the remover of obstacles and patron of arts and sciences. His elephant head symbolizes wisdom and intelligence." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "What is the meaning of the Greek word 'atomos'?", options: JSON.stringify(["Infinite","Atomic","Invisible","Indivisible"]), correctAnswer: "Indivisible", funFact: "'Atomos' means 'indivisible' or 'uncuttable.' Democritus proposed all matter is made of indivisible atoms — the foundation of atomic theory. The word was revived by John Dalton in the 1800s for modern atomic science." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "What is Norse mythology's realm of the dead called?", options: JSON.stringify(["Valhalla","Asgard","Midgard","Helheim"]), correctAnswer: "Helheim", funFact: "Helheim is the Norse realm of the dead, ruled by the goddess Hel. Unlike Valhalla (where warriors go), Helheim receives those who die of old age or illness. It is described as cold, dark, and misty." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "Which philosopher wrote 'The Republic' and described a cave allegory?", options: JSON.stringify(["Aristotle","Socrates","Descartes","Plato"]), correctAnswer: "Plato", funFact: "Plato's 'Republic' describes the Allegory of the Cave — prisoners chained in a cave who mistake shadows for reality. It explores justice, ideal governance, and the philosopher-king concept. It remains foundational to Western philosophy." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "Which philosopher coined the phrase 'Cogito, ergo sum'?", options: JSON.stringify(["Kant","Hume","Nietzsche","Descartes"]), correctAnswer: "Descartes", funFact: "René Descartes coined 'Cogito, ergo sum' (I think, therefore I am) in his 'Meditations on First Philosophy' (1637). It represents the foundation of modern philosophy — establishing the thinking self as the first certainty." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What is a 'meme' as defined by Richard Dawkins?", options: JSON.stringify(["A viral video","A cat picture","A joke","A unit of cultural transmission"]), correctAnswer: "A unit of cultural transmission", funFact: "Richard Dawkins coined the term 'meme' in his 1976 book 'The Selfish Gene' — meaning a unit of cultural information that spreads from person to person. The internet 'meme' is a modern evolution of this concept." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "Which meme features a shocked-looking dog and a caption?", options: JSON.stringify(["Cheems","Distracted Boyfriend","This is Fine","Doge"]), correctAnswer: "Doge", funFact: "Doge is a meme based on a Shiba Inu photographed by Atsuko Sato in 2010. The comic sans caption in broken English ('much wow,' 'so such') became iconic. It was even used as the basis for a cryptocurrency (Dogecoin) in 2013." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "Which meme features a two-toned cat with an expressive face?", options: JSON.stringify(["Success Kid","Woman Yelling at Cat","Meme Man","Grumpy Cat"]), correctAnswer: "Grumpy Cat", funFact: "Grumpy Cat (real name Tardar Sauce) was a famous internet cat with a permanent scowl due to feline dwarfism and an underbite. Photos were shared starting in 2012 and spawned countless memes, a book, and merchandise." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What is the origin of the 'Rickroll' internet meme?", options: JSON.stringify(["A meme about a robot","A viral video of a pizza delivery","A Twitter hashtag campaign","A YouTube prank linking to Rick Astley's 'Never Gonna Give You Up'"]), correctAnswer: "A YouTube prank linking to Rick Astley's 'Never Gonna Give You Up'", funFact: "The Rickroll originated on 4chan in 2007 when users disguised links to Rick Astley's 1987 song. By 2008 it spread globally and became a classic prank. In 2008, it was used during the Macy's Thanksgiving Day Parade — surprising millions." },
  { category: "Board Games & Strategy", difficulty: "EASY", question: "How many squares are on a standard chessboard?", options: JSON.stringify(["81","100","120","64"]), correctAnswer: "64", funFact: "A standard chessboard has 8×8 = 64 squares, alternating dark and light. It features 32 pieces total (16 per player). Chess has been played since the 6th century and is considered a measure of intellectual skill worldwide." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "How many territories does a player start with in Risk?", options: JSON.stringify(["25","30","40","45"]), correctAnswer: "45", funFact: "In Risk, players start with 45 armies and one territory each (for the first player). The goal is to conquer all territories. Risk has been a classic strategy board game since its invention in 1957." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "What is the goal in the board game Clue?", options: JSON.stringify(["Collect the most money","Build the longest chain","Capture the opponent's pieces","Guess who murdered Mr. Boddy"]), correctAnswer: "Guess who murdered Mr. Boddy", funFact: "Clue (known as Cluedo outside North America) was first published in 1949 by Anthony E. Pratt. Players use deduction to determine which of six suspects committed the murder, with what weapon, and in which room." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "Which board game involves players bidding for cards representing European cities?", options: JSON.stringify(["Ticket to Ride","7 Wonders","Dominion","Power Grid"]), correctAnswer: "Power Grid", funFact: "Power Grid is a strategy game where players bid for power plants and buy resources to supply cities. Designed by Friedemann Friese, it was published in 2004 and is considered one of the best modern economic strategy board games." },
  { category: "Automotive", difficulty: "EASY", question: "What does 'MPG' stand for in car specifications?", options: JSON.stringify(["Maximum Performance Gear","Motor Power Gauge","Mile Per Gear","Miles Per Gallon"]), correctAnswer: "Miles Per Gallon", funFact: "MPG measures how many miles a vehicle can travel on one gallon of fuel. Higher MPG means better fuel efficiency. Electric vehicles are often rated in MPGe (miles per gallon equivalent) for comparison." },
  { category: "Automotive", difficulty: "MEDIUM", question: "Who invented the modern automobile?", options: JSON.stringify(["Henry Ford","Nicolas-Joseph Cugnot","Gottlieb Daimler","Karl Benz"]), correctAnswer: "Karl Benz", funFact: "Karl Benz is credited with inventing the modern automobile in 1885 with the Benz Patent-Motorwagen. It was a three-wheeled vehicle powered by a single-cylinder engine. Henry Ford later revolutionized mass production with the assembly line." },
  { category: "Automotive", difficulty: "MEDIUM", question: "What is the name of a car's front grille opening?", options: JSON.stringify(["Hood","Bonnet","Shutter","Radiator"]), correctAnswer: "Radiator", funFact: "A car's radiator is the front-facing component that cools the engine with airflow. Modern cars have evolved from exposed radiators to sleek 'front face' designs, but the grille opening's primary function remains engine cooling." },
  { category: "Nature & Plants", difficulty: "EASY", question: "Which plant gives us chocolate?", options: JSON.stringify(["Vanilla","Cocoa Butter","Maple","Cacao"]), correctAnswer: "Cacao", funFact: "Cacao trees (Theobroma cacao) produce pods containing cacao beans — the raw ingredient for chocolate. The name Theobroma means 'food of the gods' in Greek. Cacao has been cultivated in Central and South America for over 3,000 years." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "What is the tallest tree species in the world?", options: JSON.stringify(["Giant Sequoia","Douglas Fir","Douglas Spruce","Coastal Redwood"]), correctAnswer: "Coastal Redwood", funFact: "Coastal redwoods (Sequoia sempervirens) can reach over 115 meters tall — taller than the Statue of Liberty. Hyperion, the tallest known tree, is a coastal redwood in California estimated at over 116 meters." },
  { category: "Nature & Plants", difficulty: "HARD", question: "Which carnivorous plant uses a snap trap to capture insects?", options: JSON.stringify(["Pitcher Plant","Sundew","Butterwort","Venus Flytrap"]), correctAnswer: "Venus Flytrap", funFact: "The Venus Flytrap (Dionaea muscipula) closes its jaw-like leaves in about 0.1 seconds when trigger hairs are touched twice within 20 seconds. It grows naturally only in subtropical wetlands of North and South Carolina." },
  { category: "Nature & Plants", difficulty: "EASY", question: "What is the largest flower in the world?", options: JSON.stringify(["Rose","Sunflower","Lotus","Rafflesia"]), correctAnswer: "Rafflesia", funFact: "Rafflesia arnoldii produces the largest individual flower, reaching up to 1 meter in diameter. It is a parasitic plant with no stems, leaves, or roots — it lives inside its host vine in Southeast Asian rainforests." },
  { category: "Filipino Pop Culture", difficulty: "EASY", question: "What is the Philippines' most-watched streaming platform?", options: JSON.stringify(["Netflix","Viu","iWant","YouTube"]), correctAnswer: "YouTube", funFact: "YouTube is the Philippines' most-watched platform, with Filipinos spending an average of nearly 4 hours daily on it. The country consistently ranks among the world's top YouTube-consuming nations, favoring music and entertainment content." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "Which Filipino singer won an international singing competition in 2019?", options: JSON.stringify(["Sarah Geronimo","Morissette Amon","Janine Berdin","Zephanie"]), correctAnswer: "Zephanie", funFact: "Zephanie Dimaranan won the first season of The Voice Kids Philippines in 2015 and later achieved international recognition. Filipino singers regularly excel in Asian singing competitions, showcasing the country's rich musical talent." },
  { category: "Language & Words", difficulty: "EASY", question: "How many letters are in the English alphabet?", options: JSON.stringify(["24","30","28","26"]), correctAnswer: "26", funFact: "The English alphabet has 26 letters — 21 consonants and 5 vowels (A, E, I, O, U). This standard has been in use since the late 15th century, replacing earlier versions with fewer letters." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is the longest English word without repeating letters?", options: JSON.stringify(["Dermatoglyphics","Supercalifragilisticexpialidocious","Pneumonoultramicroscopicsilicovolcanoconiosis","Uncopyrightable"]), correctAnswer: "Uncopyrightable", funFact: "'Uncopyrightable' (15 letters) is the longest English word with no repeated letters. It was coined to mean 'not subject to copyright.' Other lengthy words with unique letters include 'dermatoglyphics' and 'subdermatoglyphic'." },
  { category: "Language & Words", difficulty: "HARD", question: "Which word is the only English word that is both a singular noun and a plural verb?", options: JSON.stringify(["Does","Reads","Speaks","Words"]), correctAnswer: "Words", funFact: "'Words' is the only English word that can be both a singular noun ('the word is important') and a plural verb form ('she words her responses carefully'). This grammatical versatility is unique in English." },
  { category: "Economics & Business", difficulty: "EASY", question: "What does 'GDP' stand for?", options: JSON.stringify(["General Debt Payment","Global Development Plan","Gross Development Percentage","Gross Domestic Product"]), correctAnswer: "Gross Domestic Product", funFact: "GDP measures the total value of goods and services produced in a country in a given period. It is the primary indicator of economic health. GDP per capita (divided by population) gives a rough measure of average prosperity." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What is the name of the largest stock exchange by market capitalization?", options: JSON.stringify(["NASDAQ","Tokyo Stock Exchange","London Stock Exchange","New York Stock Exchange"]), correctAnswer: "New York Stock Exchange", funFact: "The New York Stock Exchange (NYSE) is the world's largest stock exchange by market capitalization, listing companies worth over $30 trillion. It was founded in 1792 under a buttonwood tree on Wall Street." },
  { category: "Economics & Business", difficulty: "HARD", question: "What is 'quantitative easing'?", options: JSON.stringify(["Raising interest rates to curb inflation","Taxing the wealthy to reduce deficits","Cutting government spending to balance budgets","Printing money to buy government bonds to stimulate the economy"]), correctAnswer: "Printing money to buy government bonds to stimulate the economy", funFact: "Quantitative easing (QE) is when a central bank buys government bonds to inject money into the economy and lower long-term interest rates. It was notably used by the Federal Reserve after the 2008 financial crisis and during COVID-19." }
];

const extraQuestions7 = [
  { category: "Space & Astronomy", difficulty: "EASY", question: "Which planet is known for its prominent rings?", options: JSON.stringify(["Mars","Saturn","Venus","Mercury"]), correctAnswer: "Saturn", funFact: "Saturn's rings are made of billions of pieces of ice and rock, some as large as a house. They are enormous — stretching 282,000 km across — yet surprisingly thin, averaging only about 10 meters thick. Saturn is also the least dense planet in the solar system; it would float in water if there were a bathtub big enough." },
  { category: "Space & Astronomy", difficulty: "EASY", question: "What is the name of the imaginary line around the middle of Earth?", options: JSON.stringify(["The Prime Meridian","The Tropic of Cancer","The Equator","The Axis"]), correctAnswer: "The Equator", funFact: "The Equator is about 40,075 km (24,901 miles) around, and divides Earth into the Northern and Southern Hemispheres. The word comes from the Latin 'aequus,' meaning equal — because it divides the planet into two equal halves. Countries like Ecuador, Kenya and Indonesia are named after their position on it." },
  { category: "Space & Astronomy", difficulty: "EASY", question: "What is a solar eclipse?", options: JSON.stringify(["When the Moon blocks the Sun","When Earth blocks the Sun","When the Sun goes out","When Mars covers the Sun"]), correctAnswer: "When the Moon blocks the Sun", funFact: "A solar eclipse only happens when the Moon passes directly between Earth and the Sun — which is why it occurs somewhere on Earth only about once every 18 months. A total eclipse can last just a few minutes, but the region where totality is visible is often less than 200 km wide." },
  { category: "Space & Astronomy", difficulty: "EASY", question: "What is a light-year?", options: JSON.stringify(["The time light takes to travel one year","The distance light travels in one year","The age of the nearest star","The brightness of a star"]), correctAnswer: "The distance light travels in one year", funFact: "A light-year is a unit of distance, not time. It equals roughly 9.46 trillion km. The nearest star, Proxima Centauri, is 4.24 light-years away — so seeing it now means seeing the star as it was 4 years ago. The Milky Way itself is about 100,000 light-years across." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "What is a nebula?", options: JSON.stringify(["A cloud of gas and dust where stars are born","A dead star's outer layer","A group of galaxies","A hole left by a supernova"]), correctAnswer: "A cloud of gas and dust where stars are born", funFact: "The Eagle Nebula (home of the famous 'Pillars of Creation') is roughly 7,000 light-years away and about 70 light-years tall. Stars like our Sun are literally born inside nebulae — which is why the most abundant elements in our bodies, carbon and oxygen, were first forged in stellar nurseries like these." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "Which planet has the shortest day?", options: JSON.stringify(["Mercury","Jupiter","Mars","Venus"]), correctAnswer: "Jupiter", funFact: "Jupiter spins once in under 10 hours — the fastest rotation of any planet. That rapid spin flattens the planet noticeably: Jupiter is 7% wider at the equator than at the poles. It still takes nearly 12 years for Jupiter to complete one orbit of the Sun." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "What is the name of the supermassive black hole at the centre of the Milky Way?", options: JSON.stringify(["Sagittarius A*","Betelgeuse","Quasar P3H91","Vulcan Prime"]), correctAnswer: "Sagittarius A*", funFact: "Sagittarius A* is roughly 4 million times the mass of the Sun, yet it fits inside an orbit only about 44 million km wide — meaning it has an astonishing density. It is invisible, and astronomers only 'see' it by watching stars orbit an empty space. Event Horizon Telescope images of it were released in 2022." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "How long does light from the Sun take to reach Earth?", options: JSON.stringify(["8 seconds","8 minutes","8 hours","8 days"]), correctAnswer: "8 minutes", funFact: "Light covers the 150 million km from the Sun in about 8 minutes and 20 seconds. The energy in a single photon of sunlight that lands on your skin took 100,000 years of random bouncing inside the Sun's core before finally escaping. That means the sunlight you feel right now left the Sun's surface before you were born." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is a 'red giant'?", options: JSON.stringify(["A massive young blue star","A dying star that has expanded","A star made of red gas at birth","A star with a red planet"]), correctAnswer: "A dying star that has expanded", funFact: "When a star like our Sun runs out of hydrogen fuel, its core collapses and its outer layers expand enormously — swelling up to 100 times its current size. It is not literally red-hot; it is red only because its surface cools as it stretches. In about 5 billion years, the Sun will become a red giant and likely engulf Mercury, Venus and Earth." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is the maximum mass a white dwarf can have before collapsing further?", options: JSON.stringify(["About 1.4 times the Sun's mass","About 14 times the Sun's mass","About 0.14 times the Sun's mass","About 140 times the Sun's mass"]), correctAnswer: "About 1.4 times the Sun's mass", funFact: "This limit is called the Chandrasekhar limit, after Indian-American astrophysicist Subrahmanyan Chandrasekhar, who won the 1983 Nobel Prize for his work on it. Push a white dwarf past 1.4 solar masses and it explodes as a Type Ia supernova — a cosmic bomb that outshines an entire galaxy and is used as a 'standard candle' for measuring cosmic distances." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "Which space telescope, launched in 1990, is still operating?", options: JSON.stringify(["Kepler","Hubble","Spitzer","Chandra"]), correctAnswer: "Hubble", funFact: "Hubble orbits about 540 km above Earth at roughly 28,000 km/h, completing one orbit every 95 minutes. It has required five servicing missions by astronauts, and its mirror was famously corrected in 1993 after it was found to have a flaw of about 1/50th the width of a human hair. It has taken more than 1.5 million photographs of the universe." },
  { category: "Nature & Plants", difficulty: "EASY", question: "What is the pigment that gives most plants their green colour?", options: JSON.stringify(["Chlorophyll","Melanin","Keratin","Carotene"]), correctAnswer: "Chlorophyll", funFact: "Chlorophyll absorbs red and blue light strongly but reflects green light — which is why leaves look green. The word comes from the Greek 'chloros' (green) and 'phyllon' (leaf). Autumn leaves turn yellow and red because chlorophyll breaks down, revealing pigments that were there all along." },
  { category: "Nature & Plants", difficulty: "EASY", question: "Which plant is the fastest growing plant on Earth?", options: JSON.stringify(["Giant Sequoia","Bamboo","Water Lily","Sunflower"]), correctAnswer: "Bamboo", funFact: "Some bamboo species can shoot up nearly 1 metre in a single day, reaching 30 metres in just a few months. This explosive growth makes bamboo a hugely popular building material and a vital food source for pandas. Despite its fast growth, bamboo is actually a grass, not a tree." },
  { category: "Nature & Plants", difficulty: "EASY", question: "What do we call a relationship where a fungus helps a plant absorb nutrients in exchange for sugars?", options: JSON.stringify(["Mycorrhizae","Photosynthesis","Pollination","Percolation"]), correctAnswer: "Mycorrhizae", funFact: "Around 90% of land plants form mycorrhizal partnerships. The fungus acts as a vast underground internet, its threads reaching far deeper and thinner than plant roots. One study found a fungus network weighing around 400 tonnes beneath an Oregon forest floor — one of the largest organisms on Earth." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "What is 'xylem'?", options: JSON.stringify(["The tissue that carries water up through a plant","The tissue that makes sugars","The cells that store starch","The outer bark of a tree"]), correctAnswer: "The tissue that carries water up through a plant", funFact: "Xylem is essentially a plant's plumbing. Water is pulled upward through it by a tension called the transpiration stream — generated by evaporation from leaves. Some of the tallest trees, like the coast redwood, pump water more than 100 metres straight up, with the force provided entirely by the sun." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "Which tree is the national flower tree of Japan?", options: JSON.stringify(["Maple","Cherry Blossom","Pine","Ginkgo"]), correctAnswer: "Cherry Blossom", funFact: "The cherry blossom, or 'sakura', is so culturally significant that the Japanese national news reports the bloom forecast every year. Hanami — picnicking under the blossoms — is a centuries-old tradition. The bloom front moves north across Japan at roughly 20–30 km per day, tracked in a phenomenon known as the 'cherry blossom front'." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "What does 'deciduous' describe?", options: JSON.stringify(["Plants that shed their leaves seasonally","Plants that stay green all year","Plants that reproduce via spores","Plants that grow underwater"]), correctAnswer: "Plants that shed their leaves seasonally", funFact: "Deciduous trees drop their leaves as a survival strategy — thin leaves would lose too much water to winter frost. Each leaf detaches at an abscission layer, a weak seam of cells that seals the wound. Deciduous forests are far more fertile than evergreen ones because returning leaf litter returns nutrients to the soil." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "Which genus of flowering plant is the largest in the world?", options: JSON.stringify(["Epidendrum","Rosa","Orchis","Ficus"]), correctAnswer: "Epidendrum", funFact: "The genus Epidendrum contains more than 1,500 orchid species — more than any other plant genus. Orchids as a whole number over 28,000 species, second only to the asters. Their tiny seeds are dust-like, relying on wind or fungus to germinate, which is why orchids are so rarely found growing in disturbed soil." },
  { category: "Nature & Plants", difficulty: "HARD", question: "What is the name of the world's oldest known non-clonal tree?", options: JSON.stringify(["Methuselah","General Sherman","The Lone Cypress","Pando"]), correctAnswer: "Methuselah", funFact: "Methuselah is a Great Basin bristlecone pine in California's White Mountains, aged at roughly 4,850 years — older than the ancient Egyptian pyramids. Its secret is its harsh, dry habitat at 3,000 m elevation, which keeps other species and pests away. A dendrochronology lab in this forest works in a tiny tent, outdoors, year-round." },
  { category: "Nature & Plants", difficulty: "HARD", question: "What is 'etiolation' in plant biology?", options: JSON.stringify(["Pale, stretched growth in darkness","The loss of leaves in autumn","The sprouting of a seed","The greening of a plant"]), correctAnswer: "Pale, stretched growth in darkness", funFact: "When a seedling grows without light it becomes etiolated — tall, spindly, yellow-white and fragile. It is searching for light because chlorophyll needs photons to assemble. Gardeners who want bushier, stronger plants sometimes cover seedlings briefly, tipping them to trigger 'thigmotropism' — reaching toward light." },
  { category: "Nature & Plants", difficulty: "HARD", question: "Which nutrient is the one most commonly deficient in agricultural soil?", options: JSON.stringify(["Phosphorus","Nitrogen","Calcium","Sodium"]), correctAnswer: "Nitrogen", funFact: "Nitrogen makes up 78% of the atmosphere, yet plants cannot use atmospheric nitrogen directly. Farmers must supply it as fertiliser, and the Haber-Bosch process — which converts air into ammonia — is called the most important industrial chemical process of the 20th century. Without it, feeding the modern world would be impossible." },
  { category: "Board Games & Strategy", difficulty: "EASY", question: "In chess, which piece moves in an L-shape?", options: JSON.stringify(["Bishop","Knight","Rook","Queen"]), correctAnswer: "Knight", funFact: "The knight is the only piece that jumps over others, and the only one that can never capture a piece directly in front of it. Each knight on a standard board controls exactly 8 squares. There are about 1,400 years of recorded chess history, with modern chess emerging from the shatranj game that travelled from Persia to Europe in the 9th century." },
  { category: "Board Games & Strategy", difficulty: "EASY", question: "How many letter tiles are in a standard English Scrabble set?", options: JSON.stringify(["98","100","102","120"]), correctAnswer: "100", funFact: "The 100 tiles are distributed by letter value — there are 50 points available in ones, 8 in twos, 7 in threes, and just 2 fours. A perfect Scrabble play scores 50 points in a single move, achieved in theory. Scrabble was created in the 1930s by Alfred Mosher Butts, a New York architect who loved word games." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "How many spaces are on a standard Monopoly board?", options: JSON.stringify(["36","40","42","48"]), correctAnswer: "40", funFact: "A Monopoly board has 40 spaces but only 28 are purchasable properties — 22 streets, 4 railroads and 2 utilities. The remaining 12 are corner squares and tax/special spaces. The famous 'corner' rule gives the player landing on Go a $200 salary, which is why experienced players try to stay there." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "In the board game Go, what is the goal?", options: JSON.stringify(["To be the last player standing","To surround and capture the most territory","To move all your pieces home","To build the tallest tower"]), correctAnswer: "To surround and capture the most territory", funFact: "Go is around 2,500 years old and originates from ancient China. A single move can affect hundreds of stones at once, and the number of legal positions is larger than the estimated number of atoms in the observable universe. Professional players have been compared to grandmasters in chess — the best AI, AlphaGo, defeated world champion Lee Sedol in 2016." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "What is the maximum number of properties one player can own in Monopoly?", options: JSON.stringify(["22","24","28","32"]), correctAnswer: "28", funFact: "Owning every one of the 22 street properties plus all 4 railroads and 2 utilities gives 28. With all four railroads in hand, a player collecting $200 rent can bankroll almost anything. A single pass over Boardwalk and Park Place with the full set is enough to win most games on the spot." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "How many supply centres are needed to win the board game Diplomacy?", options: JSON.stringify(["12","18","24","30"]), correctAnswer: "18", funFact: "There are exactly 34 supply centres on the Diplomacy map, and you need 18 to win. Crucially, there is no combat — units cannot attack each other. The only way to remove a rival is to convince them to leave. So the real game is negotiation and betrayal, and famously a game's 32nd-turn negotiation can last eight hours." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "What is the name of the chess term for a position where every move you make makes things worse?", options: JSON.stringify(["Stalemate","Zugzwang","Fork","Pin"]), correctAnswer: "Zugzwang", funFact: "Zugzwang is most common in endgames with pawns — a position where the player to move would rather pass. It was described by Aron Nimzowitsch in 1927 and named by Hans Kmoch. A famous example is when a knight attacks a pinned king, since the king must move to safety yet must then respond to the attack." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "What chess opening is defined by the moves 1. e4 e5 2. Nf3 Nc6 3. Bb5?", options: JSON.stringify(["Sicilian Defence","Ruy Lopez","Queen's Gambit","French Defence"]), correctAnswer: "Ruy Lopez", funFact: "The Ruy Lopez is named after a 16th-century Spanish bishop who funded the Spanish expedition to the Americas. It is one of the three most important openings in chess, and it was the favourite of world champion José Raúl Capablanca, who won more games with 1.e4 e5 than any other opening. It has been called the 'Spanish torture'." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What does 'LOL' stand for in internet slang?", options: JSON.stringify(["Laugh Out Loud","Love of Life","Lots of Laughter","Loss of Life"]), correctAnswer: "Laugh Out Loud", funFact: "'LOL' was in use by the late 1980s — long before text messaging. The World Wide Web's first joke page is often cited as being from 1990s. Today 'LOL' has softened in meaning: many users use it simply as an acknowledgment, similar to 'got it,' rather than to indicate actual laughter." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What does 'DM' stand for on social media?", options: JSON.stringify(["Direct Message","Deep Message","Digital Memory","Distant Mode"]), correctAnswer: "Direct Message", funFact: "DMs are private messages sent directly between users, unlike public posts or comments. Twitter introduced the term in 2010 when it re-branded 'Twitter Direct' simply to 'DM'. The abbreviation 'PM' (private message) remains in use on other platforms, and both usually share the same limits as a public post." },
  { category: "Internet & Memes", difficulty: "EASY", question: "Which company owns Instagram?", options: JSON.stringify(["Meta","ByteDance","Google","Snap Inc."]), correctAnswer: "Meta", funFact: "Instagram launched in 2010 and was bought by Facebook in 2012 for around $1 billion. It now has more than 2 billion monthly users. Its founders Kevin Systrom and Mike Krieger had built a previous location-based check-in app called Burbn, and Instagram was essentially a streamlined version of it." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What does '404' mean on a website?", options: JSON.stringify(["Server is overloaded","Page not found","Login required","Payment needed"]), correctAnswer: "Page not found", funFact: "404 is an HTTP status code returned when a requested page doesn't exist. The number itself is a joke — April 4, 2004, a date popular for 'joke' ideas at the origin of the World Wide Web. Other fun codes include 418 I'm a teapot, which is still used as an April Fools joke." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "What is 'shadow banning'?", options: JSON.stringify(["Hiding a user's posts from other people","Deleting an account for bad language","Blocking an IP address","Paying to boost a post"]), correctAnswer: "Hiding a user's posts from other people", funFact: "In shadow banning, the poster still sees their own content and thinks it is doing fine, but it is quietly made invisible to everyone else. Platforms argue it is used to combat spam, while critics say it is used to suppress dissent. It is extremely difficult for users to detect without using a separate account." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "What is the practice of a company posing as customers to promote its own product called?", options: JSON.stringify(["Astroturfing","Bracketing","Astroturf","Astroturfling"]), correctAnswer: "Astroturfing", funFact: "The name is a play on 'grassroots' — implying the support is organic and bottom-up, when it is actually paid for. Astroturfing has been used in tobacco lobbying and in political campaigns, including covert operation 'Operation Cardboard' in 2017. In 2019 the UK banned such undisclosed political advertising on social media." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "Which platform is known for 'retweeting'?", options: JSON.stringify(["Twitter / X","TikTok","Pinterest","Twitch"]), correctAnswer: "Twitter / X", funFact: "A retweet reshares someone else's post with one tap, letting it spread far beyond its original audience. The feature was added in March 2009 as a simple 'Retweet this Tweet' button. Later, native retweet and quote-tweet options were added so users could add their own commentary instead of just reposting verbatim." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What was the name of the botnet that took down major websites with a massive DDoS attack in 2017?", options: JSON.stringify(["Mirai","Zeus","WannaCry","Stuxnet"]), correctAnswer: "Mirai", funFact: "Mirai infected over 600,000 IoT devices — cameras, routers, DVRs — then fired 300,000 requests per second at targets like Twitter, Netflix and Reddit. The name means 'future' in Japanese, an ironic choice. Its author was arrested in 2017; the malware's source code was later published, inspiring dozens of copycat variants." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What is 'ransomware'?", options: JSON.stringify(["Software that shows unwanted adverts","Malware that encrypts files and demands payment","A firewall blocking inbound traffic","A tool that speeds up internet"]), correctAnswer: "Malware that encrypts files and demands payment", funFact: "Ransomware locks a victim's files and demands payment, often in cryptocurrency, for the key. The largest known case was the 2017 'WannaCry' attack, which locked an estimated 200,000 computers in 150 countries — including hospitals in the UK, forcing patient records offline. Experts advise against paying, as there's no guarantee of recovery." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What file tells search engine crawlers which pages of a site they may index?", options: JSON.stringify(["robots.txt","sitemap.xml","index.html",".htaccess"]), correctAnswer: "robots.txt", funFact: "The robots.txt standard was created in 1994 to prevent well-behaved crawlers from overloading servers. Notably, it is a convention rather than a security feature — most robots ignore it entirely. A 'Disallow' rule does not hide a page from determined users or determined scrapers; it only asks politely." },
  { category: "Economics & Business", difficulty: "EASY", question: "What does 'ROI' stand for in business?", options: JSON.stringify(["Rate of Income","Return on Investment","Revenue Over Inventory","Risk of Investment"]), correctAnswer: "Return on Investment", funFact: "ROI is calculated as (gain from investment minus cost) divided by cost, expressed as a percentage. Its biggest weakness is that it ignores the time value of money — a 20% return in a week looks better than 20% in ten years. Businesses therefore pair it with NPV (net present value) for bigger decisions." },
  { category: "Economics & Business", difficulty: "EASY", question: "What is a company's 'revenue'?", options: JSON.stringify(["Total money from sales of goods or services","Money left after all expenses","Total value of shareholders' equity","Cash in the company bank account"]), correctAnswer: "Total money from sales of goods or services", funFact: "Revenue is the top line of an income statement — everything before costs are subtracted. It is not the same as profit, and not the same as cash, because most sales are made on credit. A company can be profitable yet still fail simply because customers haven't paid their bills yet." },
  { category: "Economics & Business", difficulty: "EASY", question: "What is the term for the difference between a country's exports and imports?", options: JSON.stringify(["Trade balance","Gross Domestic Product","Balance of payments","Net exports index"]), correctAnswer: "Trade balance", funFact: "A positive trade balance is a surplus, a negative one a deficit. The US has run persistent goods trade deficits for decades, meaning it imports more than it exports — which is partly why the dollar is so heavily traded. Because the comparison is goods only, a country with a goods deficit can still have an overall surplus once services are counted." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What is a 'hostile takeover'?", options: JSON.stringify(["A merger agreed by both boards","A buyer acquiring a company against the board's wishes","A government nationalising a firm","A company filing for bankruptcy"]), correctAnswer: "A buyer acquiring a company against the board's wishes", funFact: "In a hostile takeover, the acquirer bypasses management — buying enough shares directly from shareholders, or making an unsolicited public offer. Notable examples include Oracle's bid for PeopleSoft and the 2007 Procter & Gamble attempt to buy Gillette. Many such deals succeed only through increasingly hostile tactics, or turn into legal battles." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "Which term describes the rate at which central banks lend to each other?", options: JSON.stringify(["Bank rate","Bond yield","Prime rate of inflation","Discount coupon"]), correctAnswer: "Bank rate", funFact: "The bank rate (or interbank rate) is the anchor of a country's financial system — changing it ripples through mortgages, savings and business loans. In the US the equivalent is the federal funds rate, which the Federal Reserve raises and lowers. Central banks mainly use it to steer inflation toward a target of around 2%." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What does 'monopoly' mean in economics?", options: JSON.stringify(["A market with many competing sellers","A single seller with no competitors","A government-owned industry","A market with no demand"]), correctAnswer: "A single seller with no competitors", funFact: "A true monopoly has 100% market share, letting it set any price. Most modern economies have a few such structures: utilities, railways, and in some countries broadband or mobile networks. They are often regulated, or could become complete monopolies — which is why net neutrality rules are fought over so fiercely." },
  { category: "Economics & Business", difficulty: "HARD", question: "What is the 'Phillips Curve' trade-off?", options: JSON.stringify(["Unemployment versus inflation","Imports versus exports","Growth versus debt","Wages versus profits"]), correctAnswer: "Unemployment versus inflation", funFact: "The curve, named for A.W. Phillips, suggested lower unemployment came at the cost of higher inflation. It held for decades after WWII but broke down in the 1970s, when both unemployment and inflation rose together — the 'stagflation' problem. This remains one of the central puzzles in macroeconomics." },
  { category: "Economics & Business", difficulty: "HARD", question: "What does 'IPO' stand for?", options: JSON.stringify(["Internal Price Option","Initial Public Offering","Increased Private Ownership","Index of Public Ownership"]), correctAnswer: "Initial Public Offering", funFact: "An IPO is the first time a private company sells its shares to the public. Facebook's 2012 IPO was one of the largest ever, raising about $16 billion and valuing the company near $104 billion. The term comes from the Latin 'in publicaMPTIO,' meaning the public taking up a share." },
  { category: "Economics & Business", difficulty: "HARD", question: "What was the main trigger of the 2008 global financial crisis?", options: JSON.stringify(["A fall in oil prices","The subprime mortgage crisis","A trade embargo on Japan","A collapse in the gold market"]), correctAnswer: "The subprime mortgage crisis", funFact: "Lenders had flooded the US with risky subprime mortgages — loans to borrowers with poor credit. When house prices fell, borrowers stopped paying, mortgage-backed securities collapsed and banks found themselves unable to lend to anyone. Around 10 million American families lost their homes, and the disaster triggered the largest economic contraction since the 1930s." },
  { category: "Language & Words", difficulty: "EASY", question: "What do you call a word that imitates a sound, like 'buzz' or 'clang'?", options: JSON.stringify(["Simile","Onomatopoeia","Alliteration","Metaphor"]), correctAnswer: "Onomatopoeia", funFact: "From the Greek 'onoma' (name) and 'poiein' (to make) — 'name-making'. It appears in every language, though often in different forms: English 'cock-a-doodle-doo', Japanese 'moo' and Turkish 'gırgır'. It is especially prominent in comics, where 'POW!' and 'BANG!' are drawn inside speech balloons." },
  { category: "Language & Words", difficulty: "EASY", question: "Which language family does Japanese belong to?", options: JSON.stringify(["Sino-Tibetan","Japonic","Altaic","Koreanic"]), correctAnswer: "Japonic", funFact: "Japanese is more closely related to Korean than to Chinese, despite sharing thousands of Chinese characters. Its grammar is agglutinative — small pieces called particles mark tense, negation and case, and words are built by stacking morphemes. Japanese also has three different scripts: hiragana, katakana and kanji." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is the term for two words that sound the same but differ in spelling and meaning?", options: JSON.stringify(["Synonyms","Antonyms","Homophones","Acronyms"]), correctAnswer: "Homophones", funFact: "English has thousands: 'write'/'right', 'there'/'their', 'two'/'too'. Shakespeare loved them for comedy, and he's credited with inventing or first recording words like 'lonely', 'eyeball' and 'wild-goose chase'. Related but distinct is 'homonyms' — words spelled alike but unrelated, like 'bat' the animal and 'bat' the club." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is 'eponymous'?", options: JSON.stringify(["Named after a particular person","Made up of two words","Clearly false","Having no name"]), correctAnswer: "Named after a particular person", funFact: "An eponym is a word or name taken from a person — 'Machiavellian' from Niccolò Machiavelli, 'quasar' from a quasi-stellar radio source. The opposite is 'anon', meaning without a name. Eponyms are everywhere in science, geography and medicine, and are a handy way to date ideas: once enough eponyms pile up, a field has matured." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is the repetition of a word at the start of successive lines or clauses called?", options: JSON.stringify(["Rhythm","Anaphora","Paradox","Elegy"]), correctAnswer: "Anaphora", funFact: "Anaphora is a very old device — used in the Bible ('Blessed are those who mourn') and famously by Martin Luther King Jr in 'I Have a Dream', repeating 'I have a dream' nine times. Its opposite, repetition at the end of clauses, is called epistrophe. Together they form a ring composition." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is the study of word origins called?", options: JSON.stringify(["Phonetics","Etymology","Semantics","Grammar"]), correctAnswer: "Etymology", funFact: "From the Greek 'etymon', meaning 'true word or origin'. Etymologists work like detectives, tracing words across languages and centuries: 'nice' once meant 'foolish', 'girl' meant 'young person of either sex', and 'salary' comes from the Latin 'salarium' — which is why it has nothing to do with salt, despite the common myth." },
  { category: "Language & Words", difficulty: "HARD", question: "What is 'epenthesis' in linguistics?", options: JSON.stringify(["Inserting a sound inside a word","Dropping the final consonant of a word","Swapping two adjacent syllables","Lengthening a vowel"]), correctAnswer: "Inserting a sound inside a word", funFact: "Epenthesis explains why English has a plural 'houses' (from 'hous') but 'buses' (from 'bus'). It also produced the 's' in 'baseball' from 'bas' and the 'o' in 'smoking' from 'smking'. This is why English plurals and past tenses are irregular — the extra sound was once a full vowel." },
  { category: "Language & Words", difficulty: "HARD", question: "What is the term for words spelled identically but with unrelated meanings, like 'bat'?", options: JSON.stringify(["Homophones","Homonyms","Synonyms","Antonyms"]), correctAnswer: "Homonyms", funFact: "Homonyms are homophones that are also homographs — same spelling, same sound, but entirely separate entries in the dictionary. 'Bank' (financial institution) and 'bank' (side of a river) are homonyms. A single pair can carry two unrelated histories, which is why a good dictionary lists them as separate headwords." },
  { category: "Art & Literature", difficulty: "EASY", question: "Which art movement is Salvador Dalí associated with?", options: JSON.stringify(["Cubism","Surrealism","Impressionism","Pointillism"]), correctAnswer: "Surrealism", funFact: "Surrealism aimed to release the unconscious mind, and Dalí's melting clocks in 'The Persistence of Memory' are its defining image. He also pioneered 'paranoiac-critical method' — a technique of double images meant to be interpreted two ways. The movement ran from the 1920s to the 1940s and was heavily shaped by Freud's writing." },
  { category: "Art & Literature", difficulty: "EASY", question: "What is the term for a sculpture that projects only slightly from an architectural surface?", options: JSON.stringify(["Sculpture in the round","Bas-relief","Fresco","Mosaic"]), correctAnswer: "Bas-relief", funFact: "Bas-relief projects from a flat background, as seen on ancient Greek and Roman temples and coins. 'Bas' comes from the Italian for 'low'. In higher relief the figures project more deeply — 'alto-relievo' — while 'alto-rilievo' and 'grand relief' are used for fully three-dimensional work. The technique also survives in modern memorials and banknotes." },
  { category: "Art & Literature", difficulty: "EASY", question: "Who painted 'The Starry Night'?", options: JSON.stringify(["Claude Monet","Pablo Picasso","Vincent van Gogh","Paul Cézanne"]), correctAnswer: "Vincent van Gogh", funFact: "Van Gogh painted 'The Starry Night' in 1889 from the window of an asylum in Saint-Rémy, a few months before his death. He described it as a dream rather than a view from life. He only sold one painting in his lifetime, for 400 francs — about $35 today — despite now being one of the most recognized artists in history." },
  { category: "Art & Literature", difficulty: "EASY", question: "Which painter created 'Guernica'?", options: JSON.stringify(["Salvador Dalí","Pablo Picasso","Diego Rivera","Joan Miró"]), correctAnswer: "Pablo Picasso", funFact: "Picasso painted 'Guernica' in 1937 after a bombing raid on the Basque town during the Spanish Civil War. He refused to let it hang in Spain while Franco was in power, and instead kept it in his studio, where it rotated. The monochrome 3.5-metre canvas is often called the most powerful anti-war painting ever made." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "Which art movement focused on capturing the effects of light and movement in the open air?", options: JSON.stringify(["Impressionism","Cubism","Fauvism","Neoclassicism"]), correctAnswer: "Impressionism", funFact: "Impressionism began in France in the 1870s, and its name comes from a hostile review of Monet's 'Impression, Sunrise' — the critic Louis Leroy mocked the paintings as unfinished sketches. They were radical: painted outdoors, in loose visible brushstrokes, capturing a fleeting moment. The movement redefined what counted as finished art." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "Which short story is widely considered the first detective story ever written?", options: JSON.stringify(["The Murders in the Rue Morgue","The Moonstone","The Sign of the Four","A Study in Scarlet"]), correctAnswer: "The Murders in the Rue Morgue", funFact: "Edgar Allan Poe's 1841 story introduced C. Auguste Dupin, the first fictional detective, and the analytical method he uses — deduction from evidence, not intuition. Conan Doyle was directly inspired by Poe. Poe also wrote 'The Tell-Tale Heart' and 'The Fall of the House of Usher', founding much of modern horror as a genre." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "Which playwright wrote 'A Doll's House'?", options: JSON.stringify(["Anton Chekhov","Henrik Ibsen","Bertolt Brecht","Samuel Beckett"]), correctAnswer: "Henrik Ibsen", funFact: "'A Doll's House' (1879) ends with Nora slamming the door and leaving her husband — a shock that resonated worldwide and helped launch modern realist theatre. Ibsen is often called the father of modern drama, writing in a plain, everyday idiom rather than elevated verse. He was nominated for the Nobel Prize in Literature twice and never won." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "Who wrote 'One Hundred Years of Solitude'?", options: JSON.stringify(["Jorge Luis Borges","Gabriel García Márquez","Mario Vargas Llosa","Isabel Allende"]), correctAnswer: "Gabriel García Márquez", funFact: "Published in 1967, the novel follows seven generations of the Buendía family and is the masterpiece of magical realism — where fantastical events are narrated with deadpan realism. It sold over 50 million copies and remains the most-translated work by a Spanish-language author. 'One Hundred Years' refers to the town of Macondo, founded the day the Buendías are massacred by a sleeping rose." },
  { category: "Art & Literature", difficulty: "HARD", question: "What is 'chiaroscuro'?", options: JSON.stringify(["The use of strong contrast between light and dark","A technique of painting in thin layers","A method of preparing a canvas","The study of light in nature"]), correctAnswer: "The use of strong contrast between light and dark", funFact: "From the Italian, meaning 'light-dark'. Chiaroscuro models forms through dramatic lighting, and it's what gives Leonardo's 'Mona Lisa' her mysterious expression. Caravaggio took it to an extreme, plunging figures into near-darkness — earning his nickname 'Caravaggio, who paints dark'. The term also survives in photography, especially in portrait lighting." },
  { category: "Art & Literature", difficulty: "HARD", question: "What is a 'palimpsest' in manuscript studies?", options: JSON.stringify(["A page whose text was erased and overwritten","A book printed on both sides","A text written entirely in rhyme","A scroll that is rolled up"]), correctAnswer: "A page whose text was erased and overwritten", funFact: "Parchment was so costly and scarce that monasteries scraped it clean and reused it, leaving the earlier text faintly visible beneath. Modern imaging techniques like multispectral imaging can recover these erased layers. The word has spread into ordinary English as a metaphor for any text or history that has been written over but still legible underneath." },
  { category: "Art & Literature", difficulty: "HARD", question: "Which 1922 novel introduced the character Jay Gatsby?", options: JSON.stringify(["The Great Gatsby","The Catcher in the Rye","Ulysses","Mrs Dalloway"]), correctAnswer: "The Great Gatsby", funFact: "F. Scott Fitzgerald's 'The Great Gatsby' is widely regarded as the greatest American novel, though it sold poorly in his lifetime. Gatsby's green light at the end of the dock has become one of the most famous symbols in literature. Fitzgerald died believing the book a failure; it sold over 100 million copies in the century after his death." },
  { category: "Automotive", difficulty: "EASY", question: "How many cylinders does a standard V8 engine have?", options: JSON.stringify(["4","6","8","12"]), correctAnswer: "8", funFact: "A V8 has eight cylinders arranged in two banks of four at a 90-degree angle — the 'V'. It is one of the most popular engine layouts ever made, famous for American muscle cars. Ferrari and Formula 1 cars also use V8s, but no V16 has ever produced enough power to reliably drive a car — the vibration destroys the crankshaft." },
  { category: "Automotive", difficulty: "EASY", question: "What does 'ABS' stand for in a car?", options: JSON.stringify(["Automatic Braking System","Anti-lock Braking System","Advanced Braking Sensor","Air Braking Suspension"]), correctAnswer: "Anti-lock Braking System", funFact: "ABS prevents wheel lockup during hard braking, letting you keep steering control. Bosch developed it for aircraft in the 1930s, and it became standard on cars from the late 1980s. Studies show it reduces fatal accident risk, but it doesn't shorten stopping distance on gravel or snow — where a locked wheel can actually help." },
  { category: "Automotive", difficulty: "EASY", question: "In car specifications, what does 'HP' measure?", options: JSON.stringify(["Fuel consumption","Power","Pressure","Horsepower of towing capacity"]), correctAnswer: "Power", funFact: "'Horsepower' was invented by James Watt, who compared steam engines to the work of draft horses. Watt's figures were conservative, so modern horsepower units are actually conservative too. A US 'mechanical horsepower' is about 746 watts. Cars are usually rated in kW in Europe and horsepower in the US, which is why figures differ between markets." },
  { category: "Automotive", difficulty: "MEDIUM", question: "What does 'AWD' stand for?", options: JSON.stringify(["All-Wheel Drive","Automatic Wide Drive","Advanced Weight Distribution","All-Weather Drive"]), correctAnswer: "All-Wheel Drive", funFact: "AWD sends power to all four wheels, improving traction on snow, mud and wet roads. It differs from 4WD, which typically has a low-range gearbox for off-roading and can engage on demand. Subaru is unusual in selling symmetrical AWD as standard on almost every model — one reason it dominates in snowy northern markets." },
  { category: "Automotive", difficulty: "MEDIUM", question: "What is 'torque' in a car?", options: JSON.stringify(["The maximum speed of the engine","The rotational force of the engine","The fuel consumption rate","The engine's total displacement"]), correctAnswer: "The rotational force of the engine", funFact: "Torque is what you feel when you press the accelerator; horsepower is what the towing figures depend on. Because torque is a force, it's multiplied by engine RPM to give power. Small diesel engines are prized for producing lots of torque at low revs, which is why they feel stronger when pulling away than bigger petrol engines of the same size." },
  { category: "Automotive", difficulty: "MEDIUM", question: "In what year was the Ford Model T introduced?", options: JSON.stringify(["1896","1908","1920","1935"]), correctAnswer: "1908", funFact: "The Model T ran for 19 years, and over 15 million were built — by far the longest production run of any car ever. Ford's moving assembly line, introduced in 1913, cut its price from around $850 to under $500, and by the 1920s the car was affordable to a mass market. Henry Ford said his customers wanted 'a car to go to church in' — and priced it accordingly." },
  { category: "Automotive", difficulty: "HARD", question: "What is 'engine downsizing'?", options: JSON.stringify(["Using a smaller engine with turbocharging","Reducing the wheel size","Removing safety systems","Shortening the gearbox"]), correctAnswer: "Using a smaller engine with turbocharging", funFact: "Downsizing lets a small engine meet strict fuel-economy rules, with a turbocharger forcing in extra air to compensate for its lower displacement. It was the key to dieselgate: 2015 testing showed makers gaming the emissions test, and the scandal cost the industry billions and prompted stricter testing. Real-world emissions are often far higher than official figures." },
  { category: "Automotive", difficulty: "HARD", question: "Which measurement is famously used to set lap records at the Nürburgring?", options: JSON.stringify(["Top speed on a straight","Lap times on a circuit","Fuel economy per lap","Braking distance"]), correctAnswer: "Lap times on a circuit", funFact: "The Nürburgring Nordschleife is a 20.8 km 'Green Hell' track with around 300 corners carved through the German countryside. Because a lap time captures performance across corners, straights and elevation, manufacturers use it as the standard proof of a car's handling balance. The track was also a dangerous public road before being closed for racing in 1976." },
  { category: "Automotive", difficulty: "HARD", question: "How is a car's resistance to rolling over often measured?", options: JSON.stringify(["By measuring the static stability factor","By timing a skid pad lap","By checking the fuel gauge","By measuring the brake pedal travel"]), correctAnswer: "By measuring the static stability factor", funFact: "The static stability factor (SSF) measures a vehicle's centre of gravity height divided by its track width — a taller centre of gravity raises the rollover risk. A typical car scores around 1.2–1.5, while SUVs and trucks score 1.0 or below, making them markedly less safe in a rollover. Sportier cars score much higher, which is why they feel planted at speed." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "Who is the Greek goddess of love and beauty?", options: JSON.stringify(["Athena","Aphrodite","Hera","Artemis"]), correctAnswer: "Aphrodite", funFact: "According to Hesiod, Aphrodite was born from sea foam washing ashore on Cyprus — she is the only major Greek god born of the sea rather than from Titan parents. The Roman equivalent is Venus, and the planet Venus is named after her. She was famously married to Hephaestus, the forge god, but had famous lovers including Ares and the mortal Anchises." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "Who is the Norse god of thunder?", options: JSON.stringify(["Odin","Loki","Thor","Freyr"]), correctAnswer: "Thor", funFact: "Thor's hammer, Mjölnir, was forged by the dwarf brothers and could be thrown and called back to his hand. He is strongest of the Aesir gods, defending both Asgard and Midgard from the giants. His day is named Thursday — 'Thor's day' — in every Germanic language, and his name survives in 'thunder'." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "Who is the Egyptian god of the sun?", options: JSON.stringify(["Osiris","Horus","Ra","Anubis"]), correctAnswer: "Ra", funFact: "Ra was the sun god and the primary creator in ancient Egypt, usually depicted with a falcon head and a solar disc. He was most important at Heliopolis, where priests believed he ruled from a boat that sailed across the sky each day and through the underworld each night. Through syncretism he merged with Amun to become Amun-Ra, Egypt's supreme god." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "Which Greek philosopher taught Alexander the Great?", options: JSON.stringify(["Socrates","Plato","Aristotle","Pythagoras"]), correctAnswer: "Aristotle", funFact: "Aristotle tutored Alexander from age 13 to 20, at a school in Metea funded by the future king. He was the tutor who gave his student a copy of Homer's Iliad, annotated and personally corrected. Aristotle later founded the Lyceum in Athens, where his students systematically catalogued biology, physics, poetry and logic." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "What is the 'Ship of Theseus' paradox?", options: JSON.stringify(["Whether an object stays the same when all its parts are gradually replaced","Whether free will can exist in a deterministic universe","Whether an infinite number can be counted","Whether a circle can be squared"]), correctAnswer: "Whether an object stays the same when all its parts are gradually replaced", funFact: "Theseus' ship was supposedly preserved in Athens for centuries, with every plank replaced as it rotted. So at some point it was no longer the original ship — yet it was also the same ship, continuously maintained. The puzzle has shaped talk about personal identity, teleportation and even transhumanism, and Plato used it to argue that reality is built from change rather than fixed forms." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "What is the term for the belief that a person's fate is determined by the stars?", options: JSON.stringify(["Astrology","Astronomy","Alchemy","Teleology"]), correctAnswer: "Astrology", funFact: "Astrology has been practised for millennia — Babylonian, Greek, Indian and Chinese traditions all have versions. The word combines 'astronomia' (study of the stars) and '-logia' (study of). In 2002 astronomers were asked in a survey whether astrology should be considered science: over 97% said no." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "What is the Buddhist concept of 'sunyata'?", options: JSON.stringify(["Emptiness","Rebirth","Detachment from desire","The four noble truths"]), correctAnswer: "Emptiness", funFact: "Sunyata is a central teaching of Mahayana Buddhism: all things lack an independent, permanent essence and exist only in relation to causes and conditions. It is not nihilism — nothing is said to be 'nothing' — but a rejection of the idea that things possess fixed, self-contained essence. The Heart Sutra's most famous line, 'form is emptiness', is its most compressed expression." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "Which Russian author wrote 'Crime and Punishment'?", options: JSON.stringify(["Leo Tolstoy","Fyodor Dostoevsky","Anton Chekhov","Ivan Turgenev"]), correctAnswer: "Fyodor Dostoevsky", funFact: "The 1866 novel follows Rodion Raskolnikov, a destitute student who murders a pawnbroker to test a theory that extraordinary men are permitted to break the law. Published under heavy censorship, it was a sensation. Dostoevsky survived a mock execution in 1849 and drew on that terror in 'The Idiot' and 'Crime and Punishment'." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "What is the name of the ancient Greek philosopher who taught Socrates?", options: JSON.stringify(["Aristotle","Plato","Democritus","Pythagoras"]), correctAnswer: "Plato", funFact: "Plato (428–348 BC) met Socrates as a young man and became his most devoted student. He founded the Academy in Athens, which became the first enduring institution of higher learning in the Western world. Since Socrates wrote nothing himself, we know him almost entirely through Plato's dialogues — the 'Socratic method' of questioning is named after a man we can only see in his student's writing." },
  { category: "Filipino Pop Culture", difficulty: "EASY", question: "What is the Filipino term for a movie theater?", options: JSON.stringify(["Palengke","Sinehan","Kiosko","Bodega"]), correctAnswer: "Sinehan", funFact: "'Sinehan' is from the Spanish 'cine' (film). Before the 1990s, every Philippine town had at least one 'movie house', often called 'paluba' after the Spanish 'pálvora' (gunpowder) — because early films were shown outdoors with a sheet and a projector that rattled like gunfire. 'Palengke' is the market and 'kiosk' the small stall." },
  { category: "Filipino Pop Culture", difficulty: "EASY", question: "What is the woven bamboo kite flown during Christmas in the Philippines?", options: JSON.stringify(["Walis","Barangay","Parol","Koro"]), correctAnswer: "Parol", funFact: "The parol is a star-shaped lantern made from bamboo and coloured paper, flown over rooftops in the weeks before Christmas. Its five points traditionally represent the Star of Bethlehem. The tradition was influenced by the 'pañálo' — a Spanish paper lantern brought home by soldiers returning from the Spanish-American War." },
  { category: "Filipino Pop Culture", difficulty: "EASY", question: "What is the everyday Filipino word 'Pinoy' a shortened form of?", options: JSON.stringify(["Filipino","Pilipino","Pinagsama","Pinagkakaisa"]), correctAnswer: "Pilipino", funFact: "'Pinoy' is the everyday, affectionate form of 'Pilipino' — a contraction created during the American colonial period from the letters 'P' and 'P'. 'Filipino' is the official term, and 'Pilipino' came from the original Philippine nationalist movement. The nickname has outlasted all of the political debate and is now embraced worldwide." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "What was the name of the Philippines' first television station, which began broadcasting in 1948?", options: JSON.stringify(["DZAQ-TV","ABS-CBN","GMA Network","TV5"]), correctAnswer: "DZAQ-TV", funFact: "DZAQ-TV went on air in Manila on 1 October 1948, making the Philippines the third country in Asia to get television. Broadcasts were black and white and often low quality, but they revolutionised news and entertainment. It was later absorbed into the government station KDBM, which is the direct ancestor of PTV." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "Which Filipino comedy duo of the 1970s–80s were hugely popular for their films and television work?", options: JSON.stringify(["Dolphy and Panchito","Ricky and Joey","Vic and Joey","Ate Vi and Betting"]), correctAnswer: "Dolphy and Panchito", funFact: "Dolphy and Panchito were among the biggest Filipino film stars of their era, appearing together in around 100 films. Their partnership defined a golden age of Filipino comedy, and Dolphy's 'John en Marsha' was a radio and TV phenomenon decades earlier. Their films were so popular that overseas Filipino communities saw them in cinemas in Hong Kong and Singapore." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "Which Filipino novelist wrote 'The Mango Makers'?", options: JSON.stringify(["F. Sionil Jose","Nick Joaquin","José García Villa","Carlos Bulosan"]), correctAnswer: "Nick Joaquin", funFact: "Nick Joaquin (1917–2004) was one of the great Filipino writers, and 'The Mango Makers' (1958) is a novella about a family in the capital during the Cultural Riches Program of the Marcos era. He won the National Book Award for 'The Cry and the Dedication' and was proclaimed National Artist for Literature. He also wrote a famous essay 'From the Masses' during the 1960s." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "Which Filipino director made the internationally acclaimed film 'Verdict' (2019)?", options: JSON.stringify(["Erik Matti","Lav Diaz","Raymund Ribay Gutierrez","Brillante Mendoza"]), correctAnswer: "Raymund Ribay Gutierrez", funFact: "'Verdict' follows a mute teenage boy accused of rape and the lawyer who takes his case, and it was the first Filipino film to compete for the Palme d'Or at Cannes. Raymund Ribay Gutierrez also directed 'Mindanao' and the acclaimed series 'Amo', which won best drama at the Asian Academy Creative Awards. Critics praise his restrained, humane storytelling." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "Which Filipino author wrote 'Po-on' and 'The Woman Who Had Two Navels'?", options: JSON.stringify(["José García Villa","F. Sionil Jose","Nick Joaquin","Carlos Bulosan"]), correctAnswer: "José García Villa", funFact: "José García Villa (1908–1961) was a major Filipino poet in English, and one of the few Filipinos declared National Artist for Literature while still alive. 'Po-on' is one of his longest works, an epic of Manila's street life in the 1920s. He was also a co-founder of the Philippine Academy of Literature in America, and 'Man Songs' was nominated for a Pulitzer." }
];

const extraQuestions8 = [
  { category: "Science", difficulty: "EASY", question: "Which blood cells carry oxygen around the body?", options: JSON.stringify(["White blood cells","Red blood cells","Platelets","Hormones"]), correctAnswer: "Red blood cells", funFact: "Red blood cells contain haemoglobin, an iron-containing protein that binds oxygen and gives blood its red colour. Your body makes around 2 million red blood cells every second to replace cells that wear out after about 120 days. They are so small that about 25 million of them could fit on a postage stamp." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the most abundant molecule in the human body?", options: JSON.stringify(["Protein","Water","Fat","DNA"]), correctAnswer: "Water", funFact: "Water makes up roughly 60% of an adult's body weight, and it is essential to nearly every chemical reaction you run. A person can survive weeks without food but only about three days without water. The water in your body is not just from drinking — about 20% of it arrives as food." },
  { category: "Science", difficulty: "MEDIUM", question: "What is the largest organ in the human body?", options: JSON.stringify(["Liver","Skin","Lungs","Brain"]), correctAnswer: "Skin", funFact: "Skin is the body's largest organ, weighing roughly 3.6 kg on a 60 kg person and covering about 2 square metres. It replaces itself completely about every 4 weeks, so a patch of skin you lose today is already being rebuilt. The brain may be heavier, but skin is the largest by surface area." },
  { category: "Science", difficulty: "MEDIUM", question: "What does DNA stand for?", options: JSON.stringify(["Deoxyribonucleic acid","Deoxyribose Nuclear Acid","Dinitro Nucleic Acid","Diribonucleic Acid"]), correctAnswer: "Deoxyribonucleic acid", funFact: "The 'deoxyribo' part means the sugar backbone lacks one oxygen atom compared with ribose sugar, which is what makes DNA far more chemically stable than RNA. DNA was first isolated in 1869 by Friedrich Miescher, long before anyone understood what it did." },
  { category: "Science", difficulty: "MEDIUM", question: "Approximately how fast does sound travel in air at sea level?", options: JSON.stringify(["343 m/s","343 km/s","1,200 km/h","3,000 m/s"]), correctAnswer: "343 m/s", funFact: "Sound travels roughly 1,230 km/h in air, but about four times faster in water and more than four times faster still in steel. The famous '3-3-3 rule' for estimating distance during a thunderstorm: divide the seconds between the flash and the thunder by 3 to get the distance in kilometres." },
  { category: "Science", difficulty: "MEDIUM", question: "Which blood cells are responsible for fighting infection?", options: JSON.stringify(["Red blood cells","White blood cells","Platelets","Hormones"]), correctAnswer: "White blood cells", funFact: "There are five main types of white blood cell, and each handles a different kind of invader. Neutrophils are the first responders, arriving within minutes of a wound, while lymphocytes mount a longer-lasting response. A healthy adult has roughly 4–11 billion white blood cells circulating at any moment." },
  { category: "Science", difficulty: "HARD", question: "What is Avogadro's number, the number of particles in one mole?", options: JSON.stringify(["3.14 × 10⁸","6.022 × 10²³","9.81 × 10²⁹","1.602 × 10⁻¹⁹"]), correctAnswer: "6.022 × 10²³", funFact: "Amedeo Avogadro proposed in 1811 that equal volumes of gases at the same temperature and pressure contain equal numbers of molecules. His constant is defined today as exactly 6.02214076 × 10²³, which makes it the one number in physics that is exact by definition rather than measured." },
  { category: "History", difficulty: "EASY", question: "What was the name of the ship that carried the Pilgrims to America in 1620?", options: JSON.stringify(["Mayflower","Santa Maria","HMS Endeavour","The Argo"]), correctAnswer: "Mayflower", funFact: "The Mayflower took 102 passengers across 65 days, and it ran aground at Provincetown before the settlers finally landed at Plymouth Rock. The ship's own journey to Virginia was a commercial venture that went wrong — the Pilgrims were 'stranded' passengers, and they wrote the Mayflower Compact before going ashore." },
  { category: "History", difficulty: "EASY", question: "Which ancient civilisation built the Colosseum?", options: JSON.stringify(["Ancient Egypt","Ancient Greece","The Roman Empire","The Persian Empire"]), correctAnswer: "The Roman Empire", funFact: "The Colosseum was completed in AD 80 under Emperor Titus and could hold around 50,000 spectators. It was built partly with forced Jewish labour after the destruction of Jerusalem, a fact documented on a surviving 2nd-century inscription. Its name comes from a colossal statue of Nero that stood nearby." },
  { category: "History", difficulty: "MEDIUM", question: "Which war is known as the 'War to End All Wars'?", options: JSON.stringify(["The Crimean War","World War I","The Franco-Prussian War","The Boer War"]), correctAnswer: "World War I", funFact: "The phrase came from H.G. Wells' 1914 book, written with enormous optimism about the war's effect on peace. The reality killed around 17 million people, and the Treaty of Versailles imposed such harsh terms on Germany that resentment there helped fuel WWII within 20 years. Few phrases in history have aged as badly." },
  { category: "History", difficulty: "MEDIUM", question: "Who was the first woman to win a Nobel Prize?", options: JSON.stringify(["Marie Curie","Rosalind Franklin","Ada Lovelace","Lise Meitner"]), correctAnswer: "Marie Curie", funFact: "Marie Curie won the Nobel Prize in Physics in 1903, then the Nobel Prize in Chemistry in 1911 — the only person ever to win in two different sciences. She also conducted much of her pioneering radiation research in a makeshift shed, and she was still using X-ray equipment in World War I when she died of aplastic anaemia." },
  { category: "History", difficulty: "MEDIUM", question: "What was the name of the prison Nelson Mandela was held in for 27 years?", options: JSON.stringify(["Polguard","Robben Island","Alcatraz","Kilmainham Gaol"]), correctAnswer: "Robben Island", funFact: "Robben Island is a 9 km island 7 km offshore from Cape Town, and Mandela spent the first 18 of his 27 years there. He was initially confined to a solitary cell barely larger than a garden shed, but was later allowed to teach other prisoners. Many of his fellow prisoners later became leaders in post-apartheid South Africa." },
  { category: "History", difficulty: "HARD", question: "What was the Rosetta Stone used for?", options: JSON.stringify(["To record a royal marriage","To decipher Egyptian hieroglyphs","To weigh gold for the treasury","To mark a trade route"]), correctAnswer: "To decipher Egyptian hieroglyphs", funFact: "The stone carries the same decree in three scripts — hieroglyphic, Demotic and ancient Greek. Scholars had been baffled by hieroglyphs for 1,400 years until Thomas Young identified Demotic as cursive Egyptian, and Jean-François Champollion used the Greek text to crack the code in 1822. It is now in the British Museum." },
  { category: "History", difficulty: "HARD", question: "Who was the Byzantine emperor who commissioned the Hagia Sophia?", options: JSON.stringify(["Constantine the Great","Justinian I","Heraclius","Basil II"]), correctAnswer: "Justinian I", funFact: "Justinian I built the Hagia Sophia between 532 and 537, and when it was unveiled it was the largest domed building on Earth — a feat not matched for another 1,000 years. According to legend, angels miraculously rescued the workers when an earlier attempt collapsed. Justinian also codified Roman law, the foundation of most European legal systems." },
  { category: "Geography", difficulty: "EASY", question: "What is the capital of Italy?", options: JSON.stringify(["Milan","Naples","Florence","Rome"]), correctAnswer: "Rome", funFact: "Rome is over 2,700 years old and contains an entire country within its city limits — Vatican City, the world's smallest sovereign state. Ancient Romans called it the 'Eternal City' because the ruins of 3,000 years still stand beneath the modern city. Its metro system uses the world's largest collection of ancient art in situ." },
  { category: "Geography", difficulty: "EASY", question: "Which country is known as the 'Land of the Rising Sun'?", options: JSON.stringify(["China","South Korea","Japan","Thailand"]), correctAnswer: "Japan", funFact: "The name Japan comes from the Chinese characters meaning 'origin of the sun', referring to its position east of Asia. The country has more than 6,800 islands, of which about 110 are heavily populated. Its cherry blossom forecasts are broadcast on national news each spring." },
  { category: "Geography", difficulty: "EASY", question: "What is the largest country in South America?", options: JSON.stringify(["Argentina","Peru","Brazil","Colombia"]), correctAnswer: "Brazil", funFact: "Brazil takes up roughly half the entire South American continent — about 8.5 million square kilometres, larger than the USA. It contains 60% of the Amazon rainforest and around 60% of the world's Amazon biodiversity. Brazil has been the world's 9th largest economy by GDP for decades." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which strait separates Spain from Morocco?", options: JSON.stringify(["Strait of Gibraltar","Strait of Hormuz","Bosphorus","Strait of Messina"]), correctAnswer: "Strait of Gibraltar", funFact: "At its narrowest the strait is only 13 km wide, separating Europe from Africa — yet it has been a major naval and trade route since ancient times. Gibraltar at its southern end is a British Overseas Territory, and the rock itself is one of the world's most closely watched strategic points. Ships pass through here to enter the Mediterranean." },
  { category: "Geography", difficulty: "MEDIUM", question: "Which European capital city sits on the River Vltava?", options: JSON.stringify(["Budapest","Vienna","Prague","Warsaw"]), correctAnswer: "Prague", funFact: "Prague sits on the Vltava, which flows through the city in a dramatic S-shape past the 14th-century Charles Bridge. The bridge has 16 statues and, according to legend, touching the bronze Saint John of Nepomuk brings good luck. Prague's castle is the largest ancient castle complex in the world." },
  { category: "Geography", difficulty: "HARD", question: "Which country has the most islands in the world?", options: JSON.stringify(["Indonesia","Philippines","Sweden","Norway"]), correctAnswer: "Sweden", funFact: "Sweden has around 267,570 islands, more than any other country, though most are small granite outcrops. Only about 30,000 are large enough to have a name. Despite this, roughly 90% of Swedes live in just the southern third of the country." },
  { category: "Geography", difficulty: "HARD", question: "Which two countries share the world's longest international border?", options: JSON.stringify(["Russia and China","Canada and the United States","Chile and Argentina","India and Bangladesh"]), correctAnswer: "Canada and the United States", funFact: "The Canada–US border runs 8,891 km, and includes Alaska — the border crosses itself so the US technically begins in the northern hemisphere. It is the longest undefended border in the world, with no soldiers or fortifications along its entire length. It has stayed unfortified by treaty since the 1818 Convention." },
  { category: "Technology", difficulty: "EASY", question: "What does 'VPN' stand for?", options: JSON.stringify(["Virtual Private Network","Visual Protocol Node","Very Public Network","Video Phone Network"]), correctAnswer: "Virtual Private Network", funFact: "A VPN encrypts your traffic and routes it through a server elsewhere, making it look like you're browsing from that country. It is genuinely useful for securing data on public Wi-Fi such as in coffee shops. However, a VPN shifts trust rather than removing it — the VPN provider can now see your traffic instead of your internet provider." },
  { category: "Technology", difficulty: "EASY", question: "What does 'PIN' stand for?", options: JSON.stringify(["Private Internet Number","Personal Identification Number","Password Input Number","Public Identification Name"]), correctAnswer: "Personal Identification Number", funFact: "The concept goes back to 1949, when inventors Almono Cohen patented an electromechanical code system for British telephone exchanges. PINs are only useful alongside a physical card — four digits alone can be brute-forced in seconds, which is why banks lock accounts after a handful of failed attempts." },
  { category: "Technology", difficulty: "MEDIUM", question: "What is 'open source' software?", options: JSON.stringify(["Software that is free to download","Software whose source code is publicly available to view and modify","Software released for a limited trial","Software that runs on any device"]), correctAnswer: "Software whose source code is publicly available to view and modify", funFact: "Open source is about the rights, not the price — the freedom to inspect, modify and redistribute the code. Linux, Firefox and the Apache web server are all open source, as is most of the internet's core infrastructure. The OSI definition was written in 1998 and has been updated several times since." },
  { category: "Technology", difficulty: "MEDIUM", question: "What does 'SSD' stand for?", options: JSON.stringify(["Super Storage Drive","Solid State Drive","Static System Disk","Sequential Sector Drive"]), correctAnswer: "Solid State Drive", funFact: "SSDs store data in flash memory with no moving parts, which is why they are far faster and more shock-resistant than hard drives. Random access is dramatically faster too — an SSD can read scattered files almost instantly, while a mechanical drive has to seek across spinning platters. That responsiveness is why booting a modern PC feels so much quicker." },
  { category: "Technology", difficulty: "MEDIUM", question: "What is a 'firewall'?", options: JSON.stringify(["A system that monitors and blocks network traffic","A backup copy of your files","A type of strong password","A physical lock for a server rack"]), correctAnswer: "A system that monitors and blocks network traffic", funFact: "Firewalls were invented in 1989 by Sally Floyd at Berkeley to protect the internet itself, not individual computers. Modern firewalls inspect packets far more deeply than early ones, and Next Generation Firewalls can even detect malicious apps rather than just known bad addresses. The first major denial-of-service attacks were launched precisely to overwhelm firewalls." },
  { category: "Technology", difficulty: "HARD", question: "What is machine learning?", options: JSON.stringify(["Training algorithms to improve from data instead of explicit rules","Teaching a computer to follow a fixed list of instructions","Using statistics to make predictions without a computer","A robot learning to walk by trial and error"]), correctAnswer: "Training algorithms to improve from data instead of explicit rules", funFact: "The term was coined by Arthur Samuel in 1959, describing a checkers program that got better simply by playing more games. Traditional programming needs humans to specify every rule; machine learning infers the rules from examples. It powers everything from spam filtering to image search, and it is why models now need enormous datasets." },
  { category: "Technology", difficulty: "HARD", question: "What is 'containerisation', as used by tools like Docker?", options: JSON.stringify(["Packaging software with its dependencies so it runs anywhere","Compressing an application to reduce download size","Splitting a large program into microservices","Encrypting a container image for shipping"]), correctAnswer: "Packaging software with its dependencies so it runs anywhere", funFact: "Docker popularised shipping an application together with everything it needs — libraries, config and runtime — into a single self-contained unit. That solved the 'it works on my machine' problem that long frustrated developers. Today essentially every major cloud platform runs container orchestration tools, and Kubernetes has become the standard scheduler for them." },
  { category: "Philippines", difficulty: "EASY", question: "What is the Filipino word for Christmas?", options: JSON.stringify(["Pasko","Araw","Tanghali","Bisperas"]), correctAnswer: "Pasko", funFact: "'Pasko' is shared with Spanish, and is a contraction of the Latin 'pascha' (Easter) — so Christmas and Easter share a name, as they do in much of Europe. Filipino Christmas is famously long, officially beginning in September with the 'ber'-month tradition, where the 'B' stands for Bethlehem,Buffers and Berries." },
  { category: "Philippines", difficulty: "EASY", question: "What is 'adobo'?", options: JSON.stringify(["A sweet rice pudding","Meat simmered in vinegar, soy sauce and spices","A steamed rice cake","A sour fish soup"]), correctAnswer: "Meat simmered in vinegar, soy sauce and spices", funFact: "Adobo is so quintessentially Filipino that it was almost included in the Dictionary of Filipino Proverbs and Sayings. The word itself comes from the Spanish 'adobado' ('seasoned' or 'marinated'). The dish's origins are widely disputed between the Chinese and Spanish, with a Chinese-Filipino version called 'adobo de chino' still very popular." },
  { category: "Philippines", difficulty: "EASY", question: "Which festival in Cebu, held every January, features elaborate street dancing and is dedicated to the Sto. Niño?", options: JSON.stringify(["Sinulog","Ati-Atihan","Pahiyas","Panunang"]), correctAnswer: "Sinulog", funFact: "Sinulog means 'to pay homage' in Cebuano, and it centres on the Santo Niño de Cebu. Ati-Atihan in Kalibo is the older Black Shaman festival that Sinulog is often said to be derived from. Participants dance under the midday sun, spinning polchlero headdresses that weigh several kilograms." },
  { category: "Philippines", difficulty: "MEDIUM", question: "What is the name of the Philippine government agency that issues weather forecasts and typhoon warnings?", options: JSON.stringify(["PAGASA","NASTI","DOST","Bureau of Fisheries"]), correctAnswer: "PAGASA", funFact: "PAGASA is the Philippine Atmospheric, Geophysical and Astronomical Services Administration, and the name is also the Tagalog word for 'speed' or 'rapidity'. It is one of the world's most typhoon-exposed countries, with around 20 tropical cyclones entering its area of responsibility each year. Its name was adopted in 1978, replacing the Weather Bureau." },
  { category: "Philippines", difficulty: "MEDIUM", question: "Which Philippine province is the country's leading producer of sugar?", options: JSON.stringify(["Negros Occidental","Ilocos Norte","Bicol","Zamboanga del Sur"]), correctAnswer: "Negros Occidental", funFact: "Negros Occidental grows roughly two-thirds of the Philippines' sugar, and its name — 'Black Island' — comes from volcanic soil that gives the crop a distinctive dark colour. A century of sugar shaped the island's economy and produced the hacienda system. It is also where the League of Filipino-American Nationals was founded in 1904, launching the Philippine independence movement." },
  { category: "Philippines", difficulty: "HARD", question: "Which Filipino ethnic group is famous for its intricate woven textiles and is among the country's largest indigenous communities?", options: JSON.stringify(["Igorot","Tausug","Aeta","Maranao"]), correctAnswer: "Igorot", funFact: "'Igorot' originally referred to the people of Baguio, from 'golot', meaning 'people of the mountains'. Today it loosely covers the many highland peoples of the Cordillera and Sierra Madre. Their weaving traditions are so respected that in 2009 the Ifugao and Kalinga designs were inscribed on the UNESCO Intangible Cultural Heritage list." },
  { category: "Philippines", difficulty: "HARD", question: "What is the name of the Spanish-era citadel in Manila's Intramuros district?", options: JSON.stringify(["Fort Santiago","Fort Siloso","Malacañang Palace","Fort Bonifacio"]), correctAnswer: "Fort Santiago", funFact: "Fort Santiago was built from the stones of a demolished Aztec/Rajo Tumatangui temple, with cannon salvaged from a shipwreck. The 'Museo de Filipinas' inside holds a collection of about 60,000 artefacts, though thousands were looted during World War II. Intramuros itself suffered a brutal 1945 battle in which an estimated 100,000 civilians died." },
  { category: "Food & Drinks", difficulty: "EASY", question: "What is the name of the Italian sauce made from basil, pine nuts, Parmesan and olive oil?", options: JSON.stringify(["Pesto","Ragù","Carbonara","Bolognese"]), correctAnswer: "Pesto", funFact: "Pesto hails from Genoa, where it is called 'salsa verde' (green sauce) and is traditionally made in a mortar with a wooden pestle — which is literally what 'pesto' means. Genoa's version is made without pine nuts, and uses a special basil grown in Pra', with a distinctive bitter, intensely green flavour." },
  { category: "Food & Drinks", difficulty: "EASY", question: "What is 'miso'?", options: JSON.stringify(["A Japanese fermented soybean paste","A Korean grilled beef dish","A type of pickled cabbage","A Chinese steamed bun"]), correctAnswer: "A Japanese fermented soybean paste", funFact: "Miso is made by fermenting soybeans with koji mould and salt, and there are well over 300 regional varieties. Red miso is aged longer and saltier, white miso is sweet and short-aged, and yellow sits between them. The word comes from 'miso' meaning 'to use up' or 'relish' — miso was the seasoning that made bland staples like rice and seaweed palatable." },
  { category: "Food & Drinks", difficulty: "EASY", question: "What is the general term for finely chopped raw vegetables, often served with tortilla chips?", options: JSON.stringify(["Salsa","Gazpacho","Relish","Tsatziki"]), correctAnswer: "Salsa", funFact: "Salsa simply means 'sauce' in Spanish, and the word covers a huge range of preparations — from Mexican pico de gallo to the smooth, cooked-and-seasoned salsas of the Andes. Modern salsa tracing began in the 1980s, and the term 'salsa' was registered in the United States in the 1960s for a particular style of sauce." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "What French method seals food in a bag and cooks it in a precisely controlled water bath?", options: JSON.stringify(["Sous vide","Braising","Flambe","Dehydration"]), correctAnswer: "Sous vide", funFact: "Sous vide is French for 'under vacuum', and the technique dates back to the 18th century, when French chef Massialot used it to make tender stews. It surged in popularity in the 2000s with the arrival of immersion circulators at affordable prices, championed by chefs such as Heston Blumenthal. Precision matters enormously — a degree or two can ruin the result." },
  { category: "Food & Drinks", difficulty: "MEDIUM", question: "What does 'al dente' mean when describing pasta?", options: JSON.stringify(["Cooked until completely soft","Cooked until firm but not hard","Served cold in a salad","Cooked without any sauce"]), correctAnswer: "Cooked until firm but not hard", funFact: "The Italian phrase means literally 'to the tooth'. Recommended timings vary by shape: dried spaghetti typically needs 8–10 minutes, while fresh egg pasta is only briefly boiled. The ideal bite still has a slight resistance at its centre, and noodles that sit after cooking turn mushy as their surface starch continues to absorb water." },
  { category: "Food & Drinks", difficulty: "HARD", question: "What is 'terroir'?", options: JSON.stringify(["The effect of local soil, climate and conditions on a food's flavour","The process of preserving food in vinegar","A style of cooking using only local ingredients","A device for measuring food temperature"]), correctAnswer: "The effect of local soil, climate and conditions on a food's flavour", funFact: "Terroir is a French term borrowed by wine, coffee, cheese and chocolate makers worldwide to describe how place shapes a product. French Roquefort must be aged in specific caves, and only within those caves. A grape grown in the same soil but 20 km away can taste noticeably different — which is why appellations like Champagne and Napa protect exact geography legally." },
  { category: "Food & Drinks", difficulty: "HARD", question: "What is the process of infusing alcohol with herbs, fruits or spices called?", options: JSON.stringify(["Maceration","Fermentation","Distillation","Caramelisation"]), correctAnswer: "Maceration", funFact: "Maceration has been used for millennia to make flavoured spirits, liqueurs, and perfume oils. The name comes from the Latin 'macerare', meaning 'to soak'. Lavender, vanilla, cinnamon and even tea can all be used, and the process is slower than simple mixing but produces a smoother, better-integrated flavour." },
  { category: "Filipino Pop Culture", difficulty: "EASY", question: "Which Filipino comic-book hero was created by Tony Velasquez in the 1960s?", options: JSON.stringify(["Vigilante","Superman","KWF","Bagong Kadipilan"]), correctAnswer: "Vigilante", funFact: "'Vigilante' first appeared in 1943 and Tony Velasquez revived and heavily reworked him in 1963, creating the country's first Filipino comic hero. A newspaper strike in the 1960s starved Filipino comics of imported US material, which is why local series such as 'KWF' and 'Bulaklak' flourished. The character returned in the 1980s as a vigilante who cleaned up corrupt politicians." },
  { category: "Filipino Pop Culture", difficulty: "EASY", question: "Which Filipino singer is famous for the song 'Batang Batong Ikaw'?", options: JSON.stringify(["Rico J. Puno","Martin Nievera","Freddie Aguilar","Don Henley"]), correctAnswer: "Martin Nievera", funFact: "Martin Nievera, known as the 'Master Showman' of Philippine entertainment, has released over 20 albums and hosted television shows for decades. 'Batang Batong Ikaw' became an enduring standard of Filipino love songs in 1981. His fans are known as 'Maries', short for 'Mariang Nawet'." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "What was the name of the hugely popular Philippine television musical anthology show of the 1970s that launched many stars?", options: JSON.stringify(["Vilma!","Maalaala Mo Kaya","That's Entertainment","Studio 23"]), correctAnswer: "Vilma!", funFact: "Vilma! aired on ABS-CBN from 1977 to 1986 and was the country's most watched variety show of its era. It became a launchpad for Sharon Cuneta, Nora Aunor, Pops Fernandez and many others, and featured the famous dancing trio Vilma, Larry and Amy. Its title came from Vilma Santos, the show's original host." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "What is the name of the Philippine independent film festival founded in 1974?", options: JSON.stringify(["Cinemalaya","Metro Manila Film Festival","Sinefest","SineMaya"]), correctAnswer: "Cinemalaya", funFact: "Cinemalaya — 'the cinema of love' — is the Philippines' largest and longest-running festival of independent film, and it helped launch the career of many acclaimed filmmakers. It is a leading member of the Asian Film Festival Network. Aby Sarwalla's 'Encounter' won its top prize there, and Lav Diaz's work has screened at Cannes partly because of the doors it opened." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "Which Filipino filmmaker directed the 1982 film 'Himala'?", options: JSON.stringify(["Ishmael Bernal","Lino Brocka","Mike de Leon","Kidlat Tahimik"]), correctAnswer: "Lino Brocka", funFact: "Lino Brocka directed 'Himala' (Miracle), which told the story of a rural Filipina alleged to have healing powers — a role made unforgettable by Sharon Cuneta. Brocka was one of Asia's most celebrated directors, and his death in 1985 was a shock across the region. He is a National Artist for Film and Broadcast Arts." },
  { category: "Filipino Pop Culture", difficulty: "MEDIUM", question: "What is the name of the popular Philippine low-cost airline known for no-frills domestic flights?", options: JSON.stringify(["Philippine Airlines","Cebu Pacific","PAL Express","AirAsia Philippines"]), correctAnswer: "Cebu Pacific", funFact: "Cebu Pacific revolutionised domestic travel by flying with bare-bones aircraft and charging very low fares, making flights affordable to ordinary families. It is now one of the world's largest low-cost carriers by passenger volume. It was founded in 1985 as an offshoot of the seafarer-training school of the PSB, and it lists its services in Filipino on board." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "Which Filipino composer wrote the orchestral work 'Maynila: Overture'?", options: JSON.stringify(["Lucio San Pedro","Francisco Santiago","Antonio Buenaventura","Juliang Bato"]), correctAnswer: "Francisco Santiago", funFact: "Francisco Santiago (1889–1947) wrote 'Maynila: Overture' in 1932, a rousing work celebrating the Philippine capital that opened the 1936 Independence Day celebration. He also composed 'Pilipinas Kong Mahal' and served as dean of the University of the Philippines College of Music. He was a pioneer of a distinctly Filipino national style of orchestral music." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "Which Filipino artist co-founded the Neo-Realist movement and is best known for 'Carnival' and 'Market Scene with a Vendor of Quail Eggs'?", options: JSON.stringify(["Vicente Manansala","Fernando Amorsolo","Carlos Francisco","Juan Luna"]), correctAnswer: "Vicente Manansala", funFact: "Vicente Manansala was a founder of the Filipino art movement known for its subjects drawn from everyday life and light. 'Carnival' (1936) shows the glitter of a marquee bulb one of his most celebrated works, and it was auctioned for millions of pesos. He was named a National Artist for Painting posthumously in 2012." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "Which Filipino poet wrote 'In Memory of My Feelings' and is known for championing free verse?", options: JSON.stringify(["Lualhati Bautista","José García Villa","Nick Joaquin","Cirilo Bautista"]), correctAnswer: "Lualhati Bautista", funFact: "Lualhati Bautista — the first Filipino National Artist for Literature — wrote 'In Memory of My Feelings' (1975), which is considered one of the great Filipino poems of the postwar era. The book explores the impact of the Marcos dictatorship on the individual, and the title poem became a kind of private anthem. She remained fiercely independent, and refused to join the 1976 protest movement to preserve her writing." },
  { category: "Filipino Pop Culture", difficulty: "HARD", question: "What was the name of the influential Philippine literary and political magazine founded in 1927?", options: JSON.stringify(["Philippine Free Press","Liwayway","Graphic","Bulaklak"]), correctAnswer: "Philippine Free Press", funFact: "The Philippine Free Press, founded by Lope K. Santos and S. P. Kalaw in 1927, was the most influential Filipino magazine of the 20th century and ran continuously for 89 years until 2016. It published the Noli Me Tangere and El Filiesterismo serially in its early years, and was a fierce critic of every Philippine president. It exposed political scandals and counted several future presidents among its writers." },
  { category: "Language & Words", difficulty: "EASY", question: "What is a 'portmanteau' word?", options: JSON.stringify(["A word that means the opposite of another","A word built by blending two others","A word that is very long","A word borrowed from Latin"]), correctAnswer: "A word built by blending two others", funFact: "Lewis Carroll coined the term from a Lewis Carroll character, a fictional beast that was part cat and part other creature. Modern portmanteaus are everywhere: 'brunch' from breakfast and lunch, 'smog' from smoke and fog, and 'malware' from malicious and software. They are especially common in a teenager's vocabulary, because they save effort." },
  { category: "Language & Words", difficulty: "EASY", question: "What is an 'oxymoron'?", options: JSON.stringify(["Two contradictory terms placed side by side","A very long sentence with no commas","A word repeated for emphasis","A phrase ending in a question"]), correctAnswer: "Two contradictory terms placed side by side", funFact: "Famous oxymorons include 'deafening silence', 'jumbo shrimp', 'terribly nice' and 'Holy Hand Grenade'. They work because they force the reader to hold two incompatible ideas at once, which often produces surprise or humour. Shakespeare used more than a thousand in his plays, and they've been a comedy staple ever since." },
  { category: "Language & Words", difficulty: "EASY", question: "What is a 'palindrome'?", options: JSON.stringify(["A word read the same forwards and backwards","A word with no vowel","A word with two syllables","A word borrowed from Greek"]), correctAnswer: "A word read the same forwards and backwards", funFact: "The word 'palindrome' comes from the Greek 'palindromos' — 'running back again'. The simplest is the single letter 'A', but 'racecar' and 'rotator' are the classic examples. The longest known palindromic word is 'saippuakivikauppias', a 19-letter Finnish word meaning a dealer in lye. There are entire palindrome sentences, such as 'A man, a plan, a canal: Panama'." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is a 'consonant cluster'?", options: JSON.stringify(["Two or more consonants pronounced together","Two vowels that sound identical","A consonant with no sound","A word with a silent letter"]), correctAnswer: "Two or more consonants pronounced together", funFact: "English allows remarkably long clusters at the start of words: 'strengths' has three, and 'tsunami' travels in English. This is why English pronunciation is largely unpredictable — one reason English has the world's largest number of non-native speakers. Other languages are stricter, and German, for instance, has a legal limit of three consecutive consonants in a word." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is a 'loanword'?", options: JSON.stringify(["A word invented for a brand","A word borrowed from another language","A word formed by adding a prefix","A word that has fallen out of use"]), correctAnswer: "A word borrowed from another language", funFact: "English is packed with loanwords — 'bazaar' from Persian, 'cafe' from Turkish, 'kangaroo' from an Aboriginal Australian language. English is also a major donor, giving other languages words such as 'weekend' and 'football'. A word can travel extraordinary distances: 'tea' came via Portuguese, from the Chinese 'te'." },
  { category: "Language & Words", difficulty: "MEDIUM", question: "What is a pidgin or creole language?", options: JSON.stringify(["A language that mixes the vocabulary of two languages","A language spoken only in written form","A language used for religious rituals","A language with a large number of loanwords"]), correctAnswer: "A language that mixes the vocabulary of two languages", funFact: "A pidgin arises when speakers of different languages need to communicate — Nigerian Pidgin English is spoken by over 100 million people. When a pidgin becomes the first language of a community, expanding its grammar and vocabulary, it is called a creole. Haitian Creole is arguably the clearest example: it became a country's official language, and the 1804 Haitian Declaration of Rights was written in it." },
  { category: "Language & Words", difficulty: "HARD", question: "What is a 'backronym'?", options: JSON.stringify(["A word reinterpreted to fit its own letters","A word made by joining the ends of two words","A phrase invented for advertising","A word with a silent first letter"]), correctAnswer: "A word reinterpreted to fit its own letters", funFact: "The classic example is 'SOS', originally chosen as a simple distress signal but later explained as 'Save Our Souls'. The modern sense dates from the 1960s, and the term itself is a backronym of 'back' plus 'acronym'. 'Posh' is a genuine example — it was a real word meaning 'aristocratic' long before it was turned into 'Pristine, Old-fashioned, Stylish, High-class'." },
  { category: "Language & Words", difficulty: "HARD", question: "What is a 'minimal pair'?", options: JSON.stringify(["Two words that differ in meaning but share a spelling","Two words that differ by only one sound","Two words of the same length","Two words borrowed from the same source"]), correctAnswer: "Two words that differ by only one sound", funFact: "Phonetics uses minimal pairs to show that two sounds are genuinely distinct: 'ship'/'sheep', 'bat'/'bad', 'full'/'fool'. If swapping the sound changed the word, the contrast proves the sound carries meaning. They also lie behind the accent puzzles — 'ship' and 'sheep' merged for many southern English speakers, which is why such jokes work in some dialects and not others." },
  { category: "Language & Words", difficulty: "HARD", question: "Which Greek root means 'love of wisdom' and gave us the word 'philosophy'?", options: JSON.stringify(["philo and sophia","logos and pathos","theos and nous","logos and sophia"]), correctAnswer: "philo and sophia", funFact: "'Philos' means love and 'sophia' means wisdom, so the very word 'philosophy' describes itself — a love of wisdom. The term was coined by Socrates' pupil Plato, who needed a word to separate the pursuit of truth from the mythological explanations that preceded it. This is also the root of 'philanthropy' (love of humanity) and 'phobia' (love of fear, oddly enough)." },
  { category: "Language & Words", difficulty: "HARD", question: "What is the study of rhythm, metre and the arrangement of words in poetry called?", options: JSON.stringify(["Semantics","Morphology","Prosody","Lexicography"]), correctAnswer: "Prosody", funFact: "Prosody is the technical analysis of how sounds behave in verse — syllable count, stress, rhyme and metre. It gives the iambic pentameter behind Shakespeare, and the Anglo-Saxon alliterative metre. Poets the world over, including Filipino practitioners, use prosodic devices like assonance and consonance to make lines memorable." },
  { category: "Economics & Business", difficulty: "EASY", question: "What is the central bank of the United States called?", options: JSON.stringify(["The Federal Reserve","The Treasury Department","The Securities Commission","The Federal Bank of America"]), correctAnswer: "The Federal Reserve", funFact: "The Federal Reserve, created in 1913, is unusual because it is not fully government-owned: member commercial banks hold its shares. It sets monetary policy, supervises banks, and provides payment services. Its independence is deliberately protected, though the Fed's balance sheet expanded enormously during the 2008 crisis and afterwards." },
  { category: "Economics & Business", difficulty: "EASY", question: "What does 'B2B' mean in business?", options: JSON.stringify(["Back to Back","Business to business","Business to buyer","Bank to bank"]), correctAnswer: "Business to business", funFact: "B2B describes a transaction between two companies rather than between a company and a consumer — which is known as B2C. Most economic activity is B2B, and such transactions are often worth far more individually. B2B and B2C also demand different sales approaches: B2B typically involves a handful of large contracts, B2C millions of small ones." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What is a company's 'liquidity'?", options: JSON.stringify(["The amount of debt a company owes","Its ability to pay short-term bills immediately","Its total annual profit","The cash it holds with no obligations"]), correctAnswer: "Its ability to pay short-term bills immediately", funFact: "A company can be highly profitable and still go bankrupt by running out of cash — that is what happened to several large firms in 2008. Liquidity is about the timing of cash flows, not net worth. The ratio of current assets to current liabilities is a common way to measure it." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What is the term for the buying and selling of company ownership shares?", options: JSON.stringify(["The bond market","The stock market","The money market","The futures market"]), correctAnswer: "The stock market", funFact: "Stock markets are among the oldest continuously operating institutions in the world: the Amsterdam Stock Exchange began trading in 1602, originally trading barrels of whale oil. Shares are often described as owning a slice of a company, though in practice what you mostly own is a contractual claim on its future dividends." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What is a period of significant decline in economic activity called?", options: JSON.stringify(["Inflation","Recession","Boom","Devaluation"]), correctAnswer: "Recession", funFact: "The standard technical definition is two consecutive quarters of falling real output, though many economists use a broader judgement-based one. Recessions are not rare: the US has had eight since 1990, and the Great Recession of 2007–2009 was the longest since the 1930s. Historically, recoveries have been remarkably uneventful, with growth returning within a year or two." },
  { category: "Economics & Business", difficulty: "MEDIUM", question: "What is the payment, calculated as a percentage of sales made, that an employee receives?", options: JSON.stringify(["A commission","A dividend","A bonus share","A rebate"]), correctAnswer: "A commission", funFact: "Commission-based pay aligns an employee's incentives with revenue, which is why it is standard in sales, insurance and advertising. A dividend is different — it is a share of profit paid to owners of the company, not workers. A rebate is money returned after a purchase, usually to encourage future sales." },
  { category: "Economics & Business", difficulty: "HARD", question: "What is 'opportunity cost'?", options: JSON.stringify(["The money spent on a purchase","The value of the next best alternative given up","The cost of an employee's salary","The fee charged for borrowing"]), correctAnswer: "The value of the next best alternative given up", funFact: "Opportunity cost is the most important idea in economics and the hardest to measure, because it never appears on an invoice. It explains why a farmer might grow flowers rather than vegetables, even when vegetables are more profitable in cash. It is also why leaving a well-paid job to start a business has a very real cost, whatever the balance sheet says." },
  { category: "Economics & Business", difficulty: "HARD", question: "What is 'predatory pricing'?", options: JSON.stringify(["Setting prices low to drive competitors out","Offering a small discount to loyal customers","Charging more abroad than at home","Reducing prices during a recession"]), correctAnswer: "Setting prices low to drive competitors out", funFact: "Predatory pricing is illegal in most jurisdictions, but proving it is hard: the company must be shown to be pricing below cost with the intent to eliminate rivals. Price wars between airlines and supermarkets have repeatedly raised exactly this question. The related concept of 'dumping' — selling abroad below domestic prices — is one of the most common trade disputes between countries." },
  { category: "Economics & Business", difficulty: "HARD", question: "What is a 'fiat currency'?", options: JSON.stringify(["Money backed by a commodity like gold","Money whose value rests on government decree and public trust","Currency only usable inside one country","Currency issued by a central bank alone"]), correctAnswer: "Money whose value rests on government decree and public trust", funFact: "'Fiat' is Latin for 'let it be done', and it describes money with value because a government says so rather than because of what backs it. The gold standard collapsed in the 1930s, and by 1971 every major currency had become fiat. Its stability therefore depends on confidence — a lesson the Zimbabwean and Venezuelan currencies demonstrated in the 2000s." },
  { category: "Board Games & Strategy", difficulty: "EASY", question: "In chess, what is it called when the king is directly under attack and must respond?", options: JSON.stringify(["Mate","Check","Threat","Attack"]), correctAnswer: "Check", funFact: "From the Persian 'shah', meaning 'king' — the word entered English via Persian into Spanish as 'jaque' and into English as 'check'. A player must respond to a check, and there are only three ways: move the king, block the attack, or capture the attacking piece. Failing to respond correctly is losing the game." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "In chess, what is it called when a player is in check and has no legal escape?", options: JSON.stringify(["Stalemate","Checkmate","Resignation","Draw"]), correctAnswer: "Checkmate", funFact: "Checkmate comes from the Persian 'shah mat', meaning 'the king is dead'. Stalemate is the trap for careless players: the king is not in check, but no legal move exists, and the game is drawn. In tournament play, players who blunder into stalemate immediately after winning a position are mocked for it." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "What is the goal in the board game Risk?", options: JSON.stringify(["Capture all 42 territories","Eliminate all opponents","Build the most cities","Control all 12 supply centres"]), correctAnswer: "Eliminate all opponents", funFact: "Risk, created in 1959 by Parker Brothers, is defined by its chaos — dice-driven battles mean almost nothing is fully in your control, and agreements are broken constantly. It has been repeatedly reissued in themed editions, including Star Wars, Lord of the Rings and Warhammer. The map has 42 territories, but eliminating everyone is the only way to win outright." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "Which modern board game is descended from the ancient Indian game Pachisi?", options: JSON.stringify(["Ludo","Backgammon","Chutes and Ladders","Carrom"]), correctAnswer: "Ludo", funFact: "Pachisi was described in detail in the 6th century and is often called the 'game of the twenty squares'. Ludo, invented in India and now enormously popular across South Asia, is its direct descendant — as are race games in Britain and America. The game is traditionally played with four players and is a fixture of family life across the subcontinent." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "In the board game Catan, what are the five resources players trade?", options: JSON.stringify(["Gold, silver, copper, iron and tin","Ore, brick, wool, wheat and lumber","Wood, stone, clay, glass and steel","Corn, wheat, soy, rice and barley"]), correctAnswer: "Ore, brick, wool, wheat and lumber", funFact: "Catan, released in 1995 by Klaus Teuber, is credited with helping modernise the board game industry and now has a worldwide competitive circuit. Its real genius is trading: it is rarely a good idea to build more than a couple of settlements because the numbers must be handed out. The first edition used hand-painted wooden pieces, one of which famously fell off the board in play-testing." },
  { category: "Board Games & Strategy", difficulty: "MEDIUM", question: "In chess, what is it called when a player offers up a piece to gain a larger advantage?", options: JSON.stringify(["A sacrifice","A blunder","A trade","A fork"]), correctAnswer: "A sacrifice", funFact: "Sacrifices are not mistakes but deliberate moves, and the most famous are the well-known 'Greek Gift' and 'Legal's mate'. A bishop sacrifice that opens a king's file, drawing the defending king out, has become an entire subgenre of chess tactics. Judging whether a sacrifice works requires deep calculation — a failed one is simply a blunder." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "What is the maximum number of players in the board game Diplomacy?", options: JSON.stringify(["2","4","6","7"]), correctAnswer: "7", funFact: "Diplomacy is usually described as the game where the most important piece is the pencil, because players must negotiate. As a zero-sum game it is mathematically unique: any two-player Diplomacy is a forced win for one player, so multi-player play is the only interesting form. Playtesting its negotiation system revealed a surprising flaw — a player who trusts everyone always loses, which stalled development until 1976." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "What is the name of the chess variant played on boards of up to 8×8×8?", options: JSON.stringify(["Three-dimensional chess","Space chess","Botanical chess","Cannon chess"]), correctAnswer: "Space chess", funFact: "Three-dimensional chess dates back at least to the 9th century, when it was played in the Arabian court of al-Adli. The modern space-bounded version was popularised in 1998 by Captain Rüdiger Schneider, who designed a 5×5×5 board when a cube wouldn't fit through a doorway. Rules are not standardised, which has kept it a curiosity rather than a competitive game." },
  { category: "Board Games & Strategy", difficulty: "HARD", question: "What is the term for when rival businesses secretly agree to fix prices to keep them high?", options: JSON.stringify(["A merger","A cartel","A monopoly","A syndicate"]), correctAnswer: "A cartel", funFact: "Cartels are agreements between competitors to eliminate competition — dividing markets, fixing prices or limiting output. They are generally illegal and notoriously hard to enforce, since the incentive to cheat is strong. They are also famously unstable: many collapse within a few years. The word was originally used for the Italian and Sicilian Mafia street gangs, which organised protection rackets and extortion." },
  { category: "Automotive", difficulty: "EASY", question: "What does 'RPM' stand for in car specifications?", options: JSON.stringify(["Revolutions per minute","Racing Power Management","Registered Power Meter","Road Pressure Measurement"]), correctAnswer: "Revolutions per minute", funFact: "RPM is how fast an engine's crankshaft turns, and power peaks at a particular range — typically 4,000–6,000 rpm in a petrol car. Redlining means holding the needle near the maximum, which for very short periods is fine. Doing it repeatedly can damage an engine, and it is a common way rental-car drivers accidentally cause expensive repairs." },
  { category: "Automotive", difficulty: "EASY", question: "What is the name of the device that electrically starts a car's engine?", options: JSON.stringify(["Starter motor","Alternator","Radiator","Flywheel"]), correctAnswer: "Starter motor", funFact: "The starter motor spins the engine fast enough to draw in a fuel-air mixture and get it going — the reason engines need a 'cranking' motion rather than a push. An alternator, by contrast, charges the battery while the engine runs. A faulty starter motor is one of the most common reasons a car fails to start, and is far cheaper to fix than an engine problem." },
  { category: "Automotive", difficulty: "MEDIUM", question: "What is a 'catalytic converter'?", options: JSON.stringify(["A device that converts harmful exhaust gases into safer ones","A filter that cleans the engine oil","A device that increases fuel injection","A compressor that powers the air conditioning"]), correctAnswer: "A device that converts harmful exhaust gases into safer ones", funFact: "A catalytic converter uses platinum, palladium and rhodium to turn carbon monoxide, nitrogen oxides and hydrocarbons into carbon dioxide, water and nitrogen. It was introduced in 1975 in the US, and globally one of the biggest single improvements to urban air quality. It needs lead-free fuel because lead physically coats and destroys the catalyst." },
  { category: "Automotive", difficulty: "MEDIUM", question: "What is a 'hybrid car'?", options: JSON.stringify(["A car powered only by electricity","A car combining an engine with an electric motor","A car with two identical engines","A car that runs on biodiesel"]), correctAnswer: "A car combining an engine with an electric motor", funFact: "Hybrids come in two flavours: series, where the electric motor does all the driving, and parallel, where both can. A 'plug-in hybrid' can be charged from the grid to give electric-only range, while a conventional hybrid is a battery that recharges from the engine. The Toyota Prius, launched in 1997, popularised the whole category." },
  { category: "Automotive", difficulty: "MEDIUM", question: "What is the name of the car safety system that helps prevent oversteer and skids?", options: JSON.stringify(["Anti-lock Braking System","Electronic Stability Control","Lane Departure Warning","Adaptive Cruise Control"]), correctAnswer: "Electronic Stability Control", funFact: "Electronic Stability Control (ESC) became mandatory on all new passenger cars in the US and Europe in the early 2010s. It uses sensors to detect a skid and brakes individual wheels to correct it, without the driver needing to react. The evidence for its value is strong — ESC is estimated to have saved thousands of lives per year in the EU alone." },
  { category: "Automotive", difficulty: "HARD", question: "What is 'brake fade'?", options: JSON.stringify(["A temporary loss of braking power after prolonged use","A noise produced when the pads wear","The effect of cold brakes on stopping distance","A type of suspension failure"]), correctAnswer: "A temporary loss of braking power after prolonged use", funFact: "Brake fade happens on long mountain descents when the brakes overheat, and the pedal still feels firm but the friction material no longer bites. It is why descent instructions stress using a lower gear rather than riding the brakes. Carbon or ceramic brakes resist fade far better than cast iron, which is why they are standard on sports cars and race cars." },
  { category: "Automotive", difficulty: "HARD", question: "What is a 'crumple zone'?", options: JSON.stringify(["A structure designed to absorb energy in a crash","A reinforced area that protects the engine","A compartment for the spare wheel","A panel that improves aerodynamics"]), correctAnswer: "A structure designed to absorb energy in a crash", funFact: "Crumple zones work on a simple principle: the crumpling metal is meant to deform and absorb kinetic energy so it never reaches the occupants. The practice became standard after Volvo researchers demonstrated in the 1960s that a survivable crash could be engineered. In a head-on collision, roughly 60% of a car's length may crumple, which is a sign the structure is working." },
  { category: "Automotive", difficulty: "HARD", question: "What is the name of the machine used to measure an engine's power output in a workshop?", options: JSON.stringify(["Dynamometer","Oscilloscope","Torque wrench","Exhaust analyser"]), correctAnswer: "Dynamometer", funFact: "A dynamometer, or 'dyno', holds the car in place while its wheels are spun against calibrated resistance. The figure quoted for a new car is usually a manufacturer's optimistic claim, and a well-used car rarely measures what its badge suggests. Dynos are also used to tune engine management, and to measure horsepower at the wheels rather than the crank." },
  { category: "Automotive", difficulty: "HARD", question: "Which layout places the engine behind the rear axle, as in many classic sports cars?", options: JSON.stringify(["Front-engine","Mid-engine","Rear-engine","Flat engine"]), correctAnswer: "Rear-engine", funFact: "A rear-engine layout places weight behind the driven wheels, giving outstanding traction and handling — the reason Volkswagen chose it for the original Beetle. Porsche has used it almost continuously since its founding in 1948. Mid-engine designs, with the engine behind the seats but ahead of the rear axle, became the norm for supercars, giving near-perfect weight distribution." },
  { category: "Nature & Plants", difficulty: "EASY", question: "What is the term for a plant that lives for two years?", options: JSON.stringify(["Annual","Biennial","Perennial","Evergreen"]), correctAnswer: "Biennial", funFact: "Annuals complete their whole life cycle in one year, biennials grow in the first year and flower in the second, and perennials live for many years. Biennials include carrots, beets and cabbages — which is why gardeners often sow them one year and harvest the next. Hollyhocks and foxgloves are classic garden biennials." },
  { category: "Nature & Plants", difficulty: "EASY", question: "What is the name of the tiny pores on the underside of leaves through which plants release water vapour?", options: JSON.stringify(["Veins","Stomata","Pores","Trichomes"]), correctAnswer: "Stomata", funFact: "The plural of stoma, from the Greek for 'mouth'. Stomata open to take in carbon dioxide and release oxygen and water vapour — a difficult trade-off, because opening them loses water. Plants therefore close them in the heat of the day, and CAM plants like cacti open theirs at night instead." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "What is 'germination'?", options: JSON.stringify(["The sprouting of a seed into a young plant","The pollination of a flower","The shedding of leaves in autumn","The greening of a plant"]), correctAnswer: "The sprouting of a seed into a young plant", funFact: "Germination needs three things: water, oxygen and the right temperature. Water is what breaks the seed's dormancy and activates enzymes stored in the endosperm. A remarkable example is the date palm: a 2,000-year-old seed from Masada germinated in 2005, and Judean date palms have since been replanted at the original site." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "What is the name of the transfer of pollen between plants?", options: JSON.stringify(["Germination","Photosynthesis","Pollination","Transpiration"]), correctAnswer: "Pollination", funFact: "Pollination comes in two forms: self-pollination, which guarantees a crop but reduces variety, and cross-pollination, which relies on wind, water or animals. Insects visiting flowers carry pollen on their bodies, deliberately planting sticky packages of food for them. Some orchids deliberately imitate female insects, so males attempt to mate with the flower and carry its pollen away." },
  { category: "Nature & Plants", difficulty: "MEDIUM", question: "Which family of plants includes pine, spruce and fir?", options: JSON.stringify(["Conifers","Ferns","Grasses","Mosses"]), correctAnswer: "Conifers", funFact: "Conifers are the only plants with cones rather than flowers, and they reproduce using naked seeds exposed to the wind — no fruit or protective wall. They dominate forests in cold climates because their needle-like leaves reduce water loss and their conical shape sheds snow. That makes them among the most commercially valuable trees on Earth, providing timber and paper." },
  { category: "Nature & Plants", difficulty: "HARD", question: "What is the name of the relationship where a fungus lives on or inside a tree and helps it absorb nutrients?", options: JSON.stringify(["Amensalism","Mycorrhizae","Parasitism","Commensalism"]), correctAnswer: "Mycorrhizae", funFact: "Fungal networks also do not do fungi a favour — in many species the fungus is entirely dependent on the tree for sugars, while the tree gains water and mineral nutrients. Fungi in the genus Mycorrhizae include some of the largest organisms measured: an Oregon specimen of Armillaria covered over 9 square kilometres and is estimated to be thousands of years old." },
  { category: "Nature & Plants", difficulty: "HARD", question: "What is 'allelopathy'?", options: JSON.stringify(["The use of chemicals released by a plant to suppress other plants","The growth of a plant in response to gravity","The inheritance of acquired traits","The spread of seeds by wind"]), correctAnswer: "The use of chemicals released by a plant to suppress other plants", funFact: "The name combines the Greek 'allelo', meaning 'other', and 'pathia', 'suffering'. Black walnut trees produce juglone, which famously kills or stunts anything planted near them, and this was exploited by farmers long before the science had a name. Eucalyptus, sagebrush and garlic all use the same chemical strategy." },
  { category: "Nature & Plants", difficulty: "HARD", question: "What is 'circadian rhythm' in plants?", options: JSON.stringify(["A plant opening and closing its flowers on a daily cycle","The rotation of a plant in response to light","The growth of a plant in response to wind","The annual cycle of leaf fall"]), correctAnswer: "A plant opening and closing its flowers on a daily cycle", funFact: "Circadian rhythms are roughly 24-hour cycles found in almost all living things, and in plants they govern the opening of flowers and the stomata. The evening primrose opens at dusk for its moth pollinators, exactly on schedule. The mechanism is internal and continues for days in total darkness, driven by a set of genes." },
  { category: "Nature & Plants", difficulty: "HARD", question: "What is the term for a plant that has adapted to grow permanently underwater?", options: JSON.stringify(["A xerophyte","A halophyte","A hydrophyte","A heliophyte"]), correctAnswer: "A hydrophyte", funFact: "Hydrophytes have solved the problems of living in water by shedding what land plants need. Their stems are thin and often hollow, their roots reduced, and their leaves finely divided to increase surface area. Seagrasses such as Posidonia are among the longest-lived organisms known, with some clones estimated to be over 100,000 years old." },
  { category: "Art & Literature", difficulty: "EASY", question: "What is the term for a painting done on wet plaster, which is how many cave paintings were made?", options: JSON.stringify(["Fresco","Watercolour","Tempera","Impasto"]), correctAnswer: "Fresco", funFact: "From the Italian 'fresco', meaning 'fresh'. Pigment is applied to wet plaster so the colour becomes part of the wall as it dries — meaning it cannot be corrected, and the work is in some sense permanent. The technique fell out of fashion in the 15th century, but artists have returned to it, including David Hockney." },
  { category: "Art & Literature", difficulty: "EASY", question: "Which art movement used bold, unnatural colours and loose brushwork to express emotion rather than realism?", options: JSON.stringify(["Fauvism","Minimalism","Neoclassicism","Rococo"]), correctAnswer: "Fauvism", funFact: "The name comes from the French 'fauves', meaning 'wild beasts' — after a critic's remark about a group's work at the 1905 Salon d'Automne. Led by Henri Matisse and André Derain, the movement used intense, non-naturalistic colour for its own sake. The word 'fauvism' has been extended as an insult in art criticism ever since." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "What is a 'vanishing point' in perspective drawing?", options: JSON.stringify(["A point where parallel lines appear to meet","The centre of the canvas","The point where light hits the subject","The far edge of the painting"]), correctAnswer: "A point where parallel lines appear to meet", funFact: "The vanishing point is the product of linear perspective, which was formalised in the early 15th century by the Italian architect Filippo Brunelleschi. Before it, medieval artists used a 'reverse' method that kept important figures at the same size regardless of distance. True perspective made naturalistic space possible, and the technique spread to oil painting and photography." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "What is the name of the dramatic technique where a character speaks their thoughts aloud to the audience?", options: JSON.stringify(["Soliloquy","Monologue","Aside","Overture"]), correctAnswer: "Soliloquy", funFact: "A soliloquy is speech delivered alone on stage, unheard by other characters — Shakespeare's 'To be or not to be' is the most famous example. A monologue is a long speech addressed to others, and an aside is a remark to the audience that characters onstage do not hear. Shakespeare used the device so heavily that it became a defining feature of English drama." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "What is the name of the technique of making a photograph by exposing film for a long time?", options: JSON.stringify(["Panning","Double exposure","Solarisation","Aperture priority"]), correctAnswer: "Panning", funFact: "Panning was pioneered as a way to suggest speed and motion, using a camera that follows the subject so it stays sharp while the background blurs. The effect became a staple of motorsport and street photography from the mid-20th century onward. It requires precise tracking of the subject, and a motorised tripod head or fast shutter is essential to keep it clean." },
  { category: "Art & Literature", difficulty: "MEDIUM", question: "Who was the English playwright who wrote 'Hamlet'?", options: JSON.stringify(["Christopher Marlowe","William Shakespeare","Ben Jonson","John Webster"]), correctAnswer: "William Shakespeare", funFact: "Hamlet, written around 1600, is Shakespeare's longest play and one of the most performed in the world. It is also the source of around 30 phrases still in everyday English, including 'to be or not to be' and 'the play's the thing'. The sole surviving early edition was printed in 1603, when Shakespeare's company was performing it during a plague closure." },
  { category: "Art & Literature", difficulty: "HARD", question: "What is a 'palimpsest' in art criticism?", options: JSON.stringify(["A page whose text was erased and overwritten","A painting of a single colour","A work that mixes several artistic styles","A portrait painted from memory"]), correctAnswer: "A page whose text was erased and overwritten", funFact: "The word originally described a reused manuscript page where the old text was scraped away but still faintly legible. Art historians have borrowed it to describe how artists build on or erase the past — a painting layered with hidden earlier versions. The technique means the earliest version survives, in effect, as a ghost." },
  { category: "Art & Literature", difficulty: "HARD", question: "Which novel is credited as the first to use the 'stream of consciousness' technique?", options: JSON.stringify(["Moby-Dick","Ulysses","Mrs Dalloway","Middlemarch"]), correctAnswer: "Ulysses", funFact: "Stream of consciousness captures the mind's scattered, non-linear flow, and James Joyce pushed it furthest in 'Ulysses' (1922), using invented linguistic experiments to render thought. Critics in the 1920s called the book 'obscene' and one burned it publicly. Its only printed edition initially bore 'for the strictest' on the title page to discourage the public." },
  { category: "Art & Literature", difficulty: "HARD", question: "Who wrote the novel 'Beloved'?", options: JSON.stringify(["Alice Walker","Toni Morrison","Maya Angelou","Zora Neale Hurston"]), correctAnswer: "Toni Morrison", funFact: "Toni Morrison's 'Beloved' (1987) follows a family haunted by slavery, and was inspired by the true story of Margaret Garner, who escaped slavery and killed her own daughter rather than see her returned. The novel won the 1988 Pulitzer Prize and is one of the most discussed works in American literature. Morrison also wrote 'The Bluest Eye' and 'Song of Solomon'." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What does 'GIF' stand for?", options: JSON.stringify(["Graphic Interchange Format","Graphics Image Function","Global Image File","General Internet Format"]), correctAnswer: "Graphic Interchange Format", funFact: "The name is deliberately a slight misnomer: a GIF is not really an interchange format, and 'GIF' is not an acronym at all. Created by CompuServe in 1987, it was the first widely supported animated image format and it remains one of the most-used formats on the web, despite being badly suited to photography." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What does 'ASAP' stand for?", options: JSON.stringify(["As Soon As Possible","As Soon As Practical","All Systems Are Pending","As Soon As Permitted"]), correctAnswer: "As Soon As Possible", funFact: "The phrase is first recorded in 1917 in American military correspondence, where 'as soon as practicable' was the formally preferred version. 'As soon as possible' is the modern popular form, and the two are used almost interchangeably today. It is one of a small set of abbreviations that have become ordinary English words." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "What is a 'bot' on social media?", options: JSON.stringify(["A program that automatically posts or replies","A human who posts very often","A verified account","A private group"]), correctAnswer: "A program that automatically posts or replies", funFact: "Bots predate social media: the first was a program called ELIZA running in 1966, chatting in an uncanny way that made users believe it understood them. Modern bots range from helpful service accounts to those buying fake followers and likes. Detecting them is an ongoing arms race, since operators adjust tactics whenever detection improves." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "What does 'phishing' refer to online?", options: JSON.stringify(["Fishing for real fish","Fooling people into revealing sensitive information","Slowing down a network","Encrypting a website"]), correctAnswer: "Fooling people into revealing sensitive information", funFact: "Phishing predates the internet entirely — the term was coined in 1996, referring to 'aerosniffing'. Today the most damaging variants are 'spear phishing', targeted at individuals, and 'voice phishing', using phone calls rather than email. The defining feature is urgency: a message demanding immediate action, which is designed to stop you thinking." },
  { category: "Internet & Memes", difficulty: "MEDIUM", question: "What is the name for a website that aggregates other people's links, like Reddit or a news portal?", options: JSON.stringify(["A search engine","A news aggregator","A wiki","A blog"]), correctAnswer: "A news aggregator", funFact: "Aggregators solved a real problem: the sheer volume of online sources. The first popular one, NewsBlur, launched in 2005. Today, aggregators powered by machine learning often dominate the traffic of the news sites they link to, which has reshaped how publishers get paid." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What is a 'zero-day' vulnerability?", options: JSON.stringify(["A flaw exploited before a patch exists","A flaw found by a researcher","A flaw in legacy systems","A flaw found at midnight"]), correctAnswer: "A flaw exploited before a patch exists", funFact: "The name refers to the zero days a developer has had to fix it — the attack happens before any patch is released. Zero-days are exceptionally valuable to attackers, so they are usually sold on underground markets for tens of thousands of dollars. Once a patch ships, the flaw becomes an 'N-day', and defence is much easier." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What is 'open web' (as in 'open web' versus 'deep web')?", options: JSON.stringify(["The internet as accessed through standard search engines","The part of the internet used for illegal activity","The part of the internet not indexed by search engines","The oldest part of the internet"]), correctAnswer: "The internet as accessed through standard search engines", funFact: "The 'deep web' is simply the internet not indexed by search engines — your inbox, banking portal, and any site behind a login. It is estimated to be 90–99% of all online content, and it is not the same as the 'dark web', which is a small, deliberately anonymised overlay. Much of the deep web is entirely mundane, such as subscription news sites and internal company pages." },
  { category: "Internet & Memes", difficulty: "HARD", question: "What is 'data harvesting'?", options: JSON.stringify(["Collecting large amounts of personal data without meaningful consent","Deleting old customer records","Compressing data for storage","Sharing data between government agencies"]), correctAnswer: "Collecting large amounts of personal data without meaningful consent", funFact: "Data harvesting covers everything from app trackers and browser fingerprinting to the sale of browsing histories. The Cambridge Analytica scandal in 2018 demonstrated how a single quiz could harvest the profiles of 87 million users, and it led directly to the GDPR in 2018. The irony the GDPR addresses is that users often consent to data collection they would never agree to if they understood it." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "Who is the Greek goddess of wisdom, weaving and strategic warfare?", options: JSON.stringify(["Aphrodite","Athena","Hera","Hestia"]), correctAnswer: "Athena", funFact: "Athena was born fully grown from the head of Zeus after he swallowed her mother Metis, and she is unusual among Greek gods for being both a warrior goddess and the patron of weaving and pottery. Her owl is still used as a symbol of wisdom, and Athens itself took its name from her. She was also credited with inventing the bridle and the first ship." },
  { category: "Philosophy & Mythology", difficulty: "EASY", question: "In Greek mythology, what creature has a human upper body and a horse's lower body?", options: JSON.stringify(["Minotaur","Centaur","Gryphon","Satyr"]), correctAnswer: "Centaur", funFact: "Centaurs were wild, drunken and quarrelsome, and lived in the forests of Thessaly. The most famous was Chiron, who was wise and civilised and taught many heroes including Achilles and Asclepius. Centaurs were also said to go wild at the smell of wine, which is how the hero Nessus was tricked into carrying Heracles across a river and lost his life to it." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "Which Greek philosopher is said to have lived in a barrel and asked for a lantern in daylight?", options: JSON.stringify(["Socrates","Plato","Diogenes","Zeno"]), correctAnswer: "Diogenes", funFact: "Diogenes of Sinope rejected all material possessions, and tradition says Alexander the Great once visited him and offered him anything he wanted. Diogenes replied that he only wished Alexander would stop blocking the sunlight. He is credited with coining the word 'cynic' after kynikos, 'dog-like' — a reference to living like a dog, without shame." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "Who wrote the 'Critique of Pure Reason'?", options: JSON.stringify(["David Hume","Immanuel Kant","Rene Descartes","Gottlob Frege"]), correctAnswer: "Immanuel Kant", funFact: "Kant set out to answer David Hume's scepticism, arguing that although we cannot know things as they are in themselves, the mind imposes structure on experience through concepts such as time, space and causality. He never left Königsberg in his life, and his habits were so regular that neighbours set their watches by the hour he passed them on his daily walk." },
  { category: "Philosophy & Mythology", difficulty: "MEDIUM", question: "Who is the Roman god of fire, metalworking and volcanoes?", options: JSON.stringify(["Mars","Vulcan","Mercury","Neptune"]), correctAnswer: "Vulcan", funFact: "Vulcan was believed to live beneath volcanic mountains and forge the thunderbolts of Jupiter, and the island of Vulcano in Italy gave its name to the word 'volcano'. He was married to Venus, and is usually depicted as a blacksmith at his anvil. The Romans built shrines to him at the foot of the Colosseum, where a famous bronze statue of him was kept." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "Which school of Indian philosophy teaches that the self (Atman) is identical to Brahman?", options: JSON.stringify(["Advaita Vedanta","Samkhya","Yoga","Vaishnavism"]), correctAnswer: "Advaita Vedanta", funFact: "Advaita, the 'non-dual' school taught by Shankara in the 8th century, argues that Brahman and Atman are ultimately the same reality, and that the sense of a separate, limited self is an illusion called maya. Shankara's arguments are built on the Upanishads, foundational texts of Indian thought that were transmitted orally for centuries. Advaita travelled west in the late 19th century and became a significant influence on Transcendentalist and later Western mystical writers." },
  { category: "Philosophy & Mythology", difficulty: "HARD", question: "In Greek mythology, which hero defeated the many-headed Hydra?", options: JSON.stringify(["Theseus","Heracles","Perseus","Jason"]), correctAnswer: "Heracles", funFact: "Heracles could not defeat the Hydra by cutting off its heads, as two grew back for each one severed — so he asked his nephew Iolaus to cauterise the stumps with fire. The Hydra's poisonous blood was so potent it poisoned the arrows used to kill Heracles himself, which his son Telephus later used against his father. Heracles' twelve labours began with killing the Nemean Lion." },
  { category: "Space & Astronomy", difficulty: "EASY", question: "How many moons does Mars have?", options: JSON.stringify(["One","Two","Four","None"]), correctAnswer: "Two", funFact: "Mars' moons Phobos and Deimos are named after characters from Homer's 'Iliad' — the horses of Ares, the god of war. Phobos is slowly spiralling inward and will crash into Mars in roughly 50 million years, becoming a ring. Deimos is so small it would appear as a bright star from the Martian surface." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "In astronomy, what is a 'transit'?", options: JSON.stringify(["A planet passing across the face of its star","Two stars passing behind each other","A comet losing its tail","A satellite leaving orbit"]), correctAnswer: "A planet passing across the face of its star", funFact: "Transits are one of the main ways astronomers search for exoplanets — when a planet crosses its star, the starlight dips by a tiny but measurable amount. The transits of Venus in the 18th century were used to measure the distance from Earth to the Sun, a figure astronomers had needed for over a century to work out the true scale of the solar system." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "What is the name of the rocky band of debris orbiting between Mars and Jupiter?", options: JSON.stringify(["The asteroid belt","The Kuiper Belt","The Oort Cloud","The Lagrange Belt"]), correctAnswer: "The asteroid belt", funFact: "The belt is vast but the asteroids within it are widely spaced — spacecraft pass through without any risk of a collision. Ceres, the largest object in it, was reclassified as a dwarf planet in 2006 and holds about a third of the belt's total mass. Scientists believe it is the leftover debris from a planet that never fully formed." },
  { category: "Space & Astronomy", difficulty: "MEDIUM", question: "Why does a comet develop a tail as it approaches the Sun?", options: JSON.stringify(["The Sun's heat and wind strip material from its nucleus","Its frozen gases melt into liquid","The pull of Jupiter draws out the tail","Its rotation flings ice into space"]), correctAnswer: "The Sun's heat and wind strip material from its nucleus", funFact: "A comet's tail always points away from the Sun, regardless of which way the comet is travelling. The glowing part is a coma of gas around the solid nucleus, and the tail is dust and ionised gas driven off by solar wind. Comet Halley, which returns every 76 years, was the subject of the first scientific prediction of a comet's return." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is a 'quasar'?", options: JSON.stringify(["An extremely luminous active galactic nucleus powered by a black hole","A young star still forming from gas","A pair of stars orbiting each other","A distant galaxy seen edge-on"]), correctAnswer: "An extremely luminous active galactic nucleus powered by a black hole", funFact: "Quasars can outshine an entire galaxy — a hundred billion Suns — from a region smaller than our solar system. They are powered by matter falling into a supermassive black hole and heating to millions of degrees. Because they are so bright, quasars act as beacons: measuring how their light is stretched tells us how fast the universe is expanding." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is the name of the technique for measuring the distance to a nearby star by observing how far it appears to shift against distant background stars?", options: JSON.stringify(["Parallax","Aberration","Occultation","Redshift"]), correctAnswer: "Parallax", funFact: "Parallax is the reason a person sitting still sees their thumb apparently move against the background when they close one eye. Hold your thumb up at arm's length, close one eye, then switch — your thumb seems to jump. Copernicus used the same idea to argue the Earth orbits the Sun, though stellar parallax was not actually measured until Bessel in 1838." },
  { category: "Space & Astronomy", difficulty: "HARD", question: "What is a 'white dwarf'?", options: JSON.stringify(["A dense, cooling remnant of a low-mass star","A small star still fusing hydrogen","A collapsed star spinning rapidly","A young star surrounded by a disc"]), correctAnswer: "A dense, cooling remnant of a low-mass star", funFact: "When a star like the Sun runs out of fuel it sheds its outer layers and leaves a white dwarf — an Earth-sized ball with roughly the Sun's mass, so dense that a teaspoon would weigh a tonne. Sirius B, the nearest white dwarf to Earth, is about as massive as the Sun but only twice its size. Over billions of years a white dwarf will cool and fade into a black dwarf, though the universe is not yet old enough for any to have formed." },
  { category: "Gaming", difficulty: "EASY", question: "What does 'NPC' stand for in gaming?", options: JSON.stringify(["New Player Character","Non-player character","Non-Player Class","Network Play Connection"]), correctAnswer: "Non-player character", funFact: "NPCs are characters controlled by the game's code rather than a player, and they fill the world: shopkeepers, enemies and shopkeepers' dialogue. In older games they were on fixed scripts, so towns felt strangely repetitive — the classic 'NPC problem'. Modern AI and quest systems have made them far more responsive to the player's actions." },
  { category: "Gaming", difficulty: "EASY", question: "Which company developed the 'Half-Life' series?", options: JSON.stringify(["Valve","Epic Games","id Software","Capcom"]), correctAnswer: "Valve", funFact: "Valve released 'Half-Life' in 1998, and unusually the game shipped without a single line of cut content — no story cutscenes, no levels removed. The technique of scripting scenes as trigger volumes rather than as separate cinematics let players keep control, and it is a direct ancestor of modern immersive storytelling. Valve also created Steam, which became the dominant PC game store." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which company makes the 'Xbox' console series?", options: JSON.stringify(["Sony","Microsoft","Nintendo","Sega"]), correctAnswer: "Microsoft", funFact: "The Xbox launched in 2001 and was initially a costly failure for Microsoft, but it established the console industry as a serious competitor. The modern Xbox Game Pass subscription is widely credited with changing how people buy and play games, offering hundreds of titles for a monthly fee. The Xbox Series X and S, released in 2020, are the current generation." },
  { category: "Gaming", difficulty: "MEDIUM", question: "What is 'emergent gameplay'?", options: JSON.stringify(["Behaviour that arises from systems interacting rather than being scripted","A bug that breaks the game's rules","Difficulty that changes with player skill","Content unlocked by player progress"]), correctAnswer: "Behaviour that arises from systems interacting rather than being scripted", funFact: "Emergent gameplay happens when a game's systems combine in ways its designers did not specifically write. The 1980 game 'Rogue' produced countless stories because it generated a new dungeon layout on every attempt, so players regularly achieved absurd fates — dying on the first level, or escaping a dungeon by descending the stairs of a building. Designers now talk about a game's 'possibility space' rather than just its features." },
  { category: "Gaming", difficulty: "MEDIUM", question: "Which programming language is primarily used to script gameplay in the Unity engine?", options: JSON.stringify(["C#","JavaScript","Lua","Swift"]), correctAnswer: "C#", funFact: "Unity, first released in 2005, became the engine behind an enormous share of independent mobile games, and also underpins games from some of the biggest studios. Its scripting language is C#, which also makes it easier to move between Unity projects and other C# ecosystems. Unity's major rival is Unreal Engine, which historically favoured C++." },
  { category: "Gaming", difficulty: "HARD", question: "What is 'procedural generation'?", options: JSON.stringify(["Creating game content algorithmically rather than by hand","Compressing game files to save space","Generating the game's source code","Rendering graphics procedurally"]), correctAnswer: "Creating game content algorithmically rather than by hand", funFact: "Procedural generation is how No Man's Sky built an entire universe of 18 quintillion planets from a set of rules, and how Minecraft generates terrain from a small seed. It is also used for dungeons in Diablo and Hogwarts Legacy, and for vegetation. The appeal to developers is that it produces vast content from relatively little human effort." },
  { category: "Gaming", difficulty: "HARD", question: "What is a 'speedrun'?", options: JSON.stringify(["Completing a game as quickly as possible","Playing only the easiest levels","A multiplayer mode with no rules","A gaming marathon"]), correctAnswer: "Completing a game as quickly as possible", funFact: "Speedrunning became a recognised competitive discipline in the 2000s, with annual events drawing hundreds of thousands of viewers online. The Super Mario Bros. category is the most famous, and sub-five-minute completions are now routine at the top level. The community is also notable for reverse-engineering game mechanics to find unintended shortcuts, called 'glitches', that are faster than anything the developers intended." },
  { category: "Internet & Memes", difficulty: "EASY", question: "What does 'HTTP' stand for?", options: JSON.stringify(["HyperText Transfer Protocol","High Transfer Text Protocol","Hyperlink Text Transfer Program","Host Transfer Text Protocol"]), correctAnswer: "HyperText Transfer Protocol", funFact: "HTTP is the protocol a browser uses to request pages from a web server, and it is the foundation of the modern web, along with URLs that identify the resources being requested. Tim Berners-Lee wrote the first version at CERN in 1989, and the first web page is still online at info.cern.ch. Version 1.0 was documented in 1991, and HTTPS, the encrypted version, has been the default since the 2010s." },
  { category: "World Wonders", difficulty: "EASY", question: "Which of the Seven Wonders of the Ancient World was a giant bronze statue of the sun god Helios?", options: JSON.stringify(["The Colossus of Rhodes","The Lighthouse of Alexandria","The Mausoleum at Halicarnassus","The Temple of Artemis"]), correctAnswer: "The Colossus of Rhodes", funFact: "The Colossus stood beside the harbour of Rhodes and was around 33 metres tall, roughly the height of a ten-storey building. It was completed in 280 BC and toppled by an earthquake only 54 years later. Because it lay in ruins for centuries, no detailed description survives, and coins minted at the time give the best idea of what it looked like." },
  { category: "World Wonders", difficulty: "EASY", question: "Which of the Seven Wonders was a walled city with towers, battlements and walls faced in glazed blue brick?", options: JSON.stringify(["The walls of Babylon","The Hanging Gardens of Babylon","The Colossus of Rhodes","The Lighthouse of Alexandria"]), correctAnswer: "The walls of Babylon", funFact: "The walls of Babylon were built under King Nebuchadnezzar II in the 6th century BC, and the Greek historian Herodotus described them as so tall that two chariots could pass abreast on top. A section was excavated in the 19th century and is now displayed in Berlin, complete with its original glazed-brick lions. The city lay in Babylonia, in modern-day Iraq." },
  { category: "World Wonders", difficulty: "EASY", question: "Which of the Seven Wonders was a tall stone lighthouse built by the Ptolemies on the coast of Egypt?", options: JSON.stringify(["The Lighthouse of Alexandria","The Colossus of Rhodes","The Statue of Zeus at Olympia","The Library of Pergamum"]), correctAnswer: "The Lighthouse of Alexandria", funFact: "The lighthouse stood on the island of Pharos, which is where the word pharos, still used for a lighthouse in several languages, comes from. It stood perhaps 100 to 120 metres tall and was topped by a fire that guided ships at night. It remained the tallest man-made structure in the world for roughly 1,600 years, until the spire of Lincoln Cathedral in England overtook it." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which of the Seven Wonders was a huge temple of Artemis at Ephesus, on the coast of modern Turkey?", options: JSON.stringify(["The Temple of Artemis","The Temple of Diana at Ephesus","The Tomb of Mausolus","The Temple of Zeus"]), correctAnswer: "The Temple of Artemis", funFact: "The temple at Ephesus was rebuilt several times on the same site over centuries, and one rebuilding was largely funded by Amastris, queen of Pontus. Its columns stood 18 metres tall and were carved with sculpted figures, and the temple was said to house one of the Seven Wonders of the World in its own right, a solid gold statue of Artemis. It was destroyed by arson in 356 BC, the same year Alexander the Great was born." },
  { category: "World Wonders", difficulty: "MEDIUM", question: "Which of the Seven Wonders was a huge tomb for King Mausolus that gave us the word 'mausoleum'?", options: JSON.stringify(["The Mausoleum at Halicarnassus","The Temple of Artemis","The walls of Babylon","The Statue of Zeus at Olympia"]), correctAnswer: "The Mausoleum at Halicarnassus", funFact: "Mausolus was a satrap of Caria in the 4th century BC, and his wife and sister Artemisia II had the tomb built for him in Halicarnassus, in modern-day Turkey. It stood on a raised platform with a pyramid-shaped roof and columns around the base, and became so famous that mausoleum now means any large and imposing tomb. It was badly damaged by a 15th-century earthquake, and its stones were reused for a Venetian fortress." },
  { category: "World Wonders", difficulty: "HARD", question: "Which of the Seven Wonders was a library and research centre at Pergamon in modern Turkey, second in importance only to the library of Alexandria?", options: JSON.stringify(["The Library of Pergamum","The Library of Alexandria","The Temple of Artemis","The Colossus of Rhodes"]), correctAnswer: "The Library of Pergamum", funFact: "The library is thought to have held between 200,000 and 700,000 scrolls. Pergamon became famous for a writing material that bears its name, parchment, and it is said the rival Alexandrian library was starved of papyrus deliberately so that people would come to Pergamon instead. The last king of Pergamon, Attalus III, bequeathed his kingdom to Rome rather than pass it to an heir." },
  { category: "World Wonders", difficulty: "HARD", question: "Which of the Seven Wonders was an enormous seated statue of Zeus in the valley of Olympia?", options: JSON.stringify(["The Statue of Zeus at Olympia","The Statue of Zeus at Pergamon","The Colossus of Rhodes","The Temple of Artemis"]), correctAnswer: "The Statue of Zeus at Olympia", funFact: "The statue was made by Phidias in the 5th century BC and stood roughly 12 metres tall, seated, carved from ivory with a mantle of gold. It stood in the most important sanctuary of the ancient Greek world. A colossal gilded bronze copy was later installed in Rome, and both statues were eventually carried off to Constantinople." },
  { category: "Pop Culture", difficulty: "EASY", question: "What is the annual celebration on 31 October, known for costumes, trick-or-treating and carved pumpkins?", options: JSON.stringify(["Halloween","Thanksgiving","Valentine's Day","Easter"]), correctAnswer: "Halloween", funFact: "Halloween traces back to the ancient Celtic Samhain festival, marking the end of the harvest and the start of the dark half of the year, when the dead were said to walk. All Hallows' Eve gives the modern name. The pumpkin tradition is comparatively recent, because pumpkins only became widely available in Ireland and America after they displaced turnips." },
  { category: "Pop Culture", difficulty: "EASY", question: "Which American soft drink company ran the 'Share a Coke' campaign that printed popular first names on its bottles?", options: JSON.stringify(["Coca-Cola","Pepsi","Dr Pepper","Sprite"]), correctAnswer: "Coca-Cola", funFact: "The campaign began in Australia in 2011 and spread worldwide, and research found that people were noticeably more likely to pick up a bottle with their own name on it. The company adapted the list for each market, which occasionally backfired: in Australia the name Tobag was read as an insult and those bottles were quietly withdrawn from sale." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "In 'The Hunger Games', what is the name of the fictional nation in which the story is set?", options: JSON.stringify(["Panem","Westeros","Narnia","Gondor"]), correctAnswer: "Panem", funFact: "Panem is described as an inspiration for the United States, and the title refers to an annual televised event in which children from each district are sent into an arena to fight to the death. The series is by Suzanne Collins, whose earlier children's series Underland Chronicles drew openly on the Greek myth of Theseus and the Minotaur. The first book was published in 2008." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "What is the name of the practice of dressing in costume as a character and attending conventions?", options: JSON.stringify(["Cosplay","Character dress","Convention wear","Role dress"]), correctAnswer: "Cosplay", funFact: "Cosplay is a portmanteau of costume play, and the practice is closely tied to the way Japanese fans dress as characters at manga and anime events. The first known English-language use dates to 1966, at the first science fiction convention in London. The first World Cosplay Summit was held in Japan in 1995, and it now draws competitors from dozens of countries." },
  { category: "Pop Culture", difficulty: "MEDIUM", question: "What is the name of the fictional African nation in which the 'Black Panther' films are set?", options: JSON.stringify(["Wakanda","Zamunda","Latveria","Genosha"]), correctAnswer: "Wakanda", funFact: "Wakanda was created in 1966 by Jack Kirby and Stan Lee, and the character's origin drew on real African kingdoms and cultures. He has had a complicated history: he began as a villain in 1966, was recast as a hero in the 1970s, and now leads an advanced, isolated African nation. The 2018 film was the first superhero film ever to win the Academy Award for Best Production Design." },
  { category: "Pop Culture", difficulty: "HARD", question: "Which toy line, launched in 1973, featured dolls with large heads, small bodies and changeable outfits, and became the best-selling toy of all time?", options: JSON.stringify(["Barbie","Cabbage Patch Kids","My Little Pony","Bratz"]), correctAnswer: "Barbie", funFact: "Barbie was created by Ruth Handler, who noticed that her daughter Barbara preferred playing with paper dolls to baby dolls, and named the doll after her. By 2000 more than eight dolls were being sold every second somewhere in the world. In 2023 a human-sized Barbie was displayed in the window of Selfridges in London, and had to be watched over by a security team." },
  { category: "Pop Culture", difficulty: "HARD", question: "What was the name of the first commercially successful instant noodle product, launched in Japan in 1958?", options: JSON.stringify(["Instant noodles","Instant spaghetti","Quick noodles","Cup noodles"]), correctAnswer: "Instant noodles", funFact: "Nissin founder Momofuku Ando is said to have been inspired to invent instant noodles after leaving a basket of boiled noodles to cool in cold water and finding them still perfectly edible. The original flavours were the three classics: chicken, beef and shrimp. The cup format followed in 1971, and Nissin's cup noodle factory is now a permanent exhibition at Japan's National Museum of Science and Technology." },
  { category: "Sports", difficulty: "EASY", question: "In which sport would a player attempt to land a slam dunk?", options: JSON.stringify(["Basketball","Baseball","Volleyball","Tennis"]), correctAnswer: "Basketball", funFact: "The slam dunk was banned in the NBA in the late 1960s, reinstated, and then banned again from 1971 to 1973, because the league feared it undermined the point of the game. The 1991 NBA Slam Dunk Contest is remembered for Dominique Wilkins soaring over a standing Larry Johnson, and the most famous contest of all is the 1988 one, won by Michael Jordan." },
  { category: "Sports", difficulty: "EASY", question: "Which sport is played with a shuttlecock over a net 1.98 metres high?", options: JSON.stringify(["Badminton","Table tennis","Tennis","Volleyball"]), correctAnswer: "Badminton", funFact: "Badminton takes its name from Badminton House in Gloucestershire, England, where the game was first played in the 1870s. It is the fastest ball sport in the world, with smash speeds over 400 km/h recorded in controlled conditions. It has been an Olympic sport since 1992, and the shuttle is made from feathers, or from feathers and cork." },
  { category: "Sports", difficulty: "EASY", question: "Which country is the traditional dominant power in table tennis?", options: JSON.stringify(["China","Sweden","Germany","South Korea"]), correctAnswer: "China", funFact: "China has won the bulk of table tennis titles at every Olympic Games since the sport was introduced, and the sport is effectively a national institution there. Chinese players have dominated so completely that in the early 2000s the country's governing body briefly proposed limiting which players could compete abroad, to stop other nations adopting their techniques. The ball was also changed from celluloid to plastic in 2000, giving the modern game its characteristic bounce." },
  { category: "Sports", difficulty: "MEDIUM", question: "In tennis, how many games does a player need to win to take a set, unless it is decided by a tie-break?", options: JSON.stringify(["Four games","Five games","Six games","Seven games"]), correctAnswer: "Six games", funFact: "A set is normally the first to six games with a two-game margin, so the possible scores are 6-0, 6-1, 6-2, 6-3 or 6-4. At 6-6 most sets are settled by a tie-break, a single game played to seven points, though the deciding set in the men's game at Grand Slams and the Olympics is played as a full set instead." },
  { category: "Sports", difficulty: "MEDIUM", question: "Which country hosted the 2016 Summer Olympics?", options: JSON.stringify(["Brazil","Japan","China","United Kingdom"]), correctAnswer: "Brazil", funFact: "Rio de Janeiro hosted the 2016 Games and had bid for them five times, and Brazil remains the only South American country to have staged a Summer Olympics. The Games are remembered for Usain Bolt winning both the 100 m and 200 m, for cricket returning to the programme for the first time since 1900, and for Fiji winning its first ever Olympic gold in men's rugby sevens." },
  { category: "Sports", difficulty: "HARD", question: "Which Grand Slam tennis tournament is the only one still played on grass?", options: JSON.stringify(["Wimbledon","Australian Open","French Open","US Open"]), correctAnswer: "Wimbledon", funFact: "Wimbledon, played at the All England Club in London, is the oldest tennis tournament in the world and the only one of the four still played on grass. The grass is cut to exactly 8 mm and the courts are relaid throughout the tournament. The all-white dress code is the last of its kind in the sport." },
  { category: "Sports", difficulty: "HARD", question: "Which football player has won the most Ballon d'Or awards?", options: JSON.stringify(["Lionel Messi","Cristiano Ronaldo","Neymar","Zinedine Zidane"]), correctAnswer: "Lionel Messi", funFact: "Messi has won the Ballon d'Or a record eight times, in 2009, 2010, 2011, 2012, 2015, 2019, 2021 and 2023, and he also holds the record for most goals for a club in a calendar year, with 91 in 2012. In 2022 he finally won the World Cup, completing the set of major trophies. He grew up in Rosario, Argentina, and joined Barcelona's youth academy at the age of 13." },
  { category: "Logic", difficulty: "EASY", question: "A man looks at a photograph and says: brothers and sisters I have none, but that man's father is my father's son. Who is in the photograph?", options: JSON.stringify(["His son","His father","His brother","Himself"]), correctAnswer: "His son", funFact: "If the man has no siblings, then my father's son must be the man himself. So the sentence reduces to that man's father is me, meaning the man in the photograph is his own father. This is one of the oldest and trickiest puzzles in recreational logic, and it has appeared in puzzle books since at least the 19th century." },
  { category: "Logic", difficulty: "EASY", question: "In a race you overtake the person in second place. What position are you now in?", options: JSON.stringify(["First","Second","Third","Unchanged"]), correctAnswer: "Second", funFact: "Overtaking the person in second place means you were behind them, so taking their position puts you in second. The puzzle is a test of whether you think carefully rather than answering first out of habit. A harder version asks what happens if you overtake the person in last place, which is impossible." },
  { category: "Logic", difficulty: "MEDIUM", question: "A man pushes his car to the top of a hill and then walks back down. What happens to the hill?", options: JSON.stringify(["It gets steeper","It gets shallower","It stays exactly the same","It gets longer"]), correctAnswer: "It stays exactly the same", funFact: "The hill does not change shape at all, but it appears to get shallower because the man is now looking at it from a different position and angle. Gravity is unchanged, and objects still roll downhill. The puzzle is a simple demonstration that a person's viewpoint, not the world, is what shifted." },
  { category: "Logic", difficulty: "MEDIUM", question: "If it is Monday morning, what day of the week will it be 50 hours later?", options: JSON.stringify(["Tuesday","Wednesday","Thursday","Friday"]), correctAnswer: "Wednesday", funFact: "Fifty hours is two days and two hours, so two days after Monday is Wednesday, plus a couple of hours that do not change the day. The puzzle tests whether you can handle a remainder that does not complete a full day, and it is a favourite of aptitude tests for the same reason. The answer is Wednesday, not Tuesday, no matter how many hours you picture." },
  { category: "Logic", difficulty: "MEDIUM", question: "A bat and a ball cost 1.10 in total. The bat costs 1.00 more than the ball. How much does the ball cost?", options: JSON.stringify(["0.10","0.05","0.01","0.20"]), correctAnswer: "0.05", funFact: "Most people answer 0.10 by subtracting one dollar from 1.10 and stopping, but that makes the bat cost 1.00 more than the ball only if the ball is 0.05. The answer follows from the fact that the difference between the two prices must be exactly 1.00, so with a total of 1.10 the ball must be five cents and the bat 1.05. It is one of the most reliable examples of a question that feels obvious and is not." },
  { category: "Logic", difficulty: "HARD", question: "You have three boxes, one containing only apples, one only oranges, and one mixed fruit. Every label is wrong. What is the minimum number of fruits you must draw to identify all three boxes?", options: JSON.stringify(["1","2","3","6"]), correctAnswer: "1", funFact: "One fruit is enough. Draw a single fruit from the box labelled mixed. Because every label is wrong, that box cannot be mixed, so the label tells you exactly which pure category is inside it. The other two labels are then forced: the box labelled with that fruit must be the mixed one, and the remaining box is the other pure fruit. Two draws, the intuitive answer, gives no extra information." },
  { category: "Logic", difficulty: "HARD", question: "You have 8 balls that all look identical, but one is slightly heavier. Using a balance scale, what is the minimum number of weighings needed to guarantee finding it?", options: JSON.stringify(["1","2","3","4"]), correctAnswer: "3", funFact: "Three weighings are enough, and also necessary. Split the balls into groups of 3, 3 and 2, then weigh the two groups of three against each other to narrow the search to one group of three. One weighing settles that group, and one more settles the final pair. The general rule is that a balance scale gives three possible results, so n weighings can distinguish at most 3 to the n balls, which is why 8 works in 3 weighings but 9 does not." },
  { category: "Movies", difficulty: "EASY", question: "Which sci-fi film franchise features the character Ellen Ripley fighting xenomorphs on a spaceship?", options: JSON.stringify(["Alien","Predator","Starship Troopers","The Thing"]), correctAnswer: "Alien", funFact: "Alien was released in 1979, directed by Ridley Scott, and Ripley was played by Sigourney Weaver. The film is famous for its creature design, created without anyone modelling the alien in full, and for the famous line written by the writer Dan O'Bannon: in space no one can hear you scream. It was a massive financial risk for 20th Century Fox, who partly financed it by mortgaging the company's Los Angeles studio." },
  { category: "Movies", difficulty: "EASY", question: "Which detective created by Arthur Conan Doyle is famous for the line 'Elementary, my dear Watson'?", options: JSON.stringify(["Sherlock Holmes","Hercule Poirot","Philip Marlowe","Inspector Morse"]), correctAnswer: "Sherlock Holmes", funFact: "Sherlock Holmes first appeared in A Study in Scarlet in 1887, and the exact phrase elementary, my dear Watson does not appear in Conan Doyle's original stories, but the modern films and television turned it into shorthand for clear thinking. Holmes is estimated to appear in more than 250 films, series and episodes, making him one of the most persistent characters in fiction. The stories were illustrated by Sidney Paget, whose images defined how Holmes looks." },
  { category: "Movies", difficulty: "EASY", question: "Which animated film follows a rat who dreams of becoming a chef in Paris?", options: JSON.stringify(["Ratatouille","Flushed Away","Chicken Run","Bee Movie"]), correctAnswer: "Ratatouille", funFact: "Ratatouille was released by Pixar in 2007 and is named after the French dish of the same name, which the film treats as a celebration of cooking rather than a joke. It is one of the few animated films with a fully kitchen-based setting and almost no outdoor scenes. Remy the rat was modelled partly on the movements of the chef Pierre Kuffler, whom the food consultant consulted." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which 1975 film about a man-eating shark made Steven Spielberg a major director?", options: JSON.stringify(["Jaws","E.T.","Close Encounters of the Third Kind","The Exorcist"]), correctAnswer: "Jaws", funFact: "Jaws was based on Peter Benchley's novel and was released before most of its effects were finished, so Spielberg was forced to show less of the shark than he wanted. The film is credited with inventing the summer blockbuster, and its theme song, a two-note motif by John Williams, is one of the most recognised pieces of film music ever written. It was also the first film to gross more than 100 million dollars at the box office." },
  { category: "Movies", difficulty: "MEDIUM", question: "Which actor played the Joker in Christopher Nolan's 'The Dark Knight'?", options: JSON.stringify(["Heath Ledger","Joaquin Phoenix","Jack Nicholson","Jared Leto"]), correctAnswer: "Heath Ledger", funFact: "Heath Ledger won the Academy Award for Best Supporting Actor for the role, and it remains the only comic book character performance to win that award. He prepared by living in character, keeping a diary and not speaking to his family for months, and died in 2008, a year after the film's release. Christopher Nolan has said he had to be extremely careful in casting someone who could handle such intensity, and the role is regarded as the high point of his career." },
  { category: "Movies", difficulty: "HARD", question: "Which 1941 film directed by Orson Welles pioneered the 'deep focus' style of cinematography?", options: JSON.stringify(["Citizen Kane","The Maltese Falcon","Casablanca","Gone with the Wind"]), correctAnswer: "Citizen Kane", funFact: "Deep focus places foreground, middle ground and background all in sharp focus, which allowed Welles to compose complex images in which the visual detail carries meaning. The film is also the most cited influence on the films of directors as different as Jean-Luc Godard, Martin Scorsese and Christopher Nolan. The opening shot, a slow zoom through an unlit room, is still discussed in film schools six decades later." },
  { category: "Movies", difficulty: "HARD", question: "Which 1939 film features the line 'There's no place like home'?", options: JSON.stringify(["The Wizard of Oz","Gone with the Wind","The Thin Man","Stagecoach"]), correctAnswer: "The Wizard of Oz", funFact: "The Wizard of Oz was the first film with a complete original score composed specifically for it, rather than assembled from existing music, and that score is in the public domain in the United States while the film is not. The Kansas scenes were shot in sepia and the Oz scenes in Technicolor, a deliberate choice that made the fantasy land feel as unreal as it looks. The ruby slippers were originally silver in the book." },
  { category: "Music", difficulty: "EASY", question: "Which large stringed instrument is played with the fingers and typically has 47 strings?", options: JSON.stringify(["Harp","Piano","Cello","Accordion"]), correctAnswer: "Harp", funFact: "A modern concert harp has 47 strings, giving it a range of six and a half octaves, and each string produces a single note so the instrument has no pedals or levers in the traditional form. The oldest surviving harps date back about 4,000 years to ancient Egypt and Mesopotamia. The pedal harp was developed in the early 18th century, and it is the instrument of choice in the orchestra for showing off in solos." },
  { category: "Music", difficulty: "EASY", question: "Which genre of music originated in the Bronx in the 1970s, built on breakbeats, rapping and DJing?", options: JSON.stringify(["Hip-hop","Jazz","Techno","Country"]), correctAnswer: "Hip-hop", funFact: "Hip-hop grew out of the block parties and sound systems of the Bronx in the early 1970s, and is often described as four separate elements: DJing, MCing, graffiti and breaking. The first commercially successful hip-hop recording was Sugarhill Gang's Rapper Delight in 1979, which sampled a funk bassline. The Bronx is now a UNESCO World Heritage site for the role of hip-hop in global culture." },
  { category: "Music", difficulty: "EASY", question: "How many lines does a standard stave have?", options: JSON.stringify(["Three","Four","Five","Six"]), correctAnswer: "Five", funFact: "The five-line stave grew out of medieval notation and was standardised in the 16th century, but early music was often written on six lines. The lines are named from bottom to top: E, G, B, D and F, which is the basis of the system that allows a singer or player to read a melody. The treble clef, so called because it resembles a stylized G, fixed those two reference points in place." },
  { category: "Music", difficulty: "MEDIUM", question: "Which singer was nicknamed the 'Material Girl'?", options: JSON.stringify(["Madonna","Whitney Houston","Cher","Cyndi Lauper"]), correctAnswer: "Madonna", funFact: "The nickname comes from her 1984 hit song Material Girl, whose chorus repeats the phrase, and Madonna has said she chose it because the word material is about both wealth and belongings, which is a joke at her own expense. She is one of the best-selling recording artists in history and was the first woman to top the Billboard Hot 100. She has also repeatedly reinvented herself musically, from dance-pop to disco to country." },
  { category: "Music", difficulty: "MEDIUM", question: "Which composer wrote the opera 'The Magic Flute'?", options: JSON.stringify(["Mozart","Rossini","Verdi","Wagner"]), correctAnswer: "Mozart", funFact: "The Magic Flute was Mozart's final opera, completed shortly before his death in 1791, and it was written for a popular suburban theatre in Vienna rather than the court. Its plot mixes serious Masonic ideas about tolerance and enlightenment with comic scenes for a mixed audience. The work is still regularly performed today, and the aria from it became a reliable encore for generations of tenors." },
  { category: "Music", difficulty: "HARD", question: "Which composer wrote 'The Rite of Spring'?", options: JSON.stringify(["Igor Stravinsky","Claude Debussy","Richard Strauss","Anton Bruckner"]), correctAnswer: "Igor Stravinsky", funFact: "The Rite of Spring was premiered in 1913, and the audience reportedly reacted so badly to its heavy, irregular rhythms and pounding percussion that a riot was rumoured. Stravinsky later said the audience differences were about dancing, not the music. Its score is built on layers of repeated rhythmic patterns that accumulate rather than a melody, which is why it changed the way composers thought about orchestral writing." },
  { category: "Music", difficulty: "HARD", question: "What is the name of the tuning system that allows all instruments to play at the same pitch despite their different sizes?", options: JSON.stringify(["Just intonation","Equal temperament","Meantone temperament","Pythagorean tuning"]), correctAnswer: "Equal temperament", funFact: "In equal temperament, every octave is divided into twelve equal steps, so a piece can be played in any key without going out of tune, at the cost of some intervals sounding slightly pure-but-unstable. This is what makes it possible to transpose a piece and to build the piano as a single instrument with 88 keys that can play every key at once. In just intonation, some intervals sound purer but a single piece can only use a few keys." },
  { category: "Animals", difficulty: "EASY", question: "What is the name for the aquatic larva of a frog?", options: JSON.stringify(["Tadpole","Nymph","Maggot","Larvace"]), correctAnswer: "Tadpole", funFact: "A tadpole hatches from a frog's egg with a tail and no legs, and over several weeks it grows hind legs, then front legs, while its tail is gradually absorbed. The metamorphosis is triggered by thyroid hormone, which is why tadpoles sometimes metamorphose early if they are exposed to it. Frogs have been declining worldwide since the 1970s, largely because of habitat loss and pollution." },
  { category: "Animals", difficulty: "EASY", question: "Which sea creature has eight arms and is widely regarded as one of the most intelligent invertebrates?", options: JSON.stringify(["Octopus","Squid","Jellyfish","Starfish"]), correctAnswer: "Octopus", funFact: "Octopuses have three hearts, blue copper-based blood, and each arm contains its own cluster of neurons, so a lot of their movement is decided without a central brain. They can open jars, escape cages, and change colour and skin texture in a fraction of a second to match their surroundings. A 2021 study found that cut-off arms still respond to stimuli, and the arms can be regrown." },
  { category: "Animals", difficulty: "EASY", question: "Which flightless bird of the Southern Hemisphere has a black and white tuxedo-like appearance?", options: JSON.stringify(["Penguin","Ostrich","Emu","Kiwi"]), correctAnswer: "Penguin", funFact: "Not all penguins are black and white, but the familiar image comes largely from the emperor penguin, which is the tallest species and lives around Antarctica. Penguins are more comfortable in water than on land, and their dense feathers and a layer of fat keep them warm in freezing water. They are unusual among birds in that the males usually incubate the egg, huddling in huge groups through Antarctic winter." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which Australian marsupial has fingerprints that are nearly indistinguishable from a human's?", options: JSON.stringify(["Koala","Kangaroo","Possum","Wombat"]), correctAnswer: "Koala", funFact: "Koala fingerprints are so similar to human fingerprints that, decades after they were first described, some crime units reportedly use them to distinguish which prints found at a scene belong to humans. A koala's grip is extraordinarily strong, and its hands have two opposable thumbs, so it can hold a eucalyptus branch firmly while it sleeps for up to 20 hours a day. Eucalyptus leaves are toxic to most animals, but koalas are able to digest them." },
  { category: "Animals", difficulty: "MEDIUM", question: "Which fish uses electric discharges to navigate and hunt in the murky waters of the Amazon?", options: JSON.stringify(["Electric eel","Piranha","Arapaima","Stingray"]), correctAnswer: "Electric eel", funFact: "The electric eel is not actually an eel but a knifefish, and it can deliver a shock of up to 600 volts, strong enough to stun a horse. It hunts by sending out weak electrical signals and reading the distortions they make when something nearby moves. It is so well adapted to the electric life that its heart stops when it is out of water, which is how fishers in the Amazon keep their catch alive in the river." },
  { category: "Animals", difficulty: "HARD", question: "What is the name of the glowing lure organ carried by deep-sea anglerfish?", options: JSON.stringify(["Escapium","Esca","Photic organ","Tentacle"]), correctAnswer: "Esca", funFact: "The esca is the modified first dorsal spine of the anglerfish, tipped with a bulb full of bioluminescent bacteria that the fish cannot produce itself. The fish dangles it in the dark to lure small fish within striking range. Almost all anglerfish found by fishermen are females, and the tiny males found in some species are fused to the female's body, reduced to little more than a pair of gonads." },
  { category: "Animals", difficulty: "HARD", question: "Which land-living crustacean is famous for stealing coconuts and has the strongest grip of any animal relative to its size?", options: JSON.stringify(["Coconut crab","King crab","Hooded shrimp","Ghost crab"]), correctAnswer: "Coconut crab", funFact: "Coconut crabs can lift objects weighing several kilograms, and their pincers generate the strongest force of any limb measured relative to body size, though the tips of the claws are among the sharpest and hardest structures in the animal kingdom. They are also among the few animals that seem to learn by using tools, carrying leaves to their burrows to keep them cool. They are protected in many places because they are a favoured food for the coconut crab's main predators, humans." },
  { category: "General Knowledge", difficulty: "EASY", question: "How many minutes are there in a full day?", options: JSON.stringify(["360","1440","720","2400"]), correctAnswer: "1440", funFact: "A day is 24 hours of 60 minutes, so 1,440 minutes, and it is the largest unit of time used in common speech that does not vary. Until the 19th century, different cities kept their own local time based on the sun, which meant a train journey in Britain could pass through several different times in a single day. Standard time zones were introduced to make railway timetables workable." },
  { category: "General Knowledge", difficulty: "EASY", question: "What is the largest country in the world by land area?", options: JSON.stringify(["Canada","Russia","China","United States"]), correctAnswer: "Russia", funFact: "Russia spans eleven time zones across two continents, Europe and Asia, and covers about 17 million square kilometres, roughly the size of the whole of Europe. It is followed by Canada, China and the United States, the only other countries larger than about 9 million square kilometres. Russia has roughly 144,000 rivers longer than 500 metres, and Lake Baikal, the world's deepest lake, holds about a fifth of unfrozen fresh water on Earth." },
  { category: "General Knowledge", difficulty: "EASY", question: "How many degrees are there in a full circle?", options: JSON.stringify(["90","180","360","720"]), correctAnswer: "360", funFact: "A full circle is 360 degrees, a convention that comes from the Babylonian sexagesimal system, which is also where 60 seconds to the minute and 60 minutes to the hour come from. Degrees remain part of everyday vocabulary, though pure mathematics prefers radians, since a full circle is simply 2 pi of them. The Babylonians also worked in base 60, which is why 360, 60 and 24 all keep turning up in measurement." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "How many time zones does Russia span?", options: JSON.stringify(["Eleven","Seven","Five","Three"]), correctAnswer: "Eleven", funFact: "Russia spans eleven time zones from Kaliningrad, in the European part, to the far east, where the sun can be 17 hours ahead of Moscow. There have been attempts to shorten the country to fewer zones, and Russia briefly experimented with permanent summer time to reduce the number of clock changes. Only the United States' overseas territories and the Arctic reach further north, and no other country has as many zones." },
  { category: "General Knowledge", difficulty: "MEDIUM", question: "What is the name for a whole number that can only be divided evenly by 1 and itself?", options: JSON.stringify(["A prime number","A square number","A perfect number","A composite number"]), correctAnswer: "A prime number", funFact: "Prime numbers are the building blocks of all other whole numbers, because any number can be broken down into a product of primes, and 2 is the only even prime, since every other even number is divisible by 2. Euclid proved over two thousand years ago that there are infinitely many primes, and most of the mathematics of encryption depends on the difficulty of factoring large numbers into them. It is not known whether every large odd number can be written as a prime plus a square number." },
  { category: "General Knowledge", difficulty: "HARD", question: "Which sequence of numbers begins 0, 1, 1, 2, 3, 5, 8, where each number is the sum of the two before it?", options: JSON.stringify(["The triangular numbers","The Fibonacci sequence","The Lucas sequence","The Catalan numbers"]), correctAnswer: "The Fibonacci sequence", funFact: "The sequence is named after Leonardo of Pisa, better known as Fibonacci, who described it in 1202 while travelling in what is now Algeria. It turns up in the number of spirals in a sunflower head, in the arrangement of pinecones, and in the branching of trees, at least approximately, because the real growth of plants is far messier than the model. The golden ratio, 1.618, emerges naturally as the sequence approaches it." },
  { category: "General Knowledge", difficulty: "HARD", question: "What is the name for a number that equals the sum of its proper factors, excluding itself?", options: JSON.stringify(["A prime number","A perfect number","A square number","A triangular number"]), correctAnswer: "A perfect number", funFact: "The first perfect numbers are 6, because 1 plus 2 plus 3 equals 6, and 28, because 1 plus 2 plus 4 plus 7 plus 14 equals 28. The next is 496. Nobody has ever proved whether there are infinitely many of them, and every perfect number found so far is even, so the existence of odd perfect numbers is one of the oldest unsolved problems in mathematics." },
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which coffee shop is the central setting of the sitcom 'Friends'?", options: JSON.stringify(["Central Perk","The Coffee House","Central Coffee","MacLaren's"]), correctAnswer: "Central Perk", funFact: "Central Perk was a real café on Greenwich Avenue in Manhattan, and the show's creators shot the first episodes there before moving to a set, which is one of the earliest examples of a sitcom's title location being a real place. The six main characters were deliberately made a group of contrasting adults rather than teenagers, which was unusual for the era. Friends has been credited with helping revive American sitcoms in the 1990s." },
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which anime series is set at a school for aspiring superheroes, and features the character Izuku Midoriya?", options: JSON.stringify(["My Hero Academia","One Punch Man","Jujutsu Kaisen","Demon Slayer"]), correctAnswer: "My Hero Academia", funFact: "The series premise is that most people in its world have superpowers, and its main character is born quirkless, which means he has to work far harder than everyone else. It began as a manga in 2014 and became one of the biggest anime in the world, and it deliberately parodies the superhero genre it borrows from. Its creator Kohei Horikoshi has said the story was partly inspired by his own experience of struggling at school." },
  { category: "TV Shows & Anime", difficulty: "EASY", question: "Which animated cartoon features a cat and a mouse endlessly chasing each other?", options: JSON.stringify(["Tom and Jerry","Bugs Bunny","Road Runner","Sylvester and Tweety"]), correctAnswer: "Tom and Jerry", funFact: "Tom and Jerry was created in 1940 by William Hanna and Joseph Barbera, who went on to found Hanna-Barbera, the studio behind the first television cartoon dynasty. The series is remarkable because it was made on three-strip Technicolor, an expensive process, and the pair were originally named Tom and Jerry, before public domain claims forced them to be renamed. The two characters never speak, but they communicate constantly, which is the heart of the comedy." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "In which anime does Izuku Midoriya attend U.A. High School?", options: JSON.stringify(["My Hero Academia","Tokyo Ghoul","Blue Exorcist","Jujutsu Kaisen"]), correctAnswer: "My Hero Academia", funFact: "The school is a fictional private academy in the series' world, funded by the hero commission, which is why the students wear reinforced uniforms and study to become professional superheroes. The name was chosen partly because U.A. High echoes the initials of the United States, hinting at the American superhero tradition the story is a commentary on. The school building itself is modelled on a real Japanese high school campus." },
  { category: "TV Shows & Anime", difficulty: "MEDIUM", question: "Which mockumentary sitcom follows a group of office workers at a paper company in Scranton, Pennsylvania?", options: JSON.stringify(["The Office","Parks and Recreation","Brooklyn Nine-Nine","Superstore"]), correctAnswer: "The Office", funFact: "The Office was the American adaptation of a British comedy of the same name, and it is shot in a single fixed camera angle with no laugh track, which made it a departure from how sitcoms were filmed at the time. The show ran for nine seasons, making it the longest-running American primetime live-action sitcom at the time of its ending. Its spin-off, web series An Oral History of The Office, ran longer in total episode count than the show itself." },
  { category: "TV Shows & Anime", difficulty: "HARD", question: "Which anime features a half-demon and a priestess of a powerful shrine travelling together through feudal Japan?", options: JSON.stringify(["Inuyasha","Rurouni Kenshin","Bleach","Sailor Moon"]), correctAnswer: "Inuyasha", funFact: "Inuyasha is based on the legend of the half-demon lord Inu no Taisho, a figure from the 14th century, and the story has the two leads repeatedly fight together and then fall out. The Shikon Jewel is the object both sides are hunting, and its protection is the main driver of the plot. The series ran from 2000 to 2004, and its success was part of the reason the studio Sunrise became known for long-running shonen fantasy." },
  { category: "TV Shows & Anime", difficulty: "HARD", question: "Which Spanish heist drama follows a gang called the Royal Bank of Spain, led by a character nicknamed 'The Professor'?", options: JSON.stringify(["Money Heist","Prison Break","The Wire","Breaking Bad"]), correctAnswer: "Money Heist", funFact: "Money Heist, originally called La Casa de Papel, was released in 2017 and became Netflix's most watched non-English-language series at the time. The plot centres on a heist of the Royal Mint of Spain, and its tension comes from the rules the Professor imposes on the gang, who wear identical red jumpsuits and masks based on Dalí. The show returned for two more parts years later, a very long time after the story had already been resolved." }
];

const expandedQuestions = [];
Object.entries(rawQuestions).forEach(([category, difficulties]) => {
  Object.entries(difficulties).forEach(([difficulty, list]) => {
    list.forEach((item) => {
      expandedQuestions.push({
        category,
        difficulty,
        question: item.q,
        options: JSON.stringify(item.o),
        correctAnswer: item.a,
        funFact: item.f
      });
    });
  });
});

async function main() {
  console.log("Seeding database...");

  console.log("Seeding achievements...");
  for (const ach of ACHIEVEMENTS) {
    await prisma.achievement.upsert({
      where: { title: ach.title },
      update: {},
      create: ach
    });
  }

  console.log("Seeding daily missions...");
  for (const mission of DAILY_MISSIONS) {
    await prisma.dailyMission.upsert({
      where: { title: mission.title },
      update: {},
      create: mission
    });
  }

  const allQuestions = [...expandedQuestions, ...extraQuestions, ...extraQuestions2, ...extraQuestions3, ...extraQuestions4, ...extraQuestions5, ...extraQuestions6, ...extraQuestions7, ...extraQuestions8];
  console.log(`Seeding ${allQuestions.length} questions with fun facts...`);
  await prisma.triviaQuestion.deleteMany({});
  for (const q of allQuestions) {
    await prisma.triviaQuestion.create({ data: q });
  }

  console.log("Database seeded successfully!");
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(async () => { await prisma.$disconnect(); });
